INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C1','sci',4,1,'u1',1,'자석 다트 놀이와 규칙 — 다트 놀이 = 과녁판에 다트 핀을 던져 맞히는 놀이 · 모둠별 과녁판(열 칸) · 정한 순서대로 각자 두 번씩 · 맞힌 칸 수를 셈 · 같은 칸에 여러 개 붙어도 하나로 · 선에 붙으면 더 가까운 쪽 칸으로',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C2','sci',4,1,'u1',1,'자석 다트 핀의 좋은 점 — 붙는 부분이 자석 · 과녁판에 착 붙었다가 쉽게 뗌 · 떼어도 자국이 남지 않음 · 뾰족하지 않아 안전',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C3','sci',4,1,'u1',1,'놀이 안전과 태도 — 세게 던지지 않고 사람을 향해 던지지 않음 · 일반 자석은 던지면 깨질 수 있어 자석 다트 핀만 · 모둠끼리 겨루기보다 자석에 관심과 흥미를 가짐',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C4','sci',4,1,'u1',1,'붙는 까닭 생각하기 — 다트 핀과 과녁판이 서로 끌어당기는 것 같다(추측) · 칠판 이름표·시간표·냉장고 메모처럼 자석을 써 본 경험 · 도화지 아래 막대자석을 움직이면 철사가 든 빵 끈이 따라 움직임',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C5','sci',4,1,'u1',2,'자석에 붙는 물체 — 철로 된 물체(철 클립·철 집게·철 캔·철 나사못·철 옷핀)는 자석에 붙음',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C6','sci',4,1,'u1',2,'자석에 붙지 않는 물체 — 유리·나무·플라스틱·고무·종이로 된 물체(유리구슬·나무젓가락·플라스틱 자·고무지우개·색종이)는 자석에 붙지 않음',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C7','sci',4,1,'u1',2,'붙지 않는 금속 — 알루미늄 포일·알루미늄 캔·동전처럼 금속이어도 자석에 붙지 않는 것이 있음 — 모든 금속이 붙는 것이 아님',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C8','sci',4,1,'u1',2,'물질로 판단하기 — 물체의 이름이 아니라 어떤 물질로 만들어졌는지로 판단 · 같은 종류의 물체라도 물질에 따라 붙거나 붙지 않음(철 캔과 알루미늄 캔)',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C9','sci',4,1,'u1',2,'붙는 부분과 붙지 않는 부분이 모두 있는 물체 — 가위 — 철로 된 날은 붙고 플라스틱 손잡이는 붙지 않음 · 공책 — 철 스프링은 붙고 종이는 붙지 않음 · 여러 부분에 자석을 가까이 해 봄',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C10','sci',4,1,'u1',2,'예상하고 관찰하기와 안전 — 어떤 물체가 붙을지 먼저 예상한 뒤 자석을 가까이 해 관찰 · 뾰족한 부분·깨지는 유리 조심 · 전자 기기·카드에 자석을 가까이 하지 않음',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C11','sci',4,1,'u1',2,'섞인 물체 골라내기 — 철 구슬과 플라스틱 구슬이 섞여 있을 때 자석을 가까이 하면 철 구슬만 붙어 나와 쉽게 골라냄',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C12','sci',4,1,'u1',3,'조금 떨어져 있어도 끌어당김 — 자석과 자석에 붙는 물체는 조금 떨어져 있어도 서로 끌어당김 · 실을 묶은 철 클립이 자석에 닿지 않고 공중에 떠 있음',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C13','sci',4,1,'u1',3,'너무 멀면 — 자석을 아주 멀리 하면 클립이 바닥으로 떨어짐 · 유리컵 밖 자석을 멀리 떨어뜨리면 컵 속 철 집게가 컵 바닥으로 떨어짐',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C14','sci',4,1,'u1',3,'사이에 물체가 있어도 — 자석과 자석에 붙는 물체 사이에 종이·얇은 플라스틱판·얇은 유리판 등이 있어도 끌어당기는 힘이 작용함 · 얇은 유리컵 속 철 집게를 컵 밖 자석으로 움직임',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C15','sci',4,1,'u1',3,'서로 끌어당김 — 자석만 끌어당기는 것이 아니라 자석과 자석에 붙는 물체가 서로 끌어당김 · 자석보다 무거운 철 물체에 가까이 하면 자석을 잡은 손이 끌려가는 느낌',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C16','sci',4,1,'u1',3,'힘을 이용해 꺼내기 — 손이 닿지 않는 책장 아래 철 나사못은 얇은 막대 끝에 자석을 고정해 꺼냄 · 자석이 아닌 물체(플라스틱 자·나무젓가락)는 클립을 끌어당기지 못함',ARRAY['[4과09-01] 자석과 여러 가지 물체를 가까이 했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다(지도서 성취기준 · W7 확인)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C17','sci',4,1,'u1',4,'자석의 극 — 자석에서 철로 된 물체를 끌어당기는 힘이 가장 센 부분 = 자석의 극 · 양쪽 끝부분 · 클립 상자에서 들어 올리면 클립이 가장 많이 붙은 곳(극이 아닌 곳에도 조금 붙을 수 있음)',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C18','sci',4,1,'u1',4,'극은 항상 두 개 — 자석의 극은 항상 두 개이며 N극과 S극으로 나타냄 · 막대자석·말굽자석·동전 모양 자석·고리 자석 모두 두 개',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C19','sci',4,1,'u1',4,'같은 극과 다른 극 — 같은 극끼리는 서로 밀어 내고(N극끼리도 S극끼리도) 다른 극끼리는 서로 끌어당김 · 고리 자석이 떠 있는 까닭 · 같은 극끼리 마주 보게 밀면 멀어짐 · 고리 자석을 같은 극끼리 마주 보게 쌓으면 높게 쌓임',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C20','sci',4,1,'u1',4,'고리 자석의 극 추리 — 빨대에 끼운 고리 자석의 한 면에 막대자석 N극·S극을 차례로 가까이 → 밀어 내면 같은 극, 끌어당기면 다른 극으로 그 면의 극을 추리 · 반대쪽 면은 다른 극',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C21','sci',4,1,'u1',4,'반으로 자르면과 안전 — 자석을 반으로 자르면 극이 나뉘지 않고 양쪽 끝에 각각 N극과 S극이 있는 새 자석 두 개가 됨 · 극은 색칠한 쪽에만 있는 것이 아님 · 두 자석 사이에 손이 끼지 않게 조심',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C22','sci',4,1,'u1',5,'나침반 — 나침반 = 방향을 찾을 때 쓰는 도구 · 평평한 곳에 놓고 주변에 자석·철로 된 물체가 없는지 확인 · 바늘이 멈출 때까지 기다리면 일정한 방향을 가리킴',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C23','sci',4,1,'u1',5,'자석을 가까이 했을 때 바늘의 움직임 — N극을 가까이 하면 빨간색 부분이 N극에서 멀어짐 · S극을 가까이 하면 S극 쪽으로 다가옴 · 자석을 멀리 하면 원래 방향으로 되돌아감 · 주변에서 움직여도 같은 규칙',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C24','sci',4,1,'u1',5,'나침반 바늘도 자석 — 바늘의 빨간색 부분 = N극 · 바늘과 자석의 극도 서로 밀어 내거나 끌어당김 · 철이라면 어느 극에든 끌려와야 하는데 N극에는 밀려남 → 바늘도 N극과 S극이 있는 자석',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C25','sci',4,1,'u1',5,'주변 자석을 확인하는 까닭 — 바늘이 자석의 성질을 가지고 있어 주변 자석의 영향을 받으면 정확한 방향을 가리킬 수 없음 · 자석을 가까이 한 채 오래 두지 않음',ARRAY['[4과09-02] 자석과 자석을 가까이 했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다(지도서 성취기준 · W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C26','sci',4,1,'u1',6,'자석을 이용한 생활용품 — 자석 단추 가방(여닫기 쉬움) · 자석 클립 통(떨어져도 안 쏟아짐) · 주방 기구 걸이 · 커튼 끈(매듭 없이 고정) · 냉장고 문(쉽게 여닫음) · 냉장고 자석(붙였다 뗌) · 스마트 기기 덮개(화면 보호·접어 고정) · 쪽지를 테이프 자국 없이 붙였다 뗌',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C27','sci',4,1,'u1',6,'자석과 철이 끌어당기는 성질 이용 — 자석 클립 통·자석 주방 기구 걸이·냉장고 자석·자석 드라이버(끝에 자석, 철 나사못) — 자석과 자석에 붙는 물체가 서로 끌어당기는 성질',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C28','sci',4,1,'u1',6,'다른 극끼리 끌어당기는 성질 이용 — 자석 창문 닦이(유리창 안쪽과 바깥쪽 닦이의 자석) · 자석 단추 가방 — 자석의 다른 극끼리 서로 끌어당기는 성질',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C29','sci',4,1,'u1',6,'붙는 물체만 걸 수 있음 — 자석 걸이에는 자석에 붙는 물체만 걸 수 있음 · 나무 주걱은 자석 주방 기구 걸이에 붙지 않음',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C30','sci',4,1,'u1',6,'양치 컵 걸이와 조사하기 — 자석 양치 컵 걸이 — 컵 바닥과 걸이의 붙이는 부분에 자석, 컵을 매달아 물이 고이지 않아 물때·곰팡이가 잘 생기지 않음 · 조사할 때 필요한 정보만 찾고 출처를 밝힘 · 아주 센 자석은 스마트 기기 화면에 가까이 하지 않음',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C31','sci',4,1,'u1',7,'장치 설계의 차례 — 불편했던 경험 떠올리기 → 이용할 자석의 성질 → 자석을 넣을 부분 → 편리한 점 → 보완 · 어떤 상황에서 쓰는지·어느 부분에 자석·어떤 성질을 정리 · 자석 신발 끈 매듭기(다른 극끼리 끌어당겨 끈을 묶지 않고 고정)',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C32','sci',4,1,'u1',7,'쓰러지지 않는 물통 — 물감으로 그림을 그릴 때 · 물통 바닥에 자석, 받침대는 철 · 자석과 철로 된 물체가 서로 끌어당기는 성질 · 실수로 쳐도 쉽게 쓰러지지 않음 · 보완 = 붓에 철 조각을 붙이고 물통 옆면에 자석을 붙여 붓 보관',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C33','sci',4,1,'u1',7,'친구들이 설계한 장치 — 자석 수저 받침대(철 수저 보관) · 자석 식탁(철 그릇·수저를 쳐도 떨어지거나 쓰러지지 않음) · 자석 허리띠(철 공구·나사못 보관) · 자석 이불(네 귀퉁이 자석으로 갤 때 꼭 붙음)',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C34','sci',4,1,'u1',7,'설계 평가와 소통 — 평가 기준 = 자석의 성질을 잘 이용했나 · 생활을 편리하게 하나 · 특징이 설계도에 잘 표현되었나 · 반드시 만들기로 이어질 필요 없음 · 이미 있는 장치를 바꾸어도 좋음 · 자유롭게 제안하고 비난하지 않으며 잘한 점을 칭찬',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C35','sci',4,1,'u1',7,'자석 말판 놀이로 되짚기 — 말판 칸 문제로 단원 되짚기 — 극은 두 개 · 같은 극 밀어 냄 · 얇은 유리판이 있어도 끌어당김 · 철 집게만 붙음 · 다른 극 끌어당김 · 나침반 바늘과 자석 사이 힘',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C36','sci',4,1,'u1',8,'우주 쓰레기 청소 — 우주 쓰레기 = 고장 난 우주선의 부품이나 더 이상 쓰지 않는 인공위성 · 인공위성·우주선·우주 정거장과 부딪칠 수 있음 · 자석의 성질로 우주 쓰레기를 모아 처리하는 장치를 개발 중 · 인공위성 = 로켓으로 쏘아 올려 지구 둘레를 도는 장치',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C37','sci',4,1,'u1',8,'몸속 작은 로봇 — 몸 안에 들어간 아주 작은 로봇을 몸 밖에서 조종 · 몸속을 자세히 살펴보고 필요한 곳에 약을 정확하게 전달',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C38','sci',4,1,'u1',8,'액체 자석 — 물이나 기름처럼 흐르는 액체이지만 자석의 성질을 가짐 · 의료 기구, 지폐의 위조를 막는 자석 잉크에 쓰임',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u1-C39','sci',4,1,'u1',8,'여러 분야의 자석과 관심 — 캔 분리수거(철 캔을 자석으로 골라냄) · 프로펠러(열·소음·떨림이 거의 없음) · 아주 큰 자석부터 눈에 보이지 않는 자석까지 다양 · 원리보다 자석이 여러 분야에 쓰임에 관심 · 관련된 일을 하는 사람',ARRAY['[4과09-03] 자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다(지도서 성취기준 · W7 확인)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X01','sci',4,'u1',ARRAY['SC4-1-u1-C1']::text[],'다트 놀이를 엉뚱하게 안다(손으로 눌러 꽂기·주고받기)','과녁판에 던져 맞혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X02','sci',4,'u1',ARRAY['SC4-1-u1-C1']::text[],'놀이 규칙을 잘못 안다(같은 칸 여러 개를 모두 셈·선 위는 안 셈·순서 없이 던짐)','하나로 · 가까운 칸') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X03','sci',4,'u1',ARRAY['SC4-1-u1-C3']::text[],'자석 다트 놀이를 모둠끼리 이기는 승부로만 여긴다','흥미와 관심이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X04','sci',4,'u1',ARRAY['SC4-1-u1-C3']::text[],'다트 핀을 세게·사람을 향해 던지거나 일반 자석을 던져도 된다고 여긴다','살살 · 다트 핀만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X05','sci',4,'u1',ARRAY['SC4-1-u1-C2']::text[],'자석 다트 핀의 좋은 점을 엉뚱하게 안다(뾰족해서 꽂힘·자국이 남음)','붙는 부분이 자석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X06','sci',4,'u1',ARRAY['SC4-1-u1-C4']::text[],'다트 핀이 붙는 까닭을 엉뚱하게 짐작한다(풀·물기·바람·끈적한 과녁판)','서로 끌어당기는 것 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X07','sci',4,'u1',ARRAY['SC4-1-u1-C4']::text[],'도화지 아래에서 자석을 움직여도 빵 끈이 따라오지 않거나 스스로 움직인다고 여긴다','자석을 따라와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X08','sci',4,'u1',ARRAY['SC4-1-u1-C7']::text[],'금속으로 된 물체는 모두 자석에 붙는다고 여긴다','알루미늄·동전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X09','sci',4,'u1',ARRAY['SC4-1-u1-C6']::text[],'유리·나무·플라스틱·고무·종이로 된 물체가 자석에 붙는다고 여긴다','철이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X10','sci',4,'u1',ARRAY['SC4-1-u1-C5']::text[],'철로 된 물체가 자석에 붙지 않는다고 여긴다','철은 붙어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X11','sci',4,'u1',ARRAY['SC4-1-u1-C8']::text[],'물체의 이름·모양·색만 보고 자석에 붙는지 판단한다','무엇으로 만들었나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X12','sci',4,'u1',ARRAY['SC4-1-u1-C9']::text[],'한 물체는 모두 붙거나 모두 붙지 않는다고 여긴다(가위 손잡이도 붙음)','부분마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X13','sci',4,'u1',ARRAY['SC4-1-u1-C11']::text[],'섞인 구슬을 골라내는 방법을 잘못 안다(플라스틱 구슬이 붙음·하나씩 줍기·물에 넣기)','자석에 철만 붙어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X14','sci',4,'u1',ARRAY['SC4-1-u1-C10']::text[],'예상 없이 관찰하거나 전자 기기·카드에 자석을 대는 등 안전을 지키지 않는다','예상 · 안전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X15','sci',4,'u1',ARRAY['SC4-1-u1-C12']::text[],'자석과 물체가 닿아 있어야만 끌어당기는 힘이 작용한다고 여긴다','조금 떨어져도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X16','sci',4,'u1',ARRAY['SC4-1-u1-C13']::text[],'자석이 아무리 멀어도 철 물체를 끌어당긴다고 여긴다','너무 멀면 떨어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X17','sci',4,'u1',ARRAY['SC4-1-u1-C14']::text[],'사이에 종이·얇은 플라스틱판·얇은 유리판이 있으면 힘이 작용하지 않는다고 여긴다','사이에 있어도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X18','sci',4,'u1',ARRAY['SC4-1-u1-C15']::text[],'자석만 철 물체를 끌어당기고 철은 자석을 끌어당기지 않는다고 여긴다','서로 끌어당겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X19','sci',4,'u1',ARRAY['SC4-1-u1-C16']::text[],'자석이 아닌 물체(플라스틱 자·나무젓가락)도 철 클립을 끌어당긴다고 여긴다','자석이 있어야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X20','sci',4,'u1',ARRAY['SC4-1-u1-C17']::text[],'자석의 극이 가운데이거나 모든 부분에 골고루 있다고 여긴다','양쪽 끝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X21','sci',4,'u1',ARRAY['SC4-1-u1-C18']::text[],'자석의 극이 한 개이거나 모양에 따라 극의 수가 다르다고 여긴다','항상 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X22','sci',4,'u1',ARRAY['SC4-1-u1-C19']::text[],'같은 극끼리 끌어당기고 다른 극끼리 밀어 낸다고 뒤바꾼다','같은 극 밀어 냄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X23','sci',4,'u1',ARRAY['SC4-1-u1-C19']::text[],'극끼리의 힘을 엉뚱하게 안다(N극끼리만 밀어 냄·아무 힘 없음·가벼워서 뜸)','N극끼리도 S극끼리도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X24','sci',4,'u1',ARRAY['SC4-1-u1-C20']::text[],'밀려나거나 끌려온 모습으로 고리 자석 면의 극을 거꾸로 추리한다','밀면 같은 극') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X25','sci',4,'u1',ARRAY['SC4-1-u1-C21']::text[],'자석을 반으로 자르면 N극만·S극만 있는 자석이 되거나 극이 사라진다고 여긴다','새 자석 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X26','sci',4,'u1',ARRAY['SC4-1-u1-C18','SC4-1-u1-C21']::text[],'극은 빨간색으로 칠한 쪽에만 있다고 여긴다','색이 아니라 끝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X27','sci',4,'u1',ARRAY['SC4-1-u1-C21']::text[],'두 자석 사이에 손을 넣거나 자석을 부딪치게 하는 등 안전을 지키지 않는다','손 끼임 조심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X28','sci',4,'u1',ARRAY['SC4-1-u1-C24']::text[],'나침반 바늘은 자석이 아니라 자석에 붙는 철이라고 여긴다','N극에 밀려나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X29','sci',4,'u1',ARRAY['SC4-1-u1-C23']::text[],'N극과 S극을 가까이 할 때 바늘의 빨간색 부분이 움직이는 방향을 뒤바꾼다','N극 멀어짐 · S극 다가옴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X30','sci',4,'u1',ARRAY['SC4-1-u1-C23']::text[],'자석을 치워도 바늘이 돌아가지 않거나 자석의 위치가 바뀌면 규칙이 바뀐다고 여긴다','원래 방향 · 같은 규칙') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X31','sci',4,'u1',ARRAY['SC4-1-u1-C24']::text[],'나침반 바늘의 빨간색 부분을 S극으로 여긴다','빨간색은 N극') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X32','sci',4,'u1',ARRAY['SC4-1-u1-C22','SC4-1-u1-C25']::text[],'나침반 주변에 자석이나 철이 있어도 괜찮다고 여기거나 흔들며 읽는다','주변 확인 · 멈출 때까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X33','sci',4,'u1',ARRAY['SC4-1-u1-C22']::text[],'나침반을 방향 찾기와 상관없는 도구로 여기거나 돌고 있는 바늘을 읽는다','방향을 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X34','sci',4,'u1',ARRAY['SC4-1-u1-C26']::text[],'생활용품에서 자석이 있는 곳이나 편리한 점을 엉뚱하게 안다','자석이 있어서 편리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X35','sci',4,'u1',ARRAY['SC4-1-u1-C29']::text[],'자석 걸이에는 나무·플라스틱 등 어떤 물체든 붙일 수 있다고 여긴다','붙는 물체만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X36','sci',4,'u1',ARRAY['SC4-1-u1-C27','SC4-1-u1-C28']::text[],'자석과 철이 끌어당기는 성질과 다른 극끼리 끌어당기는 성질을 뒤바꾸거나 유리가 자석에 붙는다고 여긴다','무엇과 무엇이 끌어당기나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X37','sci',4,'u1',ARRAY['SC4-1-u1-C28']::text[],'자석 단추·창문 닦이가 같은 극끼리 끌어당겨 붙는다고 여긴다','다른 극끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X38','sci',4,'u1',ARRAY['SC4-1-u1-C30']::text[],'자석 양치 컵 걸이의 자석 위치나 편리한 점을 엉뚱하게 안다','매달면 물이 안 고여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X39','sci',4,'u1',ARRAY['SC4-1-u1-C30']::text[],'조사할 때 출처 없이 아무 정보나 옮기거나 센 자석을 화면에 댄다','필요한 정보 · 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X40','sci',4,'u1',ARRAY['SC4-1-u1-C34']::text[],'자석과 상관없는 해결책(무겁게·끈으로 묶기)도 자석 장치 설계라고 여긴다','자석의 성질을 이용') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X41','sci',4,'u1',ARRAY['SC4-1-u1-C34']::text[],'설계는 반드시 직접 만들거나 세상에 없던 것만 해야 한다고 여긴다','만들지 않아도 · 바꾸어도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X42','sci',4,'u1',ARRAY['SC4-1-u1-C34']::text[],'친구의 설계를 놀리거나 잘한 점을 찾지 않는다','잘한 점 칭찬') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X43','sci',4,'u1',ARRAY['SC4-1-u1-C31']::text[],'설계의 차례를 뒤바꾸거나 불편한 경험 없이 시작하고, 장치가 해결한 불편함을 엉뚱하게 안다','불편 경험부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X44','sci',4,'u1',ARRAY['SC4-1-u1-C32']::text[],'쓰러지지 않는 물통에서 자석·철의 자리나 이용한 성질을 잘못 안다(받침대가 플라스틱·같은 극 밀어 냄)','바닥 자석 · 철 받침대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X45','sci',4,'u1',ARRAY['SC4-1-u1-C32']::text[],'설계를 보완하는 방법을 엉뚱하게 안다(붓을 물통에 담가 둠·풀로 붙임)','철 조각과 자석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X46','sci',4,'u1',ARRAY['SC4-1-u1-C33']::text[],'친구들이 설계한 장치의 쓰임이나 붙는 물체를 잘못 안다','철 수저 · 철 공구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X47','sci',4,'u1',ARRAY['SC4-1-u1-C36']::text[],'우주 쓰레기를 엉뚱하게 알거나 문제가 없다고 여긴다(우주 생물·별)','쓰지 않는 인공위성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X48','sci',4,'u1',ARRAY['SC4-1-u1-C37']::text[],'몸속 작은 로봇이 하는 일이나 조종하는 곳을 잘못 안다','몸 밖에서 조종') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X49','sci',4,'u1',ARRAY['SC4-1-u1-C38']::text[],'흐르는 것은 자석의 성질을 가질 수 없다고 여기거나 액체 자석의 쓰임을 잘못 안다','흘러도 자석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X50','sci',4,'u1',ARRAY['SC4-1-u1-C39']::text[],'자석은 교실에서만 쓰이거나 막대자석 모양뿐이라고 여긴다','여러 분야 · 여러 크기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u1-X51','sci',4,'u1',ARRAY['SC4-1-u1-C39']::text[],'캔 분리수거에서 알루미늄 캔이 자석에 붙어 골라진다고 여긴다','철 캔만 붙어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#1','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C1',1,'mc','auto','다트 놀이는 어떤 놀이인가요?',ARRAY['SC4-1-u1-X01','SC4-1-u1-X03']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C1","difficulty":1,"kind":"mc","stem":"다트 놀이는 어떤 놀이인가요?","options":[{"t":"과녁판에 다트 핀을 던져 맞히는 놀이","correct":true},{"t":"다트 핀을 과녁판에 손으로 눌러 꽂는 놀이","mis":"SC4-1-u1-X01"},{"t":"과녁판을 누가 더 빨리 그리는지 겨루는 놀이","mis":"SC4-1-u1-X03"},{"t":"다트 핀을 모둠끼리 주고받는 놀이","mis":"SC4-1-u1-X01"}],"explanation":["놀이 이름을 떠올려요.","던져서 맞혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#2','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C3',1,'ox','auto','자석 다트 핀은 친구가 있는 쪽을 향해 던져도 돼요.',ARRAY['SC4-1-u1-X04']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C3","difficulty":1,"kind":"ox","stem":"자석 다트 핀은 친구가 있는 쪽을 향해 던져도 돼요.","answer":"X","reason_options":[{"t":"던진 다트 핀에 친구가 맞아 다칠 수 있기 때문에","correct":true},{"t":"자석 다트 핀은 뾰족하지 않아서 맞아도 괜찮기 때문에","mis":"SC4-1-u1-X04"}],"mis":"SC4-1-u1-X04","explanation":["던지는 방향을 떠올려요.","사람 쪽은 위험해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#3','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C2',1,'mc','auto','자석 다트 핀에서 과녁판에 붙는 부분은 무엇으로 되어 있나요?',ARRAY['SC4-1-u1-X05','SC4-1-u1-X06']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C2","difficulty":1,"kind":"mc","stem":"자석 다트 핀에서 과녁판에 붙는 부분은 무엇으로 되어 있나요?","options":[{"t":"자석","correct":true},{"t":"뾰족한 핀 끝","mis":"SC4-1-u1-X05"},{"t":"끈적한 풀","mis":"SC4-1-u1-X06"},{"t":"젖은 스펀지","mis":"SC4-1-u1-X06"}],"explanation":["다트 핀 이름을 봐요.","「자석」 다트 핀이에요.","자석이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#4','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C1',1,'sa','auto','같은 칸에 다트 핀 두 개가 붙었어요. 몇 칸을 맞힌 것으로 세나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u1-C1","difficulty":1,"kind":"sa","stem":"같은 칸에 다트 핀 두 개가 붙었어요. 몇 칸을 맞힌 것으로 세나요? 숫자로 쓰세요.","answer":["1"],"explanation":["규칙 셋째 줄을 읽어요.","여러 개여도 하나예요.","1칸이에요."],"asset":{"type":"passage","lines":["모둠별로 과녁판에 열 개의 칸을 그렸어요.","정한 순서대로 한 사람이 두 번씩 던져요.","같은 칸에 여러 개가 붙어도 하나로 세요.","선 위에 붙으면 더 가까운 쪽 칸으로 세요.","모두 던진 뒤 맞힌 칸의 수를 세어요."],"title":"자석 다트 놀이 규칙"},"mis":"SC4-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#5','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C1',2,'mc','auto','선 위에 다트 핀이 붙었을 때에는 어떻게 세나요?',ARRAY['SC4-1-u1-X02']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C1","difficulty":2,"kind":"mc","stem":"선 위에 다트 핀이 붙었을 때에는 어떻게 세나요?","options":[{"t":"더 가까운 쪽 칸으로 센다","correct":true},{"t":"맞히지 못한 것으로 친다","mis":"SC4-1-u1-X02"},{"t":"선에 닿은 두 칸을 모두 센다","mis":"SC4-1-u1-X02"},{"t":"다시 던진다","mis":"SC4-1-u1-X02"}],"explanation":["규칙 넷째 줄을 읽어요.","가까운 쪽이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠별로 과녁판에 열 개의 칸을 그렸어요.","정한 순서대로 한 사람이 두 번씩 던져요.","같은 칸에 여러 개가 붙어도 하나로 세요.","선 위에 붙으면 더 가까운 쪽 칸으로 세요.","모두 던진 뒤 맞힌 칸의 수를 세어요."],"title":"자석 다트 놀이 규칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#6','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C2',2,'match','auto','자석 다트 핀의 특징과 그 좋은 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u1-C2","difficulty":2,"kind":"match","stem":"자석 다트 핀의 특징과 그 좋은 점을 알맞게 이으세요.","pairs":[{"l":"붙는 부분이 자석이에요","r":"과녁판에 착 붙어요"},{"l":"쉽게 뗄 수 있어요","r":"여러 번 다시 던질 수 있어요"},{"l":"떼어도 자국이 없어요","r":"과녁판이 상하지 않아요"},{"l":"끝이 뾰족하지 않아요","r":"다칠 위험이 적어요"}],"mis":"SC4-1-u1-X05","explanation":["다트 핀을 떠올려요.","붙였다 떼요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#7','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C4',2,'mc','auto','자석 다트 핀이 과녁판에 붙는 까닭을 가장 알맞게 생각한 것은 무엇인가요?',ARRAY['SC4-1-u1-X06']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C4","difficulty":2,"kind":"mc","stem":"자석 다트 핀이 과녁판에 붙는 까닭을 가장 알맞게 생각한 것은 무엇인가요?","options":[{"t":"다트 핀과 과녁판이 서로 끌어당기는 것 같다","correct":true},{"t":"다트 핀 끝에 풀이 묻어 있는 것 같다","mis":"SC4-1-u1-X06"},{"t":"과녁판이 젖어서 달라붙는 것 같다","mis":"SC4-1-u1-X06"},{"t":"바람이 다트 핀을 밀어 주는 것 같다","mis":"SC4-1-u1-X06"}],"explanation":["착 붙는 모습을 떠올려요.","서로 당기는 것 같아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#8','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C1',2,'ox','auto','자석 다트 놀이에서는 정한 순서대로 한 사람이 두 번씩 던져요.',ARRAY['SC4-1-u1-X02']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C1","difficulty":2,"kind":"ox","stem":"자석 다트 놀이에서는 정한 순서대로 한 사람이 두 번씩 던져요.","answer":"O","reason_options":[{"t":"놀이 규칙에서 순서를 정해 각자 두 번씩 던지기로 했기 때문에","correct":true},{"t":"먼저 던지는 사람이 원하는 만큼 던질 수 있기 때문에","mis":"SC4-1-u1-X02"}],"mis":"SC4-1-u1-X02","explanation":["규칙 둘째 줄을 읽어요.","두 번씩이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["모둠별로 과녁판에 열 개의 칸을 그렸어요.","정한 순서대로 한 사람이 두 번씩 던져요.","같은 칸에 여러 개가 붙어도 하나로 세요.","선 위에 붙으면 더 가까운 쪽 칸으로 세요.","모두 던진 뒤 맞힌 칸의 수를 세어요."],"title":"자석 다트 놀이 규칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#9','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C4',2,'mc','auto','우리 주변에서 자석을 써 본 경험으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X06']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C4","difficulty":2,"kind":"mc","stem":"우리 주변에서 자석을 써 본 경험으로 알맞은 것은 무엇인가요?","options":[{"t":"칠판에 이름표를 자석으로 붙였다","correct":true},{"t":"색종이를 풀로 공책에 붙였다","mis":"SC4-1-u1-X06"},{"t":"셀로판테이프로 그림을 벽에 붙였다","mis":"SC4-1-u1-X06"},{"t":"끈으로 풍선을 묶었다","mis":"SC4-1-u1-X06"}],"explanation":["칠판을 떠올려요.","이름표를 붙였어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_basic#10','sci',4,1,'u1','L01','g4_1_sci_u1_L01_basic','lesson_basic','SC4-1-u1-C3',3,'mc','auto','자석 다트 놀이를 할 때 가장 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u1-X04','SC4-1-u1-X03']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C3","difficulty":3,"kind":"mc","stem":"자석 다트 놀이를 할 때 가장 알맞은 행동은 무엇인가요?","options":[{"t":"살살 던지고, 던지는 곳 앞으로 친구가 지나가지 않는지 살핀다","correct":true},{"t":"멀리 날아가도록 있는 힘껏 던진다","mis":"SC4-1-u1-X04"},{"t":"다트 핀 대신 교실의 막대자석을 던진다","mis":"SC4-1-u1-X04"},{"t":"우리 모둠이 꼭 이기도록 친구를 재촉한다","mis":"SC4-1-u1-X03"}],"explanation":["안전을 떠올려요.","살살 던져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#1','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C1',2,'blank','auto','「같은 칸에 다트 핀이 여러 개 붙어도 (    )로 세요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X02']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C1","difficulty":2,"kind":"blank","stem":"「같은 칸에 다트 핀이 여러 개 붙어도 (    )로 세요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"하나","correct":true},{"t":"두 개","mis":"SC4-1-u1-X02"},{"t":"세 개","mis":"SC4-1-u1-X02"},{"t":"여러 개","mis":"SC4-1-u1-X02"}],"explanation":["놀이 규칙을 떠올려요.","여러 개여도 한 칸이에요.","하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#2','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C2',2,'mc','auto','자석 다트 핀이 뾰족한 다트 핀과 다른 점은 무엇인가요?',ARRAY['SC4-1-u1-X05']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C2","difficulty":2,"kind":"mc","stem":"자석 다트 핀이 뾰족한 다트 핀과 다른 점은 무엇인가요?","options":[{"t":"과녁판에 꽂히지 않고 착 붙었다가 쉽게 떨어진다","correct":true},{"t":"과녁판에 구멍을 내며 깊이 꽂힌다","mis":"SC4-1-u1-X05"},{"t":"떼고 나면 과녁판에 자국이 남는다","mis":"SC4-1-u1-X05"},{"t":"끝이 뾰족해서 더 조심해야 한다","mis":"SC4-1-u1-X05"}],"explanation":["붙는 부분을 떠올려요.","자석이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#3','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C3',3,'error','auto','놀이를 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X03','SC4-1-u1-X06','SC4-1-u1-X04']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C3","difficulty":3,"kind":"error","stem":"놀이를 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「우리 모둠이 가장 많이 맞혔으니 우리가 이긴 거야.」","correct":true,"mis_target":"SC4-1-u1-X03"},{"t":"친구 나 — 「다트 핀이 왜 과녁판에 붙는지 궁금해졌어.」","mis":"SC4-1-u1-X06"},{"t":"친구 다 — 「살살 던져서 아무도 다치지 않았어.」","mis":"SC4-1-u1-X04"}],"explanation":["놀이의 뜻을 떠올려요.","겨루기보다 흥미예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#4','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C4',3,'mc','auto','도화지 아래에서 막대자석을 움직였더니 도화지 위 철사가 든 빵 끈이 따라 움직였어요. 그 까닭으로 가장 알맞은 생각은 무엇인가요?',ARRAY['SC4-1-u1-X07','SC4-1-u1-X06']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C4","difficulty":3,"kind":"mc","stem":"도화지 아래에서 막대자석을 움직였더니 도화지 위 철사가 든 빵 끈이 따라 움직였어요. 그 까닭으로 가장 알맞은 생각은 무엇인가요?","options":[{"t":"빵 끈과 막대자석이 서로 끌어당기는 것 같다","correct":true},{"t":"빵 끈이 스스로 움직이는 것 같다","mis":"SC4-1-u1-X07"},{"t":"도화지가 빵 끈을 밀어 내는 것 같다","mis":"SC4-1-u1-X07"},{"t":"물감이 빵 끈을 끌고 가는 것 같다","mis":"SC4-1-u1-X06"}],"explanation":["빵 끈이 따라왔어요.","자석 쪽으로 와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#5','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C2',3,'ox','auto','자석 다트 핀은 과녁판에서 떼어도 자국이 남지 않아요.',ARRAY['SC4-1-u1-X05']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C2","difficulty":3,"kind":"ox","stem":"자석 다트 핀은 과녁판에서 떼어도 자국이 남지 않아요.","answer":"O","reason_options":[{"t":"뾰족하게 꽂히지 않고 자석으로 붙기 때문에","correct":true},{"t":"다트 핀이 과녁판에 구멍을 내며 꽂히기 때문에","mis":"SC4-1-u1-X05"}],"mis":"SC4-1-u1-X05","explanation":["붙는 방법을 떠올려요.","꽂지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#6','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C1',3,'mc','auto','다트 핀이 두 칸 사이의 선 위에 붙었는데 왼쪽 칸에 더 가까워요. 어떻게 세나요?',ARRAY['SC4-1-u1-X02']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C1","difficulty":3,"kind":"mc","stem":"다트 핀이 두 칸 사이의 선 위에 붙었는데 왼쪽 칸에 더 가까워요. 어떻게 세나요?","options":[{"t":"왼쪽 칸을 맞힌 것으로 센다","correct":true},{"t":"오른쪽 칸을 맞힌 것으로 센다","mis":"SC4-1-u1-X02"},{"t":"두 칸을 모두 맞힌 것으로 센다","mis":"SC4-1-u1-X02"},{"t":"아무 칸도 맞히지 못한 것으로 센다","mis":"SC4-1-u1-X02"}],"explanation":["규칙 넷째 줄을 읽어요.","더 가까운 쪽이에요.","왼쪽 칸이에요."],"asset":{"type":"passage","lines":["모둠별로 과녁판에 열 개의 칸을 그렸어요.","정한 순서대로 한 사람이 두 번씩 던져요.","같은 칸에 여러 개가 붙어도 하나로 세요.","선 위에 붙으면 더 가까운 쪽 칸으로 세요.","모두 던진 뒤 맞힌 칸의 수를 세어요."],"title":"자석 다트 놀이 규칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#7','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C3',3,'mc','auto','선생님이 일반 자석이 아니라 꼭 자석 다트 핀으로 놀이하라고 한 까닭은 무엇일까요?',ARRAY['SC4-1-u1-X04','SC4-1-u1-X03','SC4-1-u1-X05']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C3","difficulty":3,"kind":"mc","stem":"선생님이 일반 자석이 아니라 꼭 자석 다트 핀으로 놀이하라고 한 까닭은 무엇일까요?","options":[{"t":"일반 자석을 던지면 떨어지면서 깨질 수 있기 때문에","correct":true},{"t":"일반 자석이 과녁판에 더 잘 붙기 때문에","mis":"SC4-1-u1-X04"},{"t":"자석 다트 핀으로 해야 이길 수 있기 때문에","mis":"SC4-1-u1-X03"},{"t":"일반 자석은 뾰족해서 꽂히기 때문에","mis":"SC4-1-u1-X05"}],"explanation":["던지면 어떻게 될까요?","깨질 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#8','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C3',4,'mc','auto','친구가 「다트 놀이는 무조건 많이 맞힌 모둠이 최고야!」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X04','SC4-1-u1-X03','SC4-1-u1-X02']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C3","difficulty":4,"kind":"mc","stem":"친구가 「다트 놀이는 무조건 많이 맞힌 모둠이 최고야!」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「누가 이기는지보다 다트 핀이 왜 붙는지 궁금해하며 즐겁게 놀이하는 게 더 중요해.」","correct":true},{"t":"「맞아, 이기려면 세게 던져야 해.」","mis":"SC4-1-u1-X04"},{"t":"「맞아, 진 모둠은 다시 하면 안 돼.」","mis":"SC4-1-u1-X03"},{"t":"「놀이 규칙은 몰라도 돼.」","mis":"SC4-1-u1-X02"}],"explanation":["놀이의 뜻을 떠올려요.","흥미와 호기심이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#9','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C4',4,'mc','auto','칠판에 이름표를 붙일 때와 자석 다트 핀이 과녁판에 붙을 때의 같은 점을 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-1-u1-X06','SC4-1-u1-X05']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C4","difficulty":4,"kind":"mc","stem":"칠판에 이름표를 붙일 때와 자석 다트 핀이 과녁판에 붙을 때의 같은 점을 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"둘 다 자석과 붙는 쪽이 서로 끌어당기는 것 같다","correct":true},{"t":"둘 다 풀로 붙인 것이다","mis":"SC4-1-u1-X06"},{"t":"둘 다 뾰족한 끝으로 꽂은 것이다","mis":"SC4-1-u1-X05"},{"t":"둘 다 바람이 불어서 붙은 것이다","mis":"SC4-1-u1-X06"}],"explanation":["둘 다 자석을 써요.","착 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L01_challenge#10','sci',4,1,'u1','L01','g4_1_sci_u1_L01_challenge','lesson_challenge','SC4-1-u1-C2',4,'essay','teacher','자석 다트 핀이 뾰족한 다트 핀보다 좋은 점 두 가지를 쓰고, 다트 핀이 과녁판에 붙는 까닭을 생각해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C2","difficulty":4,"kind":"essay","stem":"자석 다트 핀이 뾰족한 다트 핀보다 좋은 점 두 가지를 쓰고, 다트 핀이 과녁판에 붙는 까닭을 생각해 쓰세요.","answer_guide":{"answer":"예: 자석 다트 핀은 과녁판에 착 붙었다가 쉽게 뗄 수 있고, 떼어도 자국이 남지 않는다. 또 끝이 뾰족하지 않아 안전하다. 다트 핀과 과녁판이 서로 끌어당기기 때문에 붙는 것 같다.","scoring_points":["좋은 점 두 가지를 썼는가","붙는 까닭을 끌어당김으로 짐작해 썼는가","자기 생각을 자유롭게 썼는가"]},"explanation":["다트 핀을 떠올려요.","좋은 점을 써요.","까닭을 짐작해 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#1','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C5',1,'mc','auto','막대자석을 가까이 했을 때 자석에 붙는 물체는 무엇인가요?',ARRAY['SC4-1-u1-X09']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C5","difficulty":1,"kind":"mc","stem":"막대자석을 가까이 했을 때 자석에 붙는 물체는 무엇인가요?","options":[{"t":"철 클립","correct":true},{"t":"색종이","mis":"SC4-1-u1-X09"},{"t":"고무지우개","mis":"SC4-1-u1-X09"},{"t":"유리구슬","mis":"SC4-1-u1-X09"}],"explanation":["무엇으로 만들었나요?","철로 된 것이에요.","철 클립이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#2','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C7',1,'ox','auto','금속으로 된 물체는 모두 자석에 붙어요.',ARRAY['SC4-1-u1-X08']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C7","difficulty":1,"kind":"ox","stem":"금속으로 된 물체는 모두 자석에 붙어요.","answer":"X","reason_options":[{"t":"알루미늄 포일이나 동전처럼 금속이어도 자석에 붙지 않는 것이 있기 때문에","correct":true},{"t":"금속은 모두 철로 만들어졌기 때문에","mis":"SC4-1-u1-X08"}],"mis":"SC4-1-u1-X08","explanation":["알루미늄 포일을 떠올려요.","금속인데 안 붙어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#3','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C6',1,'mc','auto','자석에 붙지 않는 물체끼리 묶은 것은 무엇인가요?',ARRAY['SC4-1-u1-X10']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C6","difficulty":1,"kind":"mc","stem":"자석에 붙지 않는 물체끼리 묶은 것은 무엇인가요?","options":[{"t":"나무젓가락, 플라스틱 자","correct":true},{"t":"철 클립, 나무젓가락","mis":"SC4-1-u1-X10"},{"t":"철 집게, 철 클립","mis":"SC4-1-u1-X10"},{"t":"플라스틱 자, 철 집게","mis":"SC4-1-u1-X10"}],"explanation":["철이 아닌 것을 찾아요.","나무와 플라스틱이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#4','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C5',1,'sa','auto','철 클립과 철 집게는 모두 자석에 붙어요. 두 물체는 무엇으로 만들어졌나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u1-C5","difficulty":1,"kind":"sa","stem":"철 클립과 철 집게는 모두 자석에 붙어요. 두 물체는 무엇으로 만들어졌나요? 한 글자로 쓰세요.","answer":["철"],"explanation":["물체 이름을 봐요.","앞에 같은 말이 있어요.","철이에요."],"mis":"SC4-1-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#5','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C7',2,'mc','auto','알루미늄 포일에 막대자석을 가까이 하면 어떻게 되나요?',ARRAY['SC4-1-u1-X08','SC4-1-u1-X12']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C7","difficulty":2,"kind":"mc","stem":"알루미늄 포일에 막대자석을 가까이 하면 어떻게 되나요?","options":[{"t":"금속이지만 자석에 붙지 않는다","correct":true},{"t":"금속이라서 자석에 붙는다","mis":"SC4-1-u1-X08"},{"t":"자석을 밀어 낸다","mis":"SC4-1-u1-X08"},{"t":"반짝이는 부분만 붙는다","mis":"SC4-1-u1-X12"}],"explanation":["넷째 줄을 읽어요.","붙지 않았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["철 클립 — 붙었다","색종이 — 붙지 않았다","고무지우개 — 붙지 않았다","알루미늄 포일 — 붙지 않았다","유리구슬 — 붙지 않았다","철 집게 — 붙었다"],"title":"막대자석을 가까이 했을 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#6','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C9',2,'match','auto','물체의 부분과 자석에 붙는지를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u1-C9","difficulty":2,"kind":"match","stem":"물체의 부분과 자석에 붙는지를 알맞게 이으세요.","pairs":[{"l":"가위의 날","r":"철로 되어 있어 자석에 붙어요"},{"l":"가위의 손잡이","r":"플라스틱으로 되어 있어 붙지 않아요"},{"l":"공책의 스프링","r":"철로 된 둥근 고리가 자석에 붙어요"},{"l":"공책의 속지","r":"종이로 되어 있어 붙지 않아요"}],"mis":"SC4-1-u1-X12","explanation":["부분마다 물질이 달라요.","철은 붙어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#7','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C8',2,'mc','auto','자석에 붙는지 알아볼 때 가장 먼저 살펴야 할 것은 무엇인가요?',ARRAY['SC4-1-u1-X11','SC4-1-u1-X08']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C8","difficulty":2,"kind":"mc","stem":"자석에 붙는지 알아볼 때 가장 먼저 살펴야 할 것은 무엇인가요?","options":[{"t":"물체가 어떤 물질로 만들어졌는지","correct":true},{"t":"물체의 이름이 무엇인지","mis":"SC4-1-u1-X11"},{"t":"물체의 색깔이 무엇인지","mis":"SC4-1-u1-X11"},{"t":"물체가 얼마나 반짝이는지","mis":"SC4-1-u1-X08"}],"explanation":["이름이 아니에요.","물질을 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#8','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C6',2,'ox','auto','유리구슬은 단단해서 자석에 붙어요.',ARRAY['SC4-1-u1-X09']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C6","difficulty":2,"kind":"ox","stem":"유리구슬은 단단해서 자석에 붙어요.","answer":"X","reason_options":[{"t":"유리로 된 물체는 자석에 붙지 않기 때문에","correct":true},{"t":"단단한 물체는 모두 자석에 붙기 때문에","mis":"SC4-1-u1-X09"}],"mis":"SC4-1-u1-X09","explanation":["다섯째 줄을 읽어요.","붙지 않았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["철 클립 — 붙었다","색종이 — 붙지 않았다","고무지우개 — 붙지 않았다","알루미늄 포일 — 붙지 않았다","유리구슬 — 붙지 않았다","철 집게 — 붙었다"],"title":"막대자석을 가까이 했을 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#9','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C10',2,'mc','auto','자석에 붙는 물체를 알아볼 때 가장 알맞은 차례는 무엇인가요?',ARRAY['SC4-1-u1-X14','SC4-1-u1-X11']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C10","difficulty":2,"kind":"mc","stem":"자석에 붙는 물체를 알아볼 때 가장 알맞은 차례는 무엇인가요?","options":[{"t":"어떤 물체가 붙을지 먼저 예상한 뒤 자석을 가까이 해 관찰한다","correct":true},{"t":"예상하지 않고 결과만 적는다","mis":"SC4-1-u1-X14"},{"t":"자석을 휴대 전화에 대 보며 시작한다","mis":"SC4-1-u1-X14"},{"t":"물체 이름을 외운 뒤 관찰하지 않는다","mis":"SC4-1-u1-X11"}],"explanation":["예상이 먼저예요.","그다음 관찰해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_basic#10','sci',4,1,'u1','L02','g4_1_sci_u1_L02_basic','lesson_basic','SC4-1-u1-C11',3,'mc','auto','철 구슬과 플라스틱 구슬이 섞여 있어요. 철 구슬만 쉽게 골라내는 방법은 무엇인가요?',ARRAY['SC4-1-u1-X13']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C11","difficulty":3,"kind":"mc","stem":"철 구슬과 플라스틱 구슬이 섞여 있어요. 철 구슬만 쉽게 골라내는 방법은 무엇인가요?","options":[{"t":"자석을 가까이 해 붙어 나오는 철 구슬만 모은다","correct":true},{"t":"구슬을 하나씩 손으로 집어 냄새를 맡는다","mis":"SC4-1-u1-X13"},{"t":"자석을 가까이 해 붙어 나오는 플라스틱 구슬을 모은다","mis":"SC4-1-u1-X13"},{"t":"구슬을 모두 물에 넣는다","mis":"SC4-1-u1-X13"}],"explanation":["철은 자석에 붙어요.","플라스틱은 안 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#1','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C5',2,'blank','auto','「(    )로 된 물체는 자석에 붙어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X09']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C5","difficulty":2,"kind":"blank","stem":"「(    )로 된 물체는 자석에 붙어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"철","correct":true},{"t":"유리","mis":"SC4-1-u1-X09"},{"t":"나무","mis":"SC4-1-u1-X09"},{"t":"고무","mis":"SC4-1-u1-X09"}],"explanation":["철 클립을 떠올려요.","한 글자예요.","철이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#2','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C9',2,'mc','auto','가위에서 자석에 붙는 부분은 어디인가요?',ARRAY['SC4-1-u1-X12','SC4-1-u1-X10']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C9","difficulty":2,"kind":"mc","stem":"가위에서 자석에 붙는 부분은 어디인가요?","options":[{"t":"철로 된 날","correct":true},{"t":"플라스틱 손잡이","mis":"SC4-1-u1-X12"},{"t":"가위 전체","mis":"SC4-1-u1-X12"},{"t":"붙는 부분이 없다","mis":"SC4-1-u1-X10"}],"explanation":["부분마다 봐요.","날은 철이에요.","날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#3','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C7',3,'error','auto','자석 실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X08','SC4-1-u1-X10','SC4-1-u1-X09']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C7","difficulty":3,"kind":"error","stem":"자석 실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「알루미늄 포일도 금속이니까 자석에 붙어.」","correct":true,"mis_target":"SC4-1-u1-X08"},{"t":"친구 가 — 「철 집게는 자석에 붙었어.」","mis":"SC4-1-u1-X10"},{"t":"친구 나 — 「색종이는 자석에 붙지 않았어.」","mis":"SC4-1-u1-X09"}],"explanation":["실험 결과를 봐요.","알루미늄 포일은 안 붙었어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["철 클립 — 붙었다","색종이 — 붙지 않았다","고무지우개 — 붙지 않았다","알루미늄 포일 — 붙지 않았다","유리구슬 — 붙지 않았다","철 집게 — 붙었다"],"title":"막대자석을 가까이 했을 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#4','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C8',3,'mc','auto','모양이 똑같은 두 캔 가운데 하나만 자석에 붙었어요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X11','SC4-1-u1-X08']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C8","difficulty":3,"kind":"mc","stem":"모양이 똑같은 두 캔 가운데 하나만 자석에 붙었어요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"두 캔을 만든 물질이 서로 다르기 때문에","correct":true},{"t":"캔은 모두 자석에 붙어야 하기 때문에","mis":"SC4-1-u1-X11"},{"t":"붙은 캔이 더 무겁기 때문에","mis":"SC4-1-u1-X11"},{"t":"붙은 캔이 더 반짝이기 때문에","mis":"SC4-1-u1-X08"}],"explanation":["모양이 아니에요.","물질을 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#5','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C9',3,'ox','auto','공책에 막대자석을 가까이 하면 스프링 부분만 붙어요.',ARRAY['SC4-1-u1-X12']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C9","difficulty":3,"kind":"ox","stem":"공책에 막대자석을 가까이 하면 스프링 부분만 붙어요.","answer":"O","reason_options":[{"t":"스프링은 철로 되어 있고 속지는 종이로 되어 있기 때문에","correct":true},{"t":"공책은 모두 종이로 되어 있어 어디에도 붙지 않기 때문에","mis":"SC4-1-u1-X12"}],"mis":"SC4-1-u1-X12","explanation":["공책의 부분을 봐요.","스프링은 철이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#6','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C7',3,'mc','auto','동전과 알루미늄 캔을 자석에 가까이 했을 때 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u1-X08','SC4-1-u1-X11']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C7","difficulty":3,"kind":"mc","stem":"동전과 알루미늄 캔을 자석에 가까이 했을 때 알 수 있는 것은 무엇인가요?","options":[{"t":"금속 가운데에도 자석에 붙지 않는 것이 있다","correct":true},{"t":"금속은 모두 자석에 붙는다","mis":"SC4-1-u1-X08"},{"t":"동전은 철로 만들어졌다","mis":"SC4-1-u1-X08"},{"t":"캔은 모두 자석에 붙지 않는다","mis":"SC4-1-u1-X11"}],"explanation":["둘 다 금속이에요.","그런데 안 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#7','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C10',3,'mc','auto','자석으로 실험할 때 가장 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u1-X14']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C10","difficulty":3,"kind":"mc","stem":"자석으로 실험할 때 가장 알맞은 행동은 무엇인가요?","options":[{"t":"유리구슬이나 뾰족한 클립을 조심해서 다루고, 휴대 전화나 카드에 자석을 가까이 하지 않는다","correct":true},{"t":"카드에 자석을 문질러 본다","mis":"SC4-1-u1-X14"},{"t":"유리구슬을 세게 부딪쳐 본다","mis":"SC4-1-u1-X14"},{"t":"휴대 전화 화면에 자석을 올려 둔다","mis":"SC4-1-u1-X14"}],"explanation":["안전을 떠올려요.","고장 날 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#8','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C8',4,'mc','auto','친구가 「병뚜껑은 모두 자석에 붙어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X11','SC4-1-u1-X08']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C8","difficulty":4,"kind":"mc","stem":"친구가 「병뚜껑은 모두 자석에 붙어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「병뚜껑이라도 무엇으로 만들었는지에 따라 붙기도 하고 붙지 않기도 해. 자석을 대 보자.」","correct":true},{"t":"「맞아, 이름이 같으면 모두 붙어.」","mis":"SC4-1-u1-X11"},{"t":"「병뚜껑은 금속이라 모두 붙어.」","mis":"SC4-1-u1-X08"},{"t":"「병뚜껑은 하나도 붙지 않아.」","mis":"SC4-1-u1-X11"}],"explanation":["이름이 아니라 물질이에요.","대 보면 알아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#9','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C11',4,'mc','auto','철 나사못과 플라스틱 단추가 바닥에 섞여 쏟아졌어요. 나사못만 빨리 모으려면 어떻게 하는 것이 좋을까요?',ARRAY['SC4-1-u1-X13']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C11","difficulty":4,"kind":"mc","stem":"철 나사못과 플라스틱 단추가 바닥에 섞여 쏟아졌어요. 나사못만 빨리 모으려면 어떻게 하는 것이 좋을까요?","options":[{"t":"자석을 바닥 가까이 움직여 붙어 나오는 나사못을 모은다","correct":true},{"t":"플라스틱 단추가 자석에 붙어 나오기를 기다린다","mis":"SC4-1-u1-X13"},{"t":"하나씩 이름을 부르며 손으로 줍는다","mis":"SC4-1-u1-X13"},{"t":"바닥에 물을 뿌려 나사못을 띄운다","mis":"SC4-1-u1-X13"}],"explanation":["나사못은 철이에요.","자석에 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L02_challenge#10','sci',4,1,'u1','L02','g4_1_sci_u1_L02_challenge','lesson_challenge','SC4-1-u1-C8',4,'essay','teacher','철 클립, 색종이, 알루미늄 포일, 철 집게를 자석에 붙는 것과 붙지 않는 것으로 나누고, 나눈 기준을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C8","difficulty":4,"kind":"essay","stem":"철 클립, 색종이, 알루미늄 포일, 철 집게를 자석에 붙는 것과 붙지 않는 것으로 나누고, 나눈 기준을 쓰세요.","answer_guide":{"answer":"예: 자석에 붙는 것은 철 클립과 철 집게이고, 붙지 않는 것은 색종이와 알루미늄 포일이다. 철로 된 물체는 자석에 붙고, 종이로 된 물체나 알루미늄처럼 철이 아닌 물질로 된 물체는 붙지 않기 때문이다.","scoring_points":["붙는 것과 붙지 않는 것을 바르게 나누었는가","물질(철)을 기준으로 썼는가","알루미늄 포일은 금속이어도 붙지 않음을 썼는가"]},"explanation":["실험을 떠올려요.","둘로 나눠요.","기준을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#1','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C12',1,'mc','auto','막대자석을 철 클립에서 조금 멀리 했을 때 클립은 어떻게 되었나요?',ARRAY['SC4-1-u1-X15']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C12","difficulty":1,"kind":"mc","stem":"막대자석을 철 클립에서 조금 멀리 했을 때 클립은 어떻게 되었나요?","options":[{"t":"공중에 떠 있었다","correct":true},{"t":"바로 바닥으로 떨어졌다","mis":"SC4-1-u1-X15"},{"t":"자석에서 더 멀어졌다","mis":"SC4-1-u1-X15"},{"t":"색깔이 바뀌었다","mis":"SC4-1-u1-X15"}],"explanation":["②를 읽어요.","떨어지지 않았어요.","공중에 떠 있었어요."],"asset":{"type":"passage","lines":["① 막대자석에 실을 묶은 철 클립을 붙였다.","② 자석을 조금 멀리 했더니 클립이 공중에 떠 있었다.","③ 사이에 색종이를 넣어도 클립은 떠 있었다.","④ 얇은 플라스틱판을 넣어도 클립은 떠 있었다.","⑤ 자석을 아주 멀리 했더니 클립이 떨어졌다."],"title":"실을 묶은 철 클립 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#2','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C14',1,'ox','auto','자석과 철 클립 사이에 색종이가 있으면 끌어당기는 힘이 작용하지 않아요.',ARRAY['SC4-1-u1-X17']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C14","difficulty":1,"kind":"ox","stem":"자석과 철 클립 사이에 색종이가 있으면 끌어당기는 힘이 작용하지 않아요.","answer":"X","reason_options":[{"t":"사이에 색종이가 있어도 클립이 공중에 떠 있었기 때문에","correct":true},{"t":"종이가 자석의 힘을 모두 막기 때문에","mis":"SC4-1-u1-X17"}],"mis":"SC4-1-u1-X17","explanation":["③을 읽어요.","그래도 떠 있었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 막대자석에 실을 묶은 철 클립을 붙였다.","② 자석을 조금 멀리 했더니 클립이 공중에 떠 있었다.","③ 사이에 색종이를 넣어도 클립은 떠 있었다.","④ 얇은 플라스틱판을 넣어도 클립은 떠 있었다.","⑤ 자석을 아주 멀리 했더니 클립이 떨어졌다."],"title":"실을 묶은 철 클립 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#3','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C13',1,'mc','auto','자석을 철 클립에서 아주 멀리 하면 클립은 어떻게 되나요?',ARRAY['SC4-1-u1-X16']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C13","difficulty":1,"kind":"mc","stem":"자석을 철 클립에서 아주 멀리 하면 클립은 어떻게 되나요?","options":[{"t":"바닥으로 떨어진다","correct":true},{"t":"계속 공중에 떠 있다","mis":"SC4-1-u1-X16"},{"t":"자석 쪽으로 날아온다","mis":"SC4-1-u1-X16"},{"t":"더 높이 떠오른다","mis":"SC4-1-u1-X16"}],"explanation":["⑤를 떠올려요.","너무 멀어요.","떨어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#4','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C15',1,'sa','auto','자석과 자석에 붙는 물체는 서로 밀어 내나요, 끌어당기나요? 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u1-C15","difficulty":1,"kind":"sa","stem":"자석과 자석에 붙는 물체는 서로 밀어 내나요, 끌어당기나요? 알맞은 말을 쓰세요.","answer":["끌어당겨요","끌어당긴다","끌어당겨","끌어당김"],"explanation":["클립이 끌려 왔어요.","서로 당겨요.","끌어당겨요."],"mis":"SC4-1-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#5','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C14',2,'mc','auto','얇은 유리컵 안에 철 집게를 넣고 컵 밖에서 막대자석을 움직였어요. 어떻게 될까요?',ARRAY['SC4-1-u1-X17','SC4-1-u1-X09']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C14","difficulty":2,"kind":"mc","stem":"얇은 유리컵 안에 철 집게를 넣고 컵 밖에서 막대자석을 움직였어요. 어떻게 될까요?","options":[{"t":"철 집게가 막대자석을 따라 움직인다","correct":true},{"t":"유리가 막아서 철 집게가 움직이지 않는다","mis":"SC4-1-u1-X17"},{"t":"철 집게가 컵 밖으로 튀어 나온다","mis":"SC4-1-u1-X17"},{"t":"막대자석이 유리컵에 붙는다","mis":"SC4-1-u1-X09"}],"explanation":["얇은 유리가 있어요.","그래도 힘이 작용해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#6','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C12',2,'match','auto','실험 단계와 클립의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u1-C12","difficulty":2,"kind":"match","stem":"실험 단계와 클립의 모습을 알맞게 이으세요.","pairs":[{"l":"자석에 클립을 붙여요","r":"클립이 자석 끝에 딱 붙어 있어요"},{"l":"자석을 조금 멀리 해요","r":"클립이 공중에 떠 있어요"},{"l":"사이에 색종이를 넣어요","r":"그래도 클립이 떠 있어요"},{"l":"자석을 아주 멀리 해요","r":"클립이 바닥으로 떨어져요"}],"mis":"SC4-1-u1-X16","explanation":["실험 차례를 읽어요.","거리를 봐요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 막대자석에 실을 묶은 철 클립을 붙였다.","② 자석을 조금 멀리 했더니 클립이 공중에 떠 있었다.","③ 사이에 색종이를 넣어도 클립은 떠 있었다.","④ 얇은 플라스틱판을 넣어도 클립은 떠 있었다.","⑤ 자석을 아주 멀리 했더니 클립이 떨어졌다."],"title":"실을 묶은 철 클립 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#7','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C15',2,'mc','auto','자석과 자석에 붙는 물체 사이의 힘을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u1-X18','SC4-1-u1-X15']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C15","difficulty":2,"kind":"mc","stem":"자석과 자석에 붙는 물체 사이의 힘을 바르게 말한 것은 무엇인가요?","options":[{"t":"자석과 철 물체가 서로 끌어당긴다","correct":true},{"t":"자석만 철 물체를 끌어당긴다","mis":"SC4-1-u1-X18"},{"t":"철 물체만 자석을 끌어당긴다","mis":"SC4-1-u1-X18"},{"t":"둘은 서로 아무 힘도 주고받지 않는다","mis":"SC4-1-u1-X15"}],"explanation":["「서로」가 중요해요.","둘 다 당겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#8','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C13',2,'ox','auto','유리컵 밖의 막대자석을 아주 멀리 떨어뜨리면 컵 속 철 집게는 컵 바닥으로 떨어져요.',ARRAY['SC4-1-u1-X16']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C13","difficulty":2,"kind":"ox","stem":"유리컵 밖의 막대자석을 아주 멀리 떨어뜨리면 컵 속 철 집게는 컵 바닥으로 떨어져요.","answer":"O","reason_options":[{"t":"너무 멀어지면 끌어당기는 힘이 철 집게에 미치지 못하기 때문에","correct":true},{"t":"자석은 아무리 멀어도 철을 끌어당기기 때문에","mis":"SC4-1-u1-X16"}],"mis":"SC4-1-u1-X16","explanation":["거리를 떠올려요.","너무 멀어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#9','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C16',2,'mc','auto','플라스틱 자를 철 클립에 가까이 했어요. 어떻게 될까요?',ARRAY['SC4-1-u1-X19']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C16","difficulty":2,"kind":"mc","stem":"플라스틱 자를 철 클립에 가까이 했어요. 어떻게 될까요?","options":[{"t":"클립이 끌려 오지 않는다","correct":true},{"t":"클립이 플라스틱 자에 붙는다","mis":"SC4-1-u1-X19"},{"t":"클립이 공중에 떠 있다","mis":"SC4-1-u1-X19"},{"t":"클립이 플라스틱 자를 밀어 낸다","mis":"SC4-1-u1-X19"}],"explanation":["플라스틱 자는 자석이 아니에요.","끌어당기지 못해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_basic#10','sci',4,1,'u1','L03','g4_1_sci_u1_L03_basic','lesson_basic','SC4-1-u1-C16',3,'mc','auto','손이 닿지 않는 책장 아래로 철 나사못이 들어갔어요. 가장 알맞은 방법은 무엇인가요?',ARRAY['SC4-1-u1-X19','SC4-1-u1-X16','SC4-1-u1-X17']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C16","difficulty":3,"kind":"mc","stem":"손이 닿지 않는 책장 아래로 철 나사못이 들어갔어요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"얇은 막대 끝에 자석을 고정해 책장 아래로 넣는다","correct":true},{"t":"나무젓가락만 책장 아래로 넣어 흔든다","mis":"SC4-1-u1-X19"},{"t":"자석을 책장 위에 올려놓고 기다린다","mis":"SC4-1-u1-X16"},{"t":"책장 아래에 색종이를 깔아 둔다","mis":"SC4-1-u1-X17"}],"explanation":["나사못은 철이에요.","자석을 가까이 가져가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#1','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C12',2,'blank','auto','「자석과 자석에 붙는 물체는 조금 (    ) 있어도 서로 끌어당겨요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X15']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C12","difficulty":2,"kind":"blank","stem":"「자석과 자석에 붙는 물체는 조금 (    ) 있어도 서로 끌어당겨요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"떨어져","correct":true},{"t":"닿아","mis":"SC4-1-u1-X15"},{"t":"붙어","mis":"SC4-1-u1-X15"},{"t":"젖어","mis":"SC4-1-u1-X15"}],"explanation":["클립이 떠 있었어요.","닿지 않았어요.","떨어져예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#2','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C14',2,'mc','auto','얇은 플라스틱판 위에 철 클립을 놓고 판 아래에서 자석을 움직이면 어떻게 될까요?',ARRAY['SC4-1-u1-X17','SC4-1-u1-X09']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C14","difficulty":2,"kind":"mc","stem":"얇은 플라스틱판 위에 철 클립을 놓고 판 아래에서 자석을 움직이면 어떻게 될까요?","options":[{"t":"클립이 자석을 따라 움직인다","correct":true},{"t":"플라스틱판 때문에 클립이 꼼짝하지 않는다","mis":"SC4-1-u1-X17"},{"t":"클립이 자석과 반대쪽으로 도망간다","mis":"SC4-1-u1-X17"},{"t":"플라스틱판이 자석에 붙는다","mis":"SC4-1-u1-X09"}],"explanation":["사이에 판이 있어요.","그래도 당겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#3','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C15',3,'error','auto','실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X18','SC4-1-u1-X15','SC4-1-u1-X17']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C15","difficulty":3,"kind":"error","stem":"실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「자석만 철을 끌어당기고, 철은 자석을 끌어당기지 않아.」","correct":true,"mis_target":"SC4-1-u1-X18"},{"t":"친구 가 — 「조금 떨어져 있어도 끌어당기는 힘이 작용해.」","mis":"SC4-1-u1-X15"},{"t":"친구 다 — 「사이에 얇은 플라스틱판이 있어도 힘이 작용해.」","mis":"SC4-1-u1-X17"}],"explanation":["「서로」를 떠올려요.","철도 당겨요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#4','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C15',3,'mc','auto','큰 철 문에 작은 자석을 가까이 가져가니 자석을 잡은 손이 문 쪽으로 끌려가는 느낌이 들었어요. 이것으로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u1-X18','SC4-1-u1-X15']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C15","difficulty":3,"kind":"mc","stem":"큰 철 문에 작은 자석을 가까이 가져가니 자석을 잡은 손이 문 쪽으로 끌려가는 느낌이 들었어요. 이것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"자석과 철 문이 서로 끌어당긴다","correct":true},{"t":"자석만 철 문을 끌어당긴다","mis":"SC4-1-u1-X18"},{"t":"철 문이 자석을 밀어 낸다","mis":"SC4-1-u1-X18"},{"t":"손이 저절로 움직인 것이다","mis":"SC4-1-u1-X15"}],"explanation":["손이 끌려갔어요.","철 문도 당겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#5','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C12',3,'ox','auto','실을 묶은 클립이 자석에 닿지 않았는데도 공중에 떠 있는 것은 끌어당기는 힘이 작용하기 때문이에요.',ARRAY['SC4-1-u1-X15']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C12","difficulty":3,"kind":"ox","stem":"실을 묶은 클립이 자석에 닿지 않았는데도 공중에 떠 있는 것은 끌어당기는 힘이 작용하기 때문이에요.","answer":"O","reason_options":[{"t":"자석과 철 클립은 조금 떨어져 있어도 서로 끌어당기기 때문에","correct":true},{"t":"자석과 철 클립은 닿아 있을 때만 힘이 작용하기 때문에","mis":"SC4-1-u1-X15"}],"mis":"SC4-1-u1-X15","explanation":["②를 떠올려요.","닿지 않았어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#6','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C13',3,'mc','auto','철 클립 실험 ⑤에서 클립이 바닥으로 떨어진 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X17','SC4-1-u1-X18']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C13","difficulty":3,"kind":"mc","stem":"철 클립 실험 ⑤에서 클립이 바닥으로 떨어진 까닭은 무엇인가요?","options":[{"t":"자석과 클립 사이가 너무 멀어졌기 때문에","correct":true},{"t":"사이에 색종이를 넣었기 때문에","mis":"SC4-1-u1-X17"},{"t":"자석이 클립을 밀어 냈기 때문에","mis":"SC4-1-u1-X18"},{"t":"클립이 자석보다 가볍기 때문에","mis":"SC4-1-u1-X18"}],"explanation":["⑤를 읽어요.","아주 멀리 했어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 막대자석에 실을 묶은 철 클립을 붙였다.","② 자석을 조금 멀리 했더니 클립이 공중에 떠 있었다.","③ 사이에 색종이를 넣어도 클립은 떠 있었다.","④ 얇은 플라스틱판을 넣어도 클립은 떠 있었다.","⑤ 자석을 아주 멀리 했더니 클립이 떨어졌다."],"title":"실을 묶은 철 클립 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#7','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C14',3,'mc','auto','자석과 철 클립 사이에 넣어도 클립이 떠 있을 것으로 예상되는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-1-u1-X17']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C14","difficulty":3,"kind":"mc","stem":"자석과 철 클립 사이에 넣어도 클립이 떠 있을 것으로 예상되는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"색종이, 얇은 플라스틱판, 얇은 유리판","correct":true},{"t":"색종이만","mis":"SC4-1-u1-X17"},{"t":"얇은 플라스틱판만","mis":"SC4-1-u1-X17"},{"t":"아무것도 넣으면 안 된다","mis":"SC4-1-u1-X17"}],"explanation":["사이에 넣어 보았어요.","얇은 것은 괜찮아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#8','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C15',4,'mc','auto','친구가 「클립이 자석에 끌려 오는 건 클립이 가벼워서야. 무거운 철은 자석을 끌어당기지 못해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X18']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C15","difficulty":4,"kind":"mc","stem":"친구가 「클립이 자석에 끌려 오는 건 클립이 가벼워서야. 무거운 철은 자석을 끌어당기지 못해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「무거운 철에 자석을 대면 손이 끌려가. 자석과 철은 서로 끌어당기는 거야.」","correct":true},{"t":"「맞아, 무거운 철은 자석과 상관없어.」","mis":"SC4-1-u1-X18"},{"t":"「맞아, 가벼운 것만 자석에 붙어.」","mis":"SC4-1-u1-X18"},{"t":"「철은 자석을 밀어 내.」","mis":"SC4-1-u1-X18"}],"explanation":["무거운 철을 떠올려요.","손이 끌려가요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#9','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C16',4,'mc','auto','뚜껑이 닫힌 얇은 플라스틱 통 속 철 클립을 통 위쪽으로 옮기려고 해요. 가장 알맞은 방법은 무엇인가요?',ARRAY['SC4-1-u1-X19','SC4-1-u1-X16','SC4-1-u1-X17']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C16","difficulty":4,"kind":"mc","stem":"뚜껑이 닫힌 얇은 플라스틱 통 속 철 클립을 통 위쪽으로 옮기려고 해요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"통 바깥에 자석을 대고 위쪽으로 천천히 움직인다","correct":true},{"t":"통 바깥에 나무젓가락을 대고 위쪽으로 움직인다","mis":"SC4-1-u1-X19"},{"t":"통 위에서 자석을 아주 멀리 들고 기다린다","mis":"SC4-1-u1-X16"},{"t":"통 벽이 막아서 옮길 수 없다고 여긴다","mis":"SC4-1-u1-X17"}],"explanation":["얇은 플라스틱이에요.","자석을 따라와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L03_challenge#10','sci',4,1,'u1','L03','g4_1_sci_u1_L03_challenge','lesson_challenge','SC4-1-u1-C14',4,'essay','teacher','실을 묶은 철 클립 실험에서 알게 된 자석과 자석에 붙는 물체 사이의 힘의 특징을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C14","difficulty":4,"kind":"essay","stem":"실을 묶은 철 클립 실험에서 알게 된 자석과 자석에 붙는 물체 사이의 힘의 특징을 두 가지 쓰세요.","answer_guide":{"answer":"예: 자석과 자석에 붙는 물체는 조금 떨어져 있어도 서로 끌어당긴다. 또 사이에 색종이나 얇은 플라스틱판이 있어도 끌어당기는 힘이 작용한다.","scoring_points":["떨어져 있어도 끌어당김을 썼는가","사이에 물체가 있어도 힘이 작용함을 썼는가","실험 결과를 근거로 썼는가"]},"explanation":["실험을 읽어요.","두 가지를 찾아요.","특징을 써요."],"asset":{"type":"passage","lines":["① 막대자석에 실을 묶은 철 클립을 붙였다.","② 자석을 조금 멀리 했더니 클립이 공중에 떠 있었다.","③ 사이에 색종이를 넣어도 클립은 떠 있었다.","④ 얇은 플라스틱판을 넣어도 클립은 떠 있었다.","⑤ 자석을 아주 멀리 했더니 클립이 떨어졌다."],"title":"실을 묶은 철 클립 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#1','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C17',1,'mc','auto','막대자석을 철 클립 상자에 넣었다가 들어 올리면 클립이 가장 많이 붙는 곳은 어디인가요?',ARRAY['SC4-1-u1-X20','SC4-1-u1-X21']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C17","difficulty":1,"kind":"mc","stem":"막대자석을 철 클립 상자에 넣었다가 들어 올리면 클립이 가장 많이 붙는 곳은 어디인가요?","options":[{"t":"양쪽 끝부분","correct":true},{"t":"가운데 부분","mis":"SC4-1-u1-X20"},{"t":"한쪽 끝부분만","mis":"SC4-1-u1-X21"},{"t":"모든 부분에 똑같이","mis":"SC4-1-u1-X20"}],"explanation":["첫 줄을 읽어요.","끝에 많아요.","양쪽 끝부분이에요."],"asset":{"type":"passage","lines":["막대자석 — 양쪽 끝에 클립이 많이 붙었다.","말굽자석 — 양쪽 끝에 클립이 많이 붙었다.","동전 모양 자석 — 많이 붙은 곳이 두 군데였다.","고리 자석 — 많이 붙은 곳이 두 군데였다."],"title":"클립 상자에서 들어 올린 자석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#2','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C19',1,'ox','auto','막대자석의 같은 극끼리 가까이 하면 서로 끌어당겨요.',ARRAY['SC4-1-u1-X22']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C19","difficulty":1,"kind":"ox","stem":"막대자석의 같은 극끼리 가까이 하면 서로 끌어당겨요.","answer":"X","reason_options":[{"t":"같은 극끼리는 서로 밀어 내기 때문에","correct":true},{"t":"같은 극끼리는 서로 같아서 붙기 때문에","mis":"SC4-1-u1-X22"}],"mis":"SC4-1-u1-X22","explanation":["N극끼리를 떠올려요.","밀어 내요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#3','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C18',1,'mc','auto','한 자석에 있는 극은 몇 개인가요?',ARRAY['SC4-1-u1-X21']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C18","difficulty":1,"kind":"mc","stem":"한 자석에 있는 극은 몇 개인가요?","options":[{"t":"두 개","correct":true},{"t":"한 개","mis":"SC4-1-u1-X21"},{"t":"세 개","mis":"SC4-1-u1-X21"},{"t":"자석마다 다르다","mis":"SC4-1-u1-X21"}],"explanation":["N극과 S극이에요.","둘이에요.","두 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#4','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C17',1,'sa','auto','자석에서 철로 된 물체를 끌어당기는 힘이 가장 센 부분을 무엇이라고 하나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u1-C17","difficulty":1,"kind":"sa","stem":"자석에서 철로 된 물체를 끌어당기는 힘이 가장 센 부분을 무엇이라고 하나요? 한 글자로 쓰세요.","answer":["극"],"explanation":["N○과 S○이에요.","한 글자예요.","극이에요."],"mis":"SC4-1-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#5','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C19',2,'mc','auto','막대자석의 N극과 다른 막대자석의 S극을 가까이 하면 어떻게 되나요?',ARRAY['SC4-1-u1-X22','SC4-1-u1-X23']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C19","difficulty":2,"kind":"mc","stem":"막대자석의 N극과 다른 막대자석의 S극을 가까이 하면 어떻게 되나요?","options":[{"t":"서로 끌어당긴다","correct":true},{"t":"서로 밀어 낸다","mis":"SC4-1-u1-X22"},{"t":"아무 일도 일어나지 않는다","mis":"SC4-1-u1-X23"},{"t":"N극만 S극을 밀어 낸다","mis":"SC4-1-u1-X23"}],"explanation":["다른 극이에요.","당겨요.","끌어당겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#6','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C19',2,'match','auto','가까이 한 두 극과 작용하는 힘을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u1-C19","difficulty":2,"kind":"match","stem":"가까이 한 두 극과 작용하는 힘을 알맞게 이으세요.","pairs":[{"l":"N극과 N극","r":"같은 극이라 서로 밀어 내요"},{"l":"S극과 S극","r":"같은 극이라 밀어 내는 느낌이 들어요"},{"l":"N극과 S극","r":"다른 극이라 서로 끌어당겨요"},{"l":"S극과 N극","r":"다른 극이라 끌어당기는 느낌이 들어요"}],"mis":"SC4-1-u1-X22","explanation":["같은 극인지 봐요.","같으면 밀어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#7','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C18',2,'mc','auto','자석의 두 극은 각각 무엇이라고 나타내나요?',ARRAY['SC4-1-u1-X21','SC4-1-u1-X26']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C18","difficulty":2,"kind":"mc","stem":"자석의 두 극은 각각 무엇이라고 나타내나요?","options":[{"t":"N극과 S극","correct":true},{"t":"A극과 B극","mis":"SC4-1-u1-X21"},{"t":"큰 극과 작은 극","mis":"SC4-1-u1-X21"},{"t":"빨간 극과 파란 극","mis":"SC4-1-u1-X26"}],"explanation":["글자로 나타내요.","N과 S예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#8','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C18',2,'ox','auto','고리 자석의 극은 두 개예요.',ARRAY['SC4-1-u1-X21']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C18","difficulty":2,"kind":"ox","stem":"고리 자석의 극은 두 개예요.","answer":"O","reason_options":[{"t":"모양이 달라도 자석의 극은 항상 두 개이기 때문에","correct":true},{"t":"고리 자석은 둥글어서 극이 없기 때문에","mis":"SC4-1-u1-X21"}],"mis":"SC4-1-u1-X21","explanation":["넷째 줄을 읽어요.","두 군데예요.","그래서 O예요."],"asset":{"type":"passage","lines":["막대자석 — 양쪽 끝에 클립이 많이 붙었다.","말굽자석 — 양쪽 끝에 클립이 많이 붙었다.","동전 모양 자석 — 많이 붙은 곳이 두 군데였다.","고리 자석 — 많이 붙은 곳이 두 군데였다."],"title":"클립 상자에서 들어 올린 자석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#9','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C19',2,'mc','auto','두 고리 자석이 막대에 끼워진 채 서로 닿지 않고 떠 있어요. 그 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X22','SC4-1-u1-X23']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C19","difficulty":2,"kind":"mc","stem":"두 고리 자석이 막대에 끼워진 채 서로 닿지 않고 떠 있어요. 그 까닭은 무엇인가요?","options":[{"t":"마주 보는 면이 같은 극이라 서로 밀어 내기 때문에","correct":true},{"t":"마주 보는 면이 다른 극이라 서로 끌어당기기 때문에","mis":"SC4-1-u1-X22"},{"t":"고리 자석이 가벼워서 저절로 뜨기 때문에","mis":"SC4-1-u1-X23"},{"t":"막대가 고리 자석을 밀어 올리기 때문에","mis":"SC4-1-u1-X23"}],"explanation":["떠 있어요.","밀어 내고 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_basic#10','sci',4,1,'u1','L04','g4_1_sci_u1_L04_basic','lesson_basic','SC4-1-u1-C20',3,'mc','auto','빨대에 끼운 고리 자석 윗면에 막대자석의 N극을 가까이 했더니 밀려났어요. 고리 자석 윗면은 무슨 극인가요?',ARRAY['SC4-1-u1-X24','SC4-1-u1-X21']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C20","difficulty":3,"kind":"mc","stem":"빨대에 끼운 고리 자석 윗면에 막대자석의 N극을 가까이 했더니 밀려났어요. 고리 자석 윗면은 무슨 극인가요?","options":[{"t":"N극","correct":true},{"t":"S극","mis":"SC4-1-u1-X24"},{"t":"극이 없다","mis":"SC4-1-u1-X21"},{"t":"윗면과 아랫면이 모두 N극","mis":"SC4-1-u1-X21"}],"explanation":["밀려났어요.","같은 극이에요.","N극이에요."],"asset":{"type":"passage","lines":["빨대에 고리 자석을 끼웠다.","고리 자석 윗면에 막대자석의 N극을 가까이 했다.","고리 자석이 막대자석에서 밀려났다."],"title":"고리 자석의 극 추리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#1','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C17',2,'blank','auto','「자석에서 철로 된 물체를 끌어당기는 힘이 가장 센 부분을 자석의 (    )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X20']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C17","difficulty":2,"kind":"blank","stem":"「자석에서 철로 된 물체를 끌어당기는 힘이 가장 센 부분을 자석의 (    )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"극","correct":true},{"t":"가운데","mis":"SC4-1-u1-X20"},{"t":"겉면","mis":"SC4-1-u1-X20"},{"t":"무게","mis":"SC4-1-u1-X20"}],"explanation":["클립이 가장 많이 붙어요.","양쪽 끝이에요.","극이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#2','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C21',2,'mc','auto','막대자석을 반으로 자르면 어떻게 될까요?',ARRAY['SC4-1-u1-X25','SC4-1-u1-X26']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C21","difficulty":2,"kind":"mc","stem":"막대자석을 반으로 자르면 어떻게 될까요?","options":[{"t":"양쪽 끝에 각각 N극과 S극이 있는 자석 두 개가 된다","correct":true},{"t":"N극만 있는 자석과 S극만 있는 자석이 된다","mis":"SC4-1-u1-X25"},{"t":"극이 없는 막대 두 개가 된다","mis":"SC4-1-u1-X25"},{"t":"빨간 쪽 자석에만 극이 남는다","mis":"SC4-1-u1-X26"}],"explanation":["극은 항상 두 개예요.","잘라도 그래요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#3','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C18',3,'error','auto','여러 자석을 관찰하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X21','SC4-1-u1-X20']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C18","difficulty":3,"kind":"error","stem":"여러 자석을 관찰하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「동전 모양 자석은 작아서 극이 한 개뿐이야.」","correct":true,"mis_target":"SC4-1-u1-X21"},{"t":"친구 나 — 「말굽자석도 양쪽 끝에 클립이 많이 붙었어.」","mis":"SC4-1-u1-X20"},{"t":"친구 다 — 「모양이 달라도 극은 두 개야.」","mis":"SC4-1-u1-X21"}],"explanation":["셋째 줄을 읽어요.","두 군데예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["막대자석 — 양쪽 끝에 클립이 많이 붙었다.","말굽자석 — 양쪽 끝에 클립이 많이 붙었다.","동전 모양 자석 — 많이 붙은 곳이 두 군데였다.","고리 자석 — 많이 붙은 곳이 두 군데였다."],"title":"클립 상자에서 들어 올린 자석"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#4','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C20',3,'mc','auto','같은 고리 자석 윗면에 이번에는 막대자석의 S극을 가까이 하면 어떻게 될까요?',ARRAY['SC4-1-u1-X24','SC4-1-u1-X23','SC4-1-u1-X25']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C20","difficulty":3,"kind":"mc","stem":"같은 고리 자석 윗면에 이번에는 막대자석의 S극을 가까이 하면 어떻게 될까요?","options":[{"t":"고리 자석이 막대자석 쪽으로 끌려 온다","correct":true},{"t":"고리 자석이 더 멀리 밀려난다","mis":"SC4-1-u1-X24"},{"t":"아무 일도 일어나지 않는다","mis":"SC4-1-u1-X23"},{"t":"고리 자석의 극이 사라진다","mis":"SC4-1-u1-X25"}],"explanation":["윗면은 N극이에요.","S극과는 다른 극이에요.","끌려 와요."],"asset":{"type":"passage","lines":["빨대에 고리 자석을 끼웠다.","고리 자석 윗면에 막대자석의 N극을 가까이 했다.","고리 자석이 막대자석에서 밀려났다."],"title":"고리 자석의 극 추리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#5','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C19',3,'ox','auto','막대자석 두 개를 N극끼리 마주 보게 놓고 한 자석을 밀면 다른 자석이 멀어져요.',ARRAY['SC4-1-u1-X22']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C19","difficulty":3,"kind":"ox","stem":"막대자석 두 개를 N극끼리 마주 보게 놓고 한 자석을 밀면 다른 자석이 멀어져요.","answer":"O","reason_options":[{"t":"같은 극끼리 밀어 내는 힘이 작용하기 때문에","correct":true},{"t":"N극끼리는 서로 끌어당기기 때문에","mis":"SC4-1-u1-X22"}],"mis":"SC4-1-u1-X22","explanation":["같은 극이에요.","밀어 내요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#6','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C17',3,'mc','auto','막대자석을 클립 상자에서 들어 올렸더니 가운데에도 클립이 한두 개 붙어 있었어요. 극을 찾을 때 어떻게 해야 할까요?',ARRAY['SC4-1-u1-X20','SC4-1-u1-X26']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C17","difficulty":3,"kind":"mc","stem":"막대자석을 클립 상자에서 들어 올렸더니 가운데에도 클립이 한두 개 붙어 있었어요. 극을 찾을 때 어떻게 해야 할까요?","options":[{"t":"클립이 가장 많이 붙은 부분을 극으로 찾는다","correct":true},{"t":"클립이 하나라도 붙은 곳은 모두 극으로 친다","mis":"SC4-1-u1-X20"},{"t":"가운데가 극이라고 정한다","mis":"SC4-1-u1-X20"},{"t":"클립 수와 상관없이 빨간 부분만 극이라고 한다","mis":"SC4-1-u1-X26"}],"explanation":["「가장 많이」가 중요해요.","양쪽 끝이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#7','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C21',3,'mc','auto','두 자석을 가까이 하는 실험에서 가장 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u1-X27']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C21","difficulty":3,"kind":"mc","stem":"두 자석을 가까이 하는 실험에서 가장 알맞은 행동은 무엇인가요?","options":[{"t":"두 자석 사이에 손가락이 끼지 않도록 자석의 끝을 잡고 천천히 가까이 한다","correct":true},{"t":"두 자석 사이에 손가락을 넣고 세게 붙인다","mis":"SC4-1-u1-X27"},{"t":"자석을 던져서 붙는지 본다","mis":"SC4-1-u1-X27"},{"t":"다른 극끼리 빠르게 부딪치게 한다","mis":"SC4-1-u1-X27"}],"explanation":["손 끼임을 떠올려요.","천천히 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#8','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C19',4,'mc','auto','고리 자석 다섯 개를 막대에 끼워 가장 높게 쌓으려고 해요. 어떻게 끼워야 할까요?',ARRAY['SC4-1-u1-X22','SC4-1-u1-X23','SC4-1-u1-X25']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C19","difficulty":4,"kind":"mc","stem":"고리 자석 다섯 개를 막대에 끼워 가장 높게 쌓으려고 해요. 어떻게 끼워야 할까요?","options":[{"t":"이웃한 고리 자석의 같은 극끼리 마주 보게 끼운다","correct":true},{"t":"이웃한 고리 자석의 다른 극끼리 마주 보게 끼운다","mis":"SC4-1-u1-X22"},{"t":"극과 상관없이 아무렇게나 끼운다","mis":"SC4-1-u1-X23"},{"t":"고리 자석을 반으로 잘라서 끼운다","mis":"SC4-1-u1-X25"}],"explanation":["떠 있어야 높아요.","밀어 내야 떠요.","같은 극끼리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#9','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C21',4,'mc','auto','친구가 「막대자석의 빨간 쪽이 N극이니까, 빨간 쪽만 잘라 내면 N극만 있는 자석이 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X25','SC4-1-u1-X26']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C21","difficulty":4,"kind":"mc","stem":"친구가 「막대자석의 빨간 쪽이 N극이니까, 빨간 쪽만 잘라 내면 N극만 있는 자석이 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「잘라 낸 빨간 조각도 양쪽 끝에 N극과 S극이 모두 있는 새 자석이 돼.」","correct":true},{"t":"「맞아, 빨간 조각은 N극만 있어.」","mis":"SC4-1-u1-X25"},{"t":"「잘라 내면 극이 모두 사라져.」","mis":"SC4-1-u1-X25"},{"t":"「극은 빨간 쪽에만 있으니 파란 쪽은 자석이 아니야.」","mis":"SC4-1-u1-X26"}],"explanation":["극은 항상 두 개예요.","새 자석이 돼요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L04_challenge#10','sci',4,1,'u1','L04','g4_1_sci_u1_L04_challenge','lesson_challenge','SC4-1-u1-C19',4,'essay','teacher','막대자석 두 개를 N극끼리 마주 보게 가까이 했을 때와 N극과 S극을 마주 보게 가까이 했을 때의 느낌을 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C19","difficulty":4,"kind":"essay","stem":"막대자석 두 개를 N극끼리 마주 보게 가까이 했을 때와 N극과 S극을 마주 보게 가까이 했을 때의 느낌을 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: N극끼리 가까이 하면 서로 밀어 내는 느낌이 든다. 같은 극끼리는 밀어 내는 힘이 작용하기 때문이다. N극과 S극을 가까이 하면 서로 끌어당기는 느낌이 든다. 다른 극끼리는 끌어당기는 힘이 작용하기 때문이다.","scoring_points":["같은 극일 때 밀어 냄을 썼는가","다른 극일 때 끌어당김을 썼는가","극과 관련지어 까닭을 썼는가"]},"explanation":["두 경우를 떠올려요.","느낌을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#1','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C22',1,'mc','auto','나침반은 무엇을 할 때 사용하는 도구인가요?',ARRAY['SC4-1-u1-X33']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C22","difficulty":1,"kind":"mc","stem":"나침반은 무엇을 할 때 사용하는 도구인가요?","options":[{"t":"방향을 찾을 때","correct":true},{"t":"물체의 무게를 잴 때","mis":"SC4-1-u1-X33"},{"t":"자석에 붙는 물체를 찾을 때","mis":"SC4-1-u1-X33"},{"t":"물의 온도를 잴 때","mis":"SC4-1-u1-X33"}],"explanation":["길을 찾을 때 써요.","동서남북이에요.","방향을 찾을 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#2','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C24',1,'ox','auto','나침반 바늘의 빨간색 부분은 N극이에요.',ARRAY['SC4-1-u1-X31']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C24","difficulty":1,"kind":"ox","stem":"나침반 바늘의 빨간색 부분은 N극이에요.","answer":"O","reason_options":[{"t":"자석의 N극을 가까이 하면 빨간색 부분이 밀려나기 때문에","correct":true},{"t":"빨간색 부분은 S극이라서 N극에 끌려오기 때문에","mis":"SC4-1-u1-X31"}],"mis":"SC4-1-u1-X31","explanation":["N극에 밀려났어요.","같은 극이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#3','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C23',1,'mc','auto','나침반에 막대자석의 N극을 가까이 하면 바늘의 빨간색 부분은 어떻게 움직이나요?',ARRAY['SC4-1-u1-X29','SC4-1-u1-X28','SC4-1-u1-X30']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C23","difficulty":1,"kind":"mc","stem":"나침반에 막대자석의 N극을 가까이 하면 바늘의 빨간색 부분은 어떻게 움직이나요?","options":[{"t":"N극에서 멀어지는 방향으로 움직인다","correct":true},{"t":"N극 쪽으로 다가온다","mis":"SC4-1-u1-X29"},{"t":"조금도 움직이지 않는다","mis":"SC4-1-u1-X28"},{"t":"빙글빙글 계속 돈다","mis":"SC4-1-u1-X30"}],"explanation":["②를 떠올려요.","밀려나요.","멀어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#4','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C24',1,'sa','auto','나침반 바늘도 이것의 성질을 가지고 있어서 자석을 가까이 하면 움직여요. 이것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u1-C24","difficulty":1,"kind":"sa","stem":"나침반 바늘도 이것의 성질을 가지고 있어서 자석을 가까이 하면 움직여요. 이것은 무엇인가요? 두 글자로 쓰세요.","answer":["자석"],"explanation":["바늘에도 극이 있어요.","N극과 S극이에요.","자석이에요."],"mis":"SC4-1-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#5','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C23',2,'mc','auto','나침반에 막대자석의 S극을 가까이 하면 바늘의 빨간색 부분은 어떻게 움직이나요?',ARRAY['SC4-1-u1-X29','SC4-1-u1-X28','SC4-1-u1-X25']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C23","difficulty":2,"kind":"mc","stem":"나침반에 막대자석의 S극을 가까이 하면 바늘의 빨간색 부분은 어떻게 움직이나요?","options":[{"t":"S극 쪽으로 다가온다","correct":true},{"t":"S극에서 멀어진다","mis":"SC4-1-u1-X29"},{"t":"움직이지 않는다","mis":"SC4-1-u1-X28"},{"t":"바늘이 두 개로 나뉜다","mis":"SC4-1-u1-X25"}],"explanation":["빨간색은 N극이에요.","S극과 다른 극이에요.","다가와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#6','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C23',2,'match','auto','나침반 관찰 장면과 바늘의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u1-C23","difficulty":2,"kind":"match","stem":"나침반 관찰 장면과 바늘의 모습을 알맞게 이으세요.","pairs":[{"l":"자석이 없을 때","r":"바늘이 멈추어 한 방향을 가리켜요"},{"l":"N극을 가까이 할 때","r":"빨간색 부분이 멀어져요"},{"l":"S극을 가까이 할 때","r":"빨간색 부분이 다가와요"},{"l":"자석을 멀리 할 때","r":"원래 방향으로 돌아가요"}],"mis":"SC4-1-u1-X29","explanation":["기록을 읽어요.","네 장면이에요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 자석이 없을 때 — 바늘이 멈추어 한 방향을 가리켰다.","② N극을 가까이 — 빨간색 부분이 N극에서 멀어졌다.","③ S극을 가까이 — 빨간색 부분이 S극 쪽으로 다가왔다.","④ 자석을 멀리 — 바늘이 원래 방향으로 돌아갔다."],"title":"나침반 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#7','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C22',2,'mc','auto','나침반을 쓰기 전에 가장 먼저 할 일은 무엇인가요?',ARRAY['SC4-1-u1-X32']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C22","difficulty":2,"kind":"mc","stem":"나침반을 쓰기 전에 가장 먼저 할 일은 무엇인가요?","options":[{"t":"평평한 곳에 놓고 주변에 자석이나 철로 된 물체가 없는지 살핀다","correct":true},{"t":"나침반 옆에 막대자석을 놓아 둔다","mis":"SC4-1-u1-X32"},{"t":"나침반을 세게 흔든다","mis":"SC4-1-u1-X32"},{"t":"나침반 위에 철 클립을 올려놓는다","mis":"SC4-1-u1-X32"}],"explanation":["주변을 살펴요.","자석이 없어야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#8','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C23',2,'ox','auto','나침반에서 막대자석을 멀리 떨어뜨리면 바늘은 원래 가리키던 방향으로 되돌아가요.',ARRAY['SC4-1-u1-X30']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C23","difficulty":2,"kind":"ox","stem":"나침반에서 막대자석을 멀리 떨어뜨리면 바늘은 원래 가리키던 방향으로 되돌아가요.","answer":"O","reason_options":[{"t":"자석이 멀어지면 바늘이 그 자석의 영향을 받지 않기 때문에","correct":true},{"t":"한 번 움직인 바늘은 다시 돌아가지 않기 때문에","mis":"SC4-1-u1-X30"}],"mis":"SC4-1-u1-X30","explanation":["④를 읽어요.","돌아갔어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 자석이 없을 때 — 바늘이 멈추어 한 방향을 가리켰다.","② N극을 가까이 — 빨간색 부분이 N극에서 멀어졌다.","③ S극을 가까이 — 빨간색 부분이 S극 쪽으로 다가왔다.","④ 자석을 멀리 — 바늘이 원래 방향으로 돌아갔다."],"title":"나침반 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#9','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C24',2,'mc','auto','나침반과 막대자석을 가까이 하면 바늘이 움직이는 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X28','SC4-1-u1-X30']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C24","difficulty":2,"kind":"mc","stem":"나침반과 막대자석을 가까이 하면 바늘이 움직이는 까닭은 무엇인가요?","options":[{"t":"나침반 바늘도 자석의 성질을 가지고 있기 때문에","correct":true},{"t":"나침반 바늘이 플라스틱으로 되어 있기 때문에","mis":"SC4-1-u1-X28"},{"t":"나침반 바늘이 자석보다 무겁기 때문에","mis":"SC4-1-u1-X28"},{"t":"바람이 바늘을 밀기 때문에","mis":"SC4-1-u1-X30"}],"explanation":["극끼리처럼 움직여요.","바늘도 자석이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_basic#10','sci',4,1,'u1','L05','g4_1_sci_u1_L05_basic','lesson_basic','SC4-1-u1-C25',3,'mc','auto','나침반을 사용할 때 주변에 자석이 없는지 확인해야 하는 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X32','SC4-1-u1-X33']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C25","difficulty":3,"kind":"mc","stem":"나침반을 사용할 때 주변에 자석이 없는지 확인해야 하는 까닭은 무엇인가요?","options":[{"t":"바늘이 주변 자석의 영향을 받아 정확한 방향을 가리킬 수 없기 때문에","correct":true},{"t":"자석이 나침반을 깨뜨리기 때문에","mis":"SC4-1-u1-X32"},{"t":"주변에 자석이 없으면 바늘이 움직이지 않기 때문에","mis":"SC4-1-u1-X33"},{"t":"나침반이 자석을 밀어 내 다치기 때문에","mis":"SC4-1-u1-X32"}],"explanation":["바늘도 자석이에요.","영향을 받아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#1','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C24',2,'blank','auto','「나침반 바늘의 빨간색 부분은 (    )이에요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X31','SC4-1-u1-X28']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C24","difficulty":2,"kind":"blank","stem":"「나침반 바늘의 빨간색 부분은 (    )이에요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"N극","correct":true},{"t":"S극","mis":"SC4-1-u1-X31"},{"t":"철 조각","mis":"SC4-1-u1-X28"},{"t":"극이 없는 부분","mis":"SC4-1-u1-X31"}],"explanation":["N극에 밀려났어요.","같은 극이에요.","N극이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#2','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C23',2,'mc','auto','막대자석의 S극을 나침반 주변에서 천천히 돌려 가며 움직였어요. 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X30']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C23","difficulty":2,"kind":"mc","stem":"막대자석의 S극을 나침반 주변에서 천천히 돌려 가며 움직였어요. 알맞은 것은 무엇인가요?","options":[{"t":"자석의 위치가 바뀌어도 빨간색 부분은 S극 쪽을 따라 움직인다","correct":true},{"t":"위치가 바뀌면 빨간색 부분이 S극에서 멀어진다","mis":"SC4-1-u1-X30"},{"t":"자석을 움직이면 바늘은 더 이상 움직이지 않는다","mis":"SC4-1-u1-X30"},{"t":"위치에 따라 바늘이 아무렇게나 움직인다","mis":"SC4-1-u1-X30"}],"explanation":["규칙은 그대로예요.","S극 쪽으로 다가와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#3','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C24',3,'error','auto','나침반 실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X28','SC4-1-u1-X29','SC4-1-u1-X31']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C24","difficulty":3,"kind":"error","stem":"나침반 실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「나침반 바늘은 그냥 철이라서 어느 극에든 끌려와.」","correct":true,"mis_target":"SC4-1-u1-X28"},{"t":"친구 가 — 「N극을 가까이 하니 빨간색 부분이 밀려났어.」","mis":"SC4-1-u1-X29"},{"t":"친구 나 — 「바늘도 N극과 S극이 있는 자석이야.」","mis":"SC4-1-u1-X31"}],"explanation":["N극에 밀려났어요.","철은 밀려나지 않아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#4','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C24',3,'mc','auto','나침반 바늘이 그냥 철이라면 막대자석의 N극을 가까이 했을 때 어떻게 되어야 할까요?',ARRAY['SC4-1-u1-X28','SC4-1-u1-X25','SC4-1-u1-X31']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C24","difficulty":3,"kind":"mc","stem":"나침반 바늘이 그냥 철이라면 막대자석의 N극을 가까이 했을 때 어떻게 되어야 할까요?","options":[{"t":"바늘이 N극 쪽으로 끌려와야 한다","correct":true},{"t":"바늘이 N극에서 밀려나야 한다","mis":"SC4-1-u1-X28"},{"t":"바늘이 두 개로 나뉘어야 한다","mis":"SC4-1-u1-X25"},{"t":"바늘이 빨간색으로 변해야 한다","mis":"SC4-1-u1-X31"}],"explanation":["철은 자석에 끌려와요.","어느 극에든요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#5','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C25',3,'ox','auto','나침반 옆에 막대자석을 오래 붙여 두어도 괜찮아요.',ARRAY['SC4-1-u1-X32']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C25","difficulty":3,"kind":"ox","stem":"나침반 옆에 막대자석을 오래 붙여 두어도 괜찮아요.","answer":"X","reason_options":[{"t":"자석을 가까이 둔 채 오래 두면 바늘이 잘못된 방향을 가리킬 수 있기 때문에","correct":true},{"t":"나침반 바늘은 자석의 영향을 받지 않기 때문에","mis":"SC4-1-u1-X32"}],"mis":"SC4-1-u1-X32","explanation":["바늘도 자석이에요.","영향을 받아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#6','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C23',3,'mc','auto','나침반 관찰 기록 ②와 ③을 견주어 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u1-X28','SC4-1-u1-X29','SC4-1-u1-X30']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C23","difficulty":3,"kind":"mc","stem":"나침반 관찰 기록 ②와 ③을 견주어 알 수 있는 것은 무엇인가요?","options":[{"t":"바늘의 빨간색 부분과 자석의 극 사이에 밀어 내거나 끌어당기는 힘이 작용한다","correct":true},{"t":"바늘은 자석의 극과 상관없이 늘 같은 쪽으로 움직인다","mis":"SC4-1-u1-X28"},{"t":"N극과 S극은 바늘을 똑같이 움직인다","mis":"SC4-1-u1-X29"},{"t":"바늘은 자석이 있어도 움직이지 않는다","mis":"SC4-1-u1-X30"}],"explanation":["②와 ③을 읽어요.","움직임이 반대예요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 자석이 없을 때 — 바늘이 멈추어 한 방향을 가리켰다.","② N극을 가까이 — 빨간색 부분이 N극에서 멀어졌다.","③ S극을 가까이 — 빨간색 부분이 S극 쪽으로 다가왔다.","④ 자석을 멀리 — 바늘이 원래 방향으로 돌아갔다."],"title":"나침반 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#7','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C22',3,'mc','auto','자석이 없을 때 책상 위 나침반 바늘은 어떻게 되나요?',ARRAY['SC4-1-u1-X33','SC4-1-u1-X31']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C22","difficulty":3,"kind":"mc","stem":"자석이 없을 때 책상 위 나침반 바늘은 어떻게 되나요?","options":[{"t":"멈출 때까지 기다리면 한 방향을 가리키며 멈춘다","correct":true},{"t":"끝없이 빙글빙글 돈다","mis":"SC4-1-u1-X33"},{"t":"책상 위 아무 물체나 가리킨다","mis":"SC4-1-u1-X33"},{"t":"빨간색 부분만 남고 사라진다","mis":"SC4-1-u1-X31"}],"explanation":["①을 떠올려요.","멈추어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#8','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C24',4,'mc','auto','친구가 「나침반 바늘이 자석에 움직이니까 바늘은 자석에 붙는 철일 뿐이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X28','SC4-1-u1-X31','SC4-1-u1-X30']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C24","difficulty":4,"kind":"mc","stem":"친구가 「나침반 바늘이 자석에 움직이니까 바늘은 자석에 붙는 철일 뿐이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「N극에는 밀려나고 S극에는 끌려오니까 바늘도 두 극이 있는 자석이야.」","correct":true},{"t":"「맞아, 철이라서 어느 극에든 끌려와.」","mis":"SC4-1-u1-X28"},{"t":"「바늘의 빨간색 부분은 S극이라서 그래.」","mis":"SC4-1-u1-X31"},{"t":"「바늘은 바람에 움직이는 거야.」","mis":"SC4-1-u1-X30"}],"explanation":["밀려나는 모습을 떠올려요.","철은 밀려나지 않아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#9','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C25',4,'mc','auto','야영장에서 나침반으로 방향을 찾으려는데 옆에 자석이 붙은 손전등이 있어요. 가장 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u1-X32']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C25","difficulty":4,"kind":"mc","stem":"야영장에서 나침반으로 방향을 찾으려는데 옆에 자석이 붙은 손전등이 있어요. 가장 알맞은 행동은 무엇인가요?","options":[{"t":"손전등을 멀리 치우고 나침반을 평평한 곳에 놓은 뒤 바늘이 멈출 때까지 기다린다","correct":true},{"t":"손전등을 나침반 바로 옆에 둔 채 읽는다","mis":"SC4-1-u1-X32"},{"t":"나침반을 흔들어 바늘을 빨리 멈추게 한다","mis":"SC4-1-u1-X32"},{"t":"손전등 쪽을 가리키는 방향을 그대로 믿는다","mis":"SC4-1-u1-X32"}],"explanation":["자석이 영향을 줘요.","치우고 기다려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L05_challenge#10','sci',4,1,'u1','L05','g4_1_sci_u1_L05_challenge','lesson_challenge','SC4-1-u1-C24',4,'essay','teacher','나침반에 막대자석의 N극과 S극을 차례로 가까이 했을 때 바늘의 빨간색 부분이 어떻게 움직이는지 쓰고, 나침반 바늘이 자석이라고 할 수 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C24","difficulty":4,"kind":"essay","stem":"나침반에 막대자석의 N극과 S극을 차례로 가까이 했을 때 바늘의 빨간색 부분이 어떻게 움직이는지 쓰고, 나침반 바늘이 자석이라고 할 수 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: N극을 가까이 하면 빨간색 부분이 N극에서 멀어지고, S극을 가까이 하면 S극 쪽으로 다가온다. 철이라면 어느 극에든 끌려와야 하는데 N극에는 밀려나므로 바늘도 N극과 S극이 있는 자석이다.","scoring_points":["N극일 때 멀어짐을 썼는가","S극일 때 다가옴을 썼는가","밀려나는 모습을 근거로 자석임을 썼는가"]},"explanation":["관찰을 떠올려요.","움직임을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#1','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C26',1,'mc','auto','자석 단추가 달린 가방의 편리한 점은 무엇인가요?',ARRAY['SC4-1-u1-X34']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C26","difficulty":1,"kind":"mc","stem":"자석 단추가 달린 가방의 편리한 점은 무엇인가요?","options":[{"t":"가방을 열고 닫기가 쉽다","correct":true},{"t":"가방이 더 무거워진다","mis":"SC4-1-u1-X34"},{"t":"가방이 물에 젖지 않는다","mis":"SC4-1-u1-X34"},{"t":"가방 색깔이 바뀐다","mis":"SC4-1-u1-X34"}],"explanation":["첫 줄을 읽어요.","여닫기예요.","첫 번째예요."],"asset":{"type":"passage","lines":["자석 단추가 달린 가방 — 열고 닫기가 쉬워요.","자석 클립 통 — 떨어져도 클립이 쏟아지지 않아요.","자석 주방 기구 걸이 — 철로 된 기구를 붙여 보관해요.","자석 커튼 끈 — 매듭을 묶지 않고 고정해요.","냉장고 자석 — 쪽지나 사진을 붙였다 뗄 수 있어요."],"title":"자석을 이용한 생활용품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#2','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C29',1,'ox','auto','나무로 된 주걱도 자석 주방 기구 걸이에 붙여 보관할 수 있어요.',ARRAY['SC4-1-u1-X35']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C29","difficulty":1,"kind":"ox","stem":"나무로 된 주걱도 자석 주방 기구 걸이에 붙여 보관할 수 있어요.","answer":"X","reason_options":[{"t":"나무는 자석에 붙지 않는 물질이기 때문에","correct":true},{"t":"자석 걸이에는 어떤 물체든 붙기 때문에","mis":"SC4-1-u1-X35"}],"mis":"SC4-1-u1-X35","explanation":["나무를 떠올려요.","자석에 안 붙어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#3','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C26',1,'mc','auto','자석 클립 통의 편리한 점은 무엇인가요?',ARRAY['SC4-1-u1-X34','SC4-1-u1-X35']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C26","difficulty":1,"kind":"mc","stem":"자석 클립 통의 편리한 점은 무엇인가요?","options":[{"t":"통이 바닥에 떨어져도 철 클립이 쏟아지지 않는다","correct":true},{"t":"클립이 저절로 많아진다","mis":"SC4-1-u1-X34"},{"t":"클립 색깔이 예뻐진다","mis":"SC4-1-u1-X34"},{"t":"나무 클립도 붙여 둘 수 있다","mis":"SC4-1-u1-X35"}],"explanation":["둘째 줄을 읽어요.","쏟아지지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#4','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C27',1,'sa','auto','냉장고 자석은 자석과 냉장고 문의 철이 서로 어떻게 하는 성질을 이용하나요? 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u1-C27","difficulty":1,"kind":"sa","stem":"냉장고 자석은 자석과 냉장고 문의 철이 서로 어떻게 하는 성질을 이용하나요? 알맞은 말을 쓰세요.","answer":["끌어당긴다","끌어당겨요","끌어당겨","끌어당김","끌어당기는"],"explanation":["쪽지가 붙어 있어요.","서로 당겨요.","끌어당겨요."],"mis":"SC4-1-u1-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#5','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C27',2,'mc','auto','자석 주방 기구 걸이에 붙여 보관할 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u1-X35']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C27","difficulty":2,"kind":"mc","stem":"자석 주방 기구 걸이에 붙여 보관할 수 있는 것은 무엇인가요?","options":[{"t":"철로 된 국자","correct":true},{"t":"나무 주걱","mis":"SC4-1-u1-X35"},{"t":"플라스틱 컵","mis":"SC4-1-u1-X35"},{"t":"유리 그릇","mis":"SC4-1-u1-X35"}],"explanation":["철로 된 것을 찾아요.","자석에 붙어요.","철로 된 국자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#6','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C26',2,'match','auto','생활용품과 자석이 있는 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u1-C26","difficulty":2,"kind":"match","stem":"생활용품과 자석이 있는 곳을 알맞게 이으세요.","pairs":[{"l":"자석 클립 통","r":"뚜껑"},{"l":"냉장고 문","r":"문 안쪽"},{"l":"자석 커튼 끈","r":"끈의 양쪽 끝"},{"l":"자석 드라이버","r":"드라이버 끝부분"}],"mis":"SC4-1-u1-X34","explanation":["자석이 숨은 곳을 떠올려요.","붙는 곳이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#7','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C28',2,'mc','auto','자석 창문 닦이가 유리창 안쪽과 바깥쪽에서 함께 움직이는 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X37','SC4-1-u1-X36','SC4-1-u1-X34']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C28","difficulty":2,"kind":"mc","stem":"자석 창문 닦이가 유리창 안쪽과 바깥쪽에서 함께 움직이는 까닭은 무엇인가요?","options":[{"t":"안쪽과 바깥쪽 닦이에 든 자석의 다른 극끼리 서로 끌어당기기 때문에","correct":true},{"t":"같은 극끼리 서로 끌어당기기 때문에","mis":"SC4-1-u1-X37"},{"t":"유리창이 철로 되어 있기 때문에","mis":"SC4-1-u1-X36"},{"t":"닦이에 풀이 묻어 있기 때문에","mis":"SC4-1-u1-X34"}],"explanation":["양쪽에 자석이 있어요.","다른 극끼리예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#8','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C27',2,'ox','auto','자석 클립 통은 철 클립과 자석이 서로 끌어당기는 성질을 이용한 물건이에요.',ARRAY['SC4-1-u1-X36']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C27","difficulty":2,"kind":"ox","stem":"자석 클립 통은 철 클립과 자석이 서로 끌어당기는 성질을 이용한 물건이에요.","answer":"O","reason_options":[{"t":"뚜껑의 자석이 철 클립을 끌어당겨 붙여 두기 때문에","correct":true},{"t":"자석의 같은 극끼리 밀어 내는 성질을 이용하기 때문에","mis":"SC4-1-u1-X36"}],"mis":"SC4-1-u1-X36","explanation":["뚜껑에 자석이 있어요.","클립은 철이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#9','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C30',2,'mc','auto','자석 양치 컵 걸이에 컵을 매달아 두면 좋은 점은 무엇인가요?',ARRAY['SC4-1-u1-X38']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C30","difficulty":2,"kind":"mc","stem":"자석 양치 컵 걸이에 컵을 매달아 두면 좋은 점은 무엇인가요?","options":[{"t":"컵 바닥에 물이 고이지 않아 물때나 곰팡이가 잘 생기지 않는다","correct":true},{"t":"컵 속에 물이 더 많이 고인다","mis":"SC4-1-u1-X38"},{"t":"컵이 더 무거워진다","mis":"SC4-1-u1-X38"},{"t":"컵이 저절로 깨끗해져 씻을 필요가 없다","mis":"SC4-1-u1-X38"}],"explanation":["매달려 있어요.","물이 빠져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_basic#10','sci',4,1,'u1','L06','g4_1_sci_u1_L06_basic','lesson_basic','SC4-1-u1-C30',3,'mc','auto','자석을 이용한 생활용품을 스마트 기기로 조사할 때 가장 알맞은 행동은 무엇인가요?',ARRAY['SC4-1-u1-X39']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C30","difficulty":3,"kind":"mc","stem":"자석을 이용한 생활용품을 스마트 기기로 조사할 때 가장 알맞은 행동은 무엇인가요?","options":[{"t":"필요한 정보만 찾고, 정보를 어디에서 찾았는지 출처를 밝힌다","correct":true},{"t":"아무 글이나 그대로 옮기고 출처는 쓰지 않는다","mis":"SC4-1-u1-X39"},{"t":"아주 센 자석을 화면에 대 보며 조사한다","mis":"SC4-1-u1-X39"},{"t":"친구의 조사 결과를 내 것처럼 쓴다","mis":"SC4-1-u1-X39"}],"explanation":["조사할 때 지킬 점이에요.","출처를 밝혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#1','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C27',2,'blank','auto','「냉장고 자석은 쪽지나 사진을 쉽게 붙였다 뗄 수 있어요. 자석과 자석에 붙는 물체가 서로 (    ) 성질을 이용했어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X36','SC4-1-u1-X34']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C27","difficulty":2,"kind":"blank","stem":"「냉장고 자석은 쪽지나 사진을 쉽게 붙였다 뗄 수 있어요. 자석과 자석에 붙는 물체가 서로 (    ) 성질을 이용했어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"끌어당기는","correct":true},{"t":"밀어 내는","mis":"SC4-1-u1-X36"},{"t":"녹이는","mis":"SC4-1-u1-X34"},{"t":"물에 뜨는","mis":"SC4-1-u1-X34"}],"explanation":["쪽지가 붙어요.","당겨요.","끌어당기는이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#2','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C28',2,'mc','auto','자석의 다른 극끼리 서로 끌어당기는 성질을 이용한 생활용품은 무엇인가요?',ARRAY['SC4-1-u1-X36']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C28","difficulty":2,"kind":"mc","stem":"자석의 다른 극끼리 서로 끌어당기는 성질을 이용한 생활용품은 무엇인가요?","options":[{"t":"자석 창문 닦이","correct":true},{"t":"자석 주방 기구 걸이","mis":"SC4-1-u1-X36"},{"t":"자석 클립 통","mis":"SC4-1-u1-X36"},{"t":"자석 드라이버","mis":"SC4-1-u1-X36"}],"explanation":["자석 두 개가 마주 봐요.","유리 안팎이에요.","창문 닦이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#3','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C29',3,'error','auto','자석 주방 기구 걸이를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X35','SC4-1-u1-X34','SC4-1-u1-X36']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C29","difficulty":3,"kind":"error","stem":"자석 주방 기구 걸이를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「자석 걸이에는 나무 주걱도 플라스틱 컵도 다 붙일 수 있어.」","correct":true,"mis_target":"SC4-1-u1-X35"},{"t":"친구 가 — 「철로 된 국자를 붙여 두면 쉽게 찾을 수 있어.」","mis":"SC4-1-u1-X34"},{"t":"친구 다 — 「자석과 철이 서로 끌어당기는 성질을 이용했어.」","mis":"SC4-1-u1-X36"}],"explanation":["나무와 플라스틱을 떠올려요.","자석에 안 붙어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#4','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C27',3,'mc','auto','자석 드라이버의 끝부분에 자석이 있으면 어떤 점이 편리한가요?',ARRAY['SC4-1-u1-X35','SC4-1-u1-X34','SC4-1-u1-X37']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C27","difficulty":3,"kind":"mc","stem":"자석 드라이버의 끝부분에 자석이 있으면 어떤 점이 편리한가요?","options":[{"t":"철 나사못이 드라이버 끝에 붙어 떨어뜨리지 않고 쉽게 조일 수 있다","correct":true},{"t":"플라스틱 나사도 붙어서 편리하다","mis":"SC4-1-u1-X35"},{"t":"드라이버가 저절로 돌아간다","mis":"SC4-1-u1-X34"},{"t":"나사못을 밀어 내서 멀리 보낼 수 있다","mis":"SC4-1-u1-X37"}],"explanation":["나사못은 철이에요.","끝에 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#5','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C28',3,'ox','auto','자석 창문 닦이는 자석과 유리가 서로 끌어당기는 성질을 이용해요.',ARRAY['SC4-1-u1-X36']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C28","difficulty":3,"kind":"ox","stem":"자석 창문 닦이는 자석과 유리가 서로 끌어당기는 성질을 이용해요.","answer":"X","reason_options":[{"t":"유리는 자석에 붙지 않고, 안쪽과 바깥쪽 자석의 다른 극끼리 끌어당기기 때문에","correct":true},{"t":"유리는 자석에 붙는 물질이기 때문에","mis":"SC4-1-u1-X36"}],"mis":"SC4-1-u1-X36","explanation":["유리를 떠올려요.","자석에 안 붙어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#6','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C26',3,'mc','auto','자석 커튼 끈의 편리한 점은 무엇인가요?',ARRAY['SC4-1-u1-X34','SC4-1-u1-X37']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C26","difficulty":3,"kind":"mc","stem":"자석 커튼 끈의 편리한 점은 무엇인가요?","options":[{"t":"끈의 양쪽 끝이 붙어 매듭을 묶지 않고 쉽게 커튼을 고정할 수 있다","correct":true},{"t":"커튼이 저절로 열리고 닫힌다","mis":"SC4-1-u1-X34"},{"t":"커튼이 햇빛을 더 잘 막는다","mis":"SC4-1-u1-X34"},{"t":"끈이 철로 된 물체를 밀어 낸다","mis":"SC4-1-u1-X37"}],"explanation":["넷째 줄을 읽어요.","묶지 않아요.","첫 번째예요."],"asset":{"type":"passage","lines":["자석 단추가 달린 가방 — 열고 닫기가 쉬워요.","자석 클립 통 — 떨어져도 클립이 쏟아지지 않아요.","자석 주방 기구 걸이 — 철로 된 기구를 붙여 보관해요.","자석 커튼 끈 — 매듭을 묶지 않고 고정해요.","냉장고 자석 — 쪽지나 사진을 붙였다 뗄 수 있어요."],"title":"자석을 이용한 생활용품"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#7','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C26',3,'mc','auto','셀로판테이프 대신 자석으로 쪽지를 칠판에 붙이면 좋은 점은 무엇인가요?',ARRAY['SC4-1-u1-X34','SC4-1-u1-X35']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C26","difficulty":3,"kind":"mc","stem":"셀로판테이프 대신 자석으로 쪽지를 칠판에 붙이면 좋은 점은 무엇인가요?","options":[{"t":"테이프 자국 없이 쉽게 붙였다 뗄 수 있다","correct":true},{"t":"쪽지가 칠판에서 절대 떨어지지 않는다","mis":"SC4-1-u1-X34"},{"t":"쪽지 글씨가 더 크게 보인다","mis":"SC4-1-u1-X34"},{"t":"나무 칠판에도 붙는다","mis":"SC4-1-u1-X35"}],"explanation":["테이프를 떠올려요.","자국이 남아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#8','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C28',4,'mc','auto','친구가 「가방 자석 단추는 같은 극끼리 붙어서 딸깍 닫혀.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X37','SC4-1-u1-X34','SC4-1-u1-X36']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C28","difficulty":4,"kind":"mc","stem":"친구가 「가방 자석 단추는 같은 극끼리 붙어서 딸깍 닫혀.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「같은 극끼리는 밀어 내. 단추의 자석은 다른 극끼리 끌어당겨서 닫히는 거야.」","correct":true},{"t":"「맞아, 같은 극끼리 끌어당겨.」","mis":"SC4-1-u1-X37"},{"t":"「단추는 자석과 상관없이 풀로 붙어.」","mis":"SC4-1-u1-X34"},{"t":"「단추는 철이라서 아무 데나 붙어.」","mis":"SC4-1-u1-X36"}],"explanation":["같은 극은 밀어요.","다른 극은 당겨요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#9','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C30',4,'mc','auto','자석 양치 컵 걸이에서 자석을 이용한 부분으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X38']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C30","difficulty":4,"kind":"mc","stem":"자석 양치 컵 걸이에서 자석을 이용한 부분으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"컵 바닥과 컵 걸이의 붙이는 부분","correct":true},{"t":"컵 손잡이에 그린 그림","mis":"SC4-1-u1-X38"},{"t":"칫솔의 털","mis":"SC4-1-u1-X38"},{"t":"컵 속에 담긴 물","mis":"SC4-1-u1-X38"}],"explanation":["어디가 붙나요?","컵 바닥이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L06_challenge#10','sci',4,1,'u1','L06','g4_1_sci_u1_L06_challenge','lesson_challenge','SC4-1-u1-C28',4,'essay','teacher','자석 창문 닦이에서 자석을 이용한 부분과 이용한 자석의 성질을 쓰고, 편리한 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C28","difficulty":4,"kind":"essay","stem":"자석 창문 닦이에서 자석을 이용한 부분과 이용한 자석의 성질을 쓰고, 편리한 점을 쓰세요.","answer_guide":{"answer":"예: 유리창 안쪽 닦이와 바깥쪽 닦이에 자석이 들어 있다. 자석의 다른 극끼리 서로 끌어당기는 성질을 이용했다. 안쪽만 움직여도 바깥쪽이 함께 움직여 손이 닿지 않는 바깥 면까지 한 번에 닦을 수 있다.","scoring_points":["자석이 있는 곳을 썼는가","다른 극끼리 끌어당기는 성질을 썼는가","편리한 점을 썼는가"]},"explanation":["창문 닦이를 떠올려요.","성질을 써요.","편리한 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#1','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C31',1,'mc','auto','자석을 이용한 장치를 설계할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SC4-1-u1-X43','SC4-1-u1-X42']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C31","difficulty":1,"kind":"mc","stem":"자석을 이용한 장치를 설계할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"일상생활에서 불편했던 경험을 떠올린다","correct":true},{"t":"장치를 바로 만들기 시작한다","mis":"SC4-1-u1-X43"},{"t":"가장 비싼 자석을 산다","mis":"SC4-1-u1-X43"},{"t":"친구 설계도를 그대로 베낀다","mis":"SC4-1-u1-X42"}],"explanation":["설계의 차례예요.","불편함부터예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#2','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C34',1,'ox','auto','자석 장치를 설계했다면 반드시 직접 만들어야 해요.',ARRAY['SC4-1-u1-X41']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C34","difficulty":1,"kind":"ox","stem":"자석 장치를 설계했다면 반드시 직접 만들어야 해요.","answer":"X","reason_options":[{"t":"설계한 것이 꼭 만들기로 이어지지 않아도 되기 때문에","correct":true},{"t":"설계는 만들어야만 끝나기 때문에","mis":"SC4-1-u1-X41"}],"mis":"SC4-1-u1-X41","explanation":["설계를 떠올려요.","생각을 그려요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#3','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C32',1,'mc','auto','쓰러지지 않는 물통에서 물통 바닥에 붙인 것은 무엇인가요?',ARRAY['SC4-1-u1-X44']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C32","difficulty":1,"kind":"mc","stem":"쓰러지지 않는 물통에서 물통 바닥에 붙인 것은 무엇인가요?","options":[{"t":"자석","correct":true},{"t":"고무","mis":"SC4-1-u1-X44"},{"t":"나무 조각","mis":"SC4-1-u1-X44"},{"t":"종이","mis":"SC4-1-u1-X44"}],"explanation":["둘째 줄을 읽어요.","바닥에 있어요.","자석이에요."],"asset":{"type":"passage","lines":["어떤 상황 — 물감으로 그림을 그릴 때 물통이 자꾸 쓰러져요.","자석 위치 — 물통 바닥에 자석, 받침대는 철","이용한 성질 — 자석과 철이 서로 끌어당겨요.","편리한 점 — 실수로 쳐도 물통이 쉽게 쓰러지지 않아요."],"title":"쓰러지지 않는 물통 설계도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#4','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C32',1,'sa','auto','쓰러지지 않는 물통의 받침대는 무엇으로 만들었나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u1-C32","difficulty":1,"kind":"sa","stem":"쓰러지지 않는 물통의 받침대는 무엇으로 만들었나요? 한 글자로 쓰세요.","answer":["철"],"explanation":["둘째 줄을 읽어요.","자석에 붙어요.","철이에요."],"asset":{"type":"passage","lines":["어떤 상황 — 물감으로 그림을 그릴 때 물통이 자꾸 쓰러져요.","자석 위치 — 물통 바닥에 자석, 받침대는 철","이용한 성질 — 자석과 철이 서로 끌어당겨요.","편리한 점 — 실수로 쳐도 물통이 쉽게 쓰러지지 않아요."],"title":"쓰러지지 않는 물통 설계도"},"mis":"SC4-1-u1-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
