INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#6','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C31',2,'match','auto','설계 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u1-C31","difficulty":2,"kind":"match","stem":"설계 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"불편한 점 찾기","r":"물감 물통이 자꾸 쓰러져요"},{"l":"성질 정하기","r":"자석과 철이 끌어당기는 성질을 써요"},{"l":"자석 위치 정하기","r":"물통 바닥에 자석을 붙여요"},{"l":"편리한 점 쓰기","r":"쳐도 쉽게 쓰러지지 않아요"}],"mis":"SC4-1-u1-X43","explanation":["설계 차례를 떠올려요.","단계마다 할 일이 있어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#7','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C34',2,'mc','auto','친구의 설계를 살펴볼 때의 기준으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X41','SC4-1-u1-X42']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C34","difficulty":2,"kind":"mc","stem":"친구의 설계를 살펴볼 때의 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"자석의 성질을 잘 이용하여 설계했는가","correct":true},{"t":"설계한 장치를 직접 만들었는가","mis":"SC4-1-u1-X41"},{"t":"가장 화려한 색으로 칠했는가","mis":"SC4-1-u1-X42"},{"t":"세상에 하나도 없는 장치인가","mis":"SC4-1-u1-X41"}],"explanation":["평가 기준을 떠올려요.","자석의 성질이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#8','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C31',2,'ox','auto','신발 끈 끝에 자석을 달면 다른 극끼리 끌어당기는 성질로 끈을 묶지 않고도 고정할 수 있어요.',ARRAY['SC4-1-u1-X37']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C31","difficulty":2,"kind":"ox","stem":"신발 끈 끝에 자석을 달면 다른 극끼리 끌어당기는 성질로 끈을 묶지 않고도 고정할 수 있어요.","answer":"O","reason_options":[{"t":"끈 양쪽 자석의 다른 극끼리 서로 끌어당겨 붙기 때문에","correct":true},{"t":"같은 극끼리 끌어당겨 붙기 때문에","mis":"SC4-1-u1-X37"}],"mis":"SC4-1-u1-X37","explanation":["신발 끈 매듭기예요.","다른 극끼리 당겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#9','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C33',2,'mc','auto','자석 수저 받침대는 어떤 성질을 이용한 장치인가요?',ARRAY['SC4-1-u1-X46','SC4-1-u1-X37']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C33","difficulty":2,"kind":"mc","stem":"자석 수저 받침대는 어떤 성질을 이용한 장치인가요?","options":[{"t":"자석과 철 수저가 서로 끌어당기는 성질","correct":true},{"t":"자석과 나무 수저가 서로 끌어당기는 성질","mis":"SC4-1-u1-X46"},{"t":"자석과 철 수저가 서로 밀어 내는 성질","mis":"SC4-1-u1-X46"},{"t":"수저끼리 같은 극이 밀어 내는 성질","mis":"SC4-1-u1-X37"}],"explanation":["수저는 철이에요.","받침대에 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_basic#10','sci',4,1,'u1','L07','g4_1_sci_u1_L07_basic','lesson_basic','SC4-1-u1-C34',3,'mc','auto','다른 모둠의 설계 발표를 들을 때 가장 알맞은 태도는 무엇인가요?',ARRAY['SC4-1-u1-X42']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C34","difficulty":3,"kind":"mc","stem":"다른 모둠의 설계 발표를 들을 때 가장 알맞은 태도는 무엇인가요?","options":[{"t":"잘한 점을 찾아 칭찬하고 보완할 점은 부드럽게 제안한다","correct":true},{"t":"마음에 들지 않으면 크게 웃으며 놀린다","mis":"SC4-1-u1-X42"},{"t":"우리 모둠 설계가 더 낫다고만 말한다","mis":"SC4-1-u1-X42"},{"t":"아무 말도 듣지 않고 우리 설계만 고친다","mis":"SC4-1-u1-X42"}],"explanation":["소통을 떠올려요.","칭찬하고 제안해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#1','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C32',2,'blank','auto','「쓰러지지 않는 물통은 물통 바닥에 자석을 붙이고 받침대를 (    )로 만들었어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X44']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C32","difficulty":2,"kind":"blank","stem":"「쓰러지지 않는 물통은 물통 바닥에 자석을 붙이고 받침대를 (    )로 만들었어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"철","correct":true},{"t":"고무","mis":"SC4-1-u1-X44"},{"t":"나무","mis":"SC4-1-u1-X44"},{"t":"종이","mis":"SC4-1-u1-X44"}],"explanation":["자석에 붙어야 해요.","한 글자예요.","철이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#2','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C33',2,'mc','auto','자석 허리띠에 붙여 보관하기 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X46']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C33","difficulty":2,"kind":"mc","stem":"자석 허리띠에 붙여 보관하기 알맞은 것은 무엇인가요?","options":[{"t":"철로 된 공구와 나사못","correct":true},{"t":"플라스틱 장난감","mis":"SC4-1-u1-X46"},{"t":"종이 설명서","mis":"SC4-1-u1-X46"},{"t":"유리병","mis":"SC4-1-u1-X46"}],"explanation":["허리띠에 자석이 있어요.","철이 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#3','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C34',3,'error','auto','설계도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X40','SC4-1-u1-X44','SC4-1-u1-X45']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C34","difficulty":3,"kind":"error","stem":"설계도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「물통을 아주 무겁게 만들면 되니까 자석은 필요 없어. 이것도 자석 장치야.」","correct":true,"mis_target":"SC4-1-u1-X40"},{"t":"친구 나 — 「받침대를 철로 만들어서 자석과 끌어당기게 했구나.」","mis":"SC4-1-u1-X44"},{"t":"친구 다 — 「붓을 보관할 곳도 있으면 더 좋겠어.」","mis":"SC4-1-u1-X45"}],"explanation":["평가 기준 ①을 떠올려요.","자석을 이용해야 해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#4','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C32',3,'mc','auto','쓰러지지 않는 물통에서 붓을 잃어버리지 않도록 보완하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X45','SC4-1-u1-X35']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C32","difficulty":3,"kind":"mc","stem":"쓰러지지 않는 물통에서 붓을 잃어버리지 않도록 보완하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"붓에 철 조각을 붙이고 물통 옆면에 자석을 붙여 붓을 보관한다","correct":true},{"t":"붓을 물통 속에 계속 담가 둔다","mis":"SC4-1-u1-X45"},{"t":"붓에 나무 조각을 붙여 자석에 붙인다","mis":"SC4-1-u1-X35"},{"t":"물통 옆면에 풀을 발라 붓을 붙인다","mis":"SC4-1-u1-X45"}],"explanation":["붓도 붙게 해요.","철 조각과 자석이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#5','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C34',3,'ox','auto','이미 있는 자석 장치를 바꾸어 더 편리하게 설계하는 것도 좋은 설계예요.',ARRAY['SC4-1-u1-X41']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C34","difficulty":3,"kind":"ox","stem":"이미 있는 자석 장치를 바꾸어 더 편리하게 설계하는 것도 좋은 설계예요.","answer":"O","reason_options":[{"t":"시중에 나와 있는 장치를 변형하거나 발전시키는 방향도 괜찮기 때문에","correct":true},{"t":"세상에 없던 완전히 새로운 장치만 설계해야 하기 때문에","mis":"SC4-1-u1-X41"}],"mis":"SC4-1-u1-X41","explanation":["부담을 느끼지 않아요.","바꾸어도 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#6','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C33',3,'mc','auto','이불 네 귀퉁이에 자석을 넣은 자석 이불은 어떤 점이 편리한가요?',ARRAY['SC4-1-u1-X46']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C33","difficulty":3,"kind":"mc","stem":"이불 네 귀퉁이에 자석을 넣은 자석 이불은 어떤 점이 편리한가요?","options":[{"t":"이불을 갤 때 귀퉁이끼리 꼭 붙어 반듯하게 갤 수 있다","correct":true},{"t":"이불이 더 따뜻해진다","mis":"SC4-1-u1-X46"},{"t":"이불이 저절로 개어진다","mis":"SC4-1-u1-X46"},{"t":"이불에 철 공구를 붙여 둘 수 있다","mis":"SC4-1-u1-X46"}],"explanation":["귀퉁이를 떠올려요.","꼭 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#7','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C34',3,'mc','auto','평가 기준 「자석의 성질을 잘 이용하여 설계했나요?」에 알맞은 설계는 무엇인가요?',ARRAY['SC4-1-u1-X40']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C34","difficulty":3,"kind":"mc","stem":"평가 기준 「자석의 성질을 잘 이용하여 설계했나요?」에 알맞은 설계는 무엇인가요?","options":[{"t":"철 수저가 받침대의 자석에 붙도록 한 수저 받침대","correct":true},{"t":"수저를 끈으로 묶어 두는 받침대","mis":"SC4-1-u1-X40"},{"t":"수저를 무겁게 만들어 떨어지지 않게 한 받침대","mis":"SC4-1-u1-X40"},{"t":"수저에 예쁜 그림을 그린 받침대","mis":"SC4-1-u1-X40"}],"explanation":["자석이 들어 있나요?","성질을 썼나요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#8','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C35',4,'mc','auto','자석 말판 놀이에서 「자석과 철 클립 사이에 얇은 유리판이 있으면 끌어당기는 힘이 작용하지 않는다.」 칸에 멈췄어요. 알맞은 답은 무엇인가요?',ARRAY['SC4-1-u1-X17','SC4-1-u1-X18','SC4-1-u1-X25']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C35","difficulty":4,"kind":"mc","stem":"자석 말판 놀이에서 「자석과 철 클립 사이에 얇은 유리판이 있으면 끌어당기는 힘이 작용하지 않는다.」 칸에 멈췄어요. 알맞은 답은 무엇인가요?","options":[{"t":"X — 얇은 유리판이 있어도 끌어당기는 힘이 작용한다","correct":true},{"t":"O — 유리판이 힘을 모두 막는다","mis":"SC4-1-u1-X17"},{"t":"O — 유리판이 있으면 자석이 클립을 밀어 낸다","mis":"SC4-1-u1-X18"},{"t":"X — 유리판이 있으면 오히려 극이 사라진다","mis":"SC4-1-u1-X25"}],"explanation":["유리컵 속 철 집게를 떠올려요.","그래도 움직였어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#9','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C35',4,'mc','auto','자석 말판 놀이에서 「고리 자석의 N극에 막대자석의 S극을 가까이 한다.」 칸에 멈췄어요. 무슨 일이 일어날까요?',ARRAY['SC4-1-u1-X22','SC4-1-u1-X23','SC4-1-u1-X24']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C35","difficulty":4,"kind":"mc","stem":"자석 말판 놀이에서 「고리 자석의 N극에 막대자석의 S극을 가까이 한다.」 칸에 멈췄어요. 무슨 일이 일어날까요?","options":[{"t":"서로 끌어당긴다","correct":true},{"t":"서로 밀어 낸다","mis":"SC4-1-u1-X22"},{"t":"아무 힘도 작용하지 않는다","mis":"SC4-1-u1-X23"},{"t":"고리 자석의 극이 바뀐다","mis":"SC4-1-u1-X24"}],"explanation":["N극과 S극이에요.","다른 극이에요.","끌어당겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L07_challenge#10','sci',4,1,'u1','L07','g4_1_sci_u1_L07_challenge','lesson_challenge','SC4-1-u1-C31',4,'essay','teacher','생활 속 불편했던 경험을 하나 떠올려 자석 장치를 설계해 보세요. 어떤 상황에서 쓰는지, 자석을 넣을 곳, 이용할 자석의 성질, 편리한 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C31","difficulty":4,"kind":"essay","stem":"생활 속 불편했던 경험을 하나 떠올려 자석 장치를 설계해 보세요. 어떤 상황에서 쓰는지, 자석을 넣을 곳, 이용할 자석의 성질, 편리한 점을 쓰세요.","answer_guide":{"answer":"예: 필통이 책상에서 자주 떨어져 불편했다. 필통 바닥에 자석을 넣고 책상 모서리에 철판을 붙인다. 자석과 철이 서로 끌어당기는 성질을 이용한다. 필통이 책상에서 잘 떨어지지 않아 편리하다.","scoring_points":["쓰는 상황을 썼는가","자석 위치와 이용한 성질을 썼는가","편리한 점을 썼는가"]},"explanation":["불편했던 일을 떠올려요.","자석을 어디에 넣을까요?","편리한 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#1','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C36',1,'mc','auto','우주 쓰레기는 무엇인가요?',ARRAY['SC4-1-u1-X47']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C36","difficulty":1,"kind":"mc","stem":"우주 쓰레기는 무엇인가요?","options":[{"t":"고장 난 우주선의 부품이나 더 이상 쓰지 않는 인공위성","correct":true},{"t":"우주에 사는 작은 생물","mis":"SC4-1-u1-X47"},{"t":"밤하늘에 반짝이는 별","mis":"SC4-1-u1-X47"},{"t":"우주 비행사가 먹는 음식","mis":"SC4-1-u1-X47"}],"explanation":["우주에 떠도는 것이에요.","쓰지 않는 것이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#2','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C38',1,'ox','auto','액체 자석은 물처럼 흐르지만 자석의 성질을 가지고 있어요.',ARRAY['SC4-1-u1-X49']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C38","difficulty":1,"kind":"ox","stem":"액체 자석은 물처럼 흐르지만 자석의 성질을 가지고 있어요.","answer":"O","reason_options":[{"t":"흐르는 액체 상태이지만 자석의 성질이 있기 때문에","correct":true},{"t":"자석은 단단한 고체여야만 하기 때문에","mis":"SC4-1-u1-X49"}],"mis":"SC4-1-u1-X49","explanation":["셋째 줄을 읽어요.","흘러도 자석이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["우주 쓰레기 청소 — 자석의 성질로 우주 쓰레기를 모아요.","몸속 작은 로봇 — 몸 밖에서 조종해 몸속을 살펴요.","액체 자석 — 흐르지만 자석의 성질이 있어요.","캔 분리수거 — 자석으로 철 캔을 골라내요."],"title":"자석을 이용한 첨단 과학 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#3','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C37',1,'mc','auto','몸속을 돌아다니는 아주 작은 로봇은 어떻게 움직이나요?',ARRAY['SC4-1-u1-X48']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C37","difficulty":1,"kind":"mc","stem":"몸속을 돌아다니는 아주 작은 로봇은 어떻게 움직이나요?","options":[{"t":"몸 밖에서 조종한다","correct":true},{"t":"몸속 음식을 먹고 스스로만 움직인다","mis":"SC4-1-u1-X48"},{"t":"의사가 몸속에 들어가 손으로 민다","mis":"SC4-1-u1-X48"},{"t":"움직이지 않고 한곳에 붙어 있다","mis":"SC4-1-u1-X48"}],"explanation":["둘째 줄을 읽어요.","밖에서 움직여요.","첫 번째예요."],"asset":{"type":"passage","lines":["우주 쓰레기 청소 — 자석의 성질로 우주 쓰레기를 모아요.","몸속 작은 로봇 — 몸 밖에서 조종해 몸속을 살펴요.","액체 자석 — 흐르지만 자석의 성질이 있어요.","캔 분리수거 — 자석으로 철 캔을 골라내요."],"title":"자석을 이용한 첨단 과학 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#4','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C36',1,'sa','auto','지구 둘레를 돌 수 있도록 로켓으로 쏘아 올린 장치를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u1-C36","difficulty":1,"kind":"sa","stem":"지구 둘레를 돌 수 있도록 로켓으로 쏘아 올린 장치를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["인공위성"],"explanation":["우주 쓰레기가 되기도 해요.","로켓으로 쏘아 올려요.","인공위성이에요."],"mis":"SC4-1-u1-X47"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#5','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C38',2,'mc','auto','액체 자석이 쓰이는 곳으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X49']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C38","difficulty":2,"kind":"mc","stem":"액체 자석이 쓰이는 곳으로 알맞은 것은 무엇인가요?","options":[{"t":"지폐의 위조를 막는 자석 잉크","correct":true},{"t":"우주 쓰레기를 태우는 불","mis":"SC4-1-u1-X49"},{"t":"책상을 만드는 나무","mis":"SC4-1-u1-X49"},{"t":"창문의 유리","mis":"SC4-1-u1-X49"}],"explanation":["흐르는 자석이에요.","잉크로 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#6','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C39',2,'match','auto','첨단 과학 기술과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u1-C39","difficulty":2,"kind":"match","stem":"첨단 과학 기술과 하는 일을 알맞게 이으세요.","pairs":[{"l":"우주 쓰레기 청소 장치","r":"인공위성과 부딪치는 사고를 막아요"},{"l":"몸속 작은 로봇","r":"필요한 곳에 약을 전달해요"},{"l":"자석 잉크","r":"가짜 지폐를 막는 데 도움을 줘요"},{"l":"캔 분리수거 장치","r":"철 캔을 골라내요"}],"mis":"SC4-1-u1-X50","explanation":["기술 이름을 읽어요.","하는 일을 떠올려요.","하나씩 이어요."],"asset":{"type":"passage","lines":["우주 쓰레기 청소 — 자석의 성질로 우주 쓰레기를 모아요.","몸속 작은 로봇 — 몸 밖에서 조종해 몸속을 살펴요.","액체 자석 — 흐르지만 자석의 성질이 있어요.","캔 분리수거 — 자석으로 철 캔을 골라내요."],"title":"자석을 이용한 첨단 과학 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#7','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C36',2,'mc','auto','우주 쓰레기가 문제가 되는 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X47']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C36","difficulty":2,"kind":"mc","stem":"우주 쓰레기가 문제가 되는 까닭은 무엇인가요?","options":[{"t":"인공위성이나 우주선, 우주 정거장과 부딪칠 수 있기 때문에","correct":true},{"t":"우주 쓰레기가 지구의 별빛을 가리기 때문에","mis":"SC4-1-u1-X47"},{"t":"우주 쓰레기가 모두 금으로 되어 있기 때문에","mis":"SC4-1-u1-X47"},{"t":"아무 문제도 일으키지 않기 때문에","mis":"SC4-1-u1-X47"}],"explanation":["우주에서 떠돌아요.","부딪칠 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#8','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C39',2,'ox','auto','자석은 교실에서 쓰는 막대자석 모양만 있어요.',ARRAY['SC4-1-u1-X50']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C39","difficulty":2,"kind":"ox","stem":"자석은 교실에서 쓰는 막대자석 모양만 있어요.","answer":"X","reason_options":[{"t":"아주 큰 자석부터 눈에 보이지 않을 만큼 작은 자석, 흐르는 액체 자석까지 다양하기 때문에","correct":true},{"t":"자석은 크기와 모양이 모두 같기 때문에","mis":"SC4-1-u1-X50"}],"mis":"SC4-1-u1-X50","explanation":["여러 자석을 떠올려요.","크기도 모습도 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#9','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C37',2,'mc','auto','몸속 작은 로봇으로 할 수 있는 일은 무엇인가요?',ARRAY['SC4-1-u1-X48']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C37","difficulty":2,"kind":"mc","stem":"몸속 작은 로봇으로 할 수 있는 일은 무엇인가요?","options":[{"t":"몸속을 자세히 살펴보고 필요한 곳에 약을 정확하게 전달한다","correct":true},{"t":"몸속의 우주 쓰레기를 모은다","mis":"SC4-1-u1-X48"},{"t":"지폐에 자석 잉크를 바른다","mis":"SC4-1-u1-X48"},{"t":"캔을 종류별로 나눈다","mis":"SC4-1-u1-X48"}],"explanation":["의료 분야예요.","살피고 약을 전해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_basic#10','sci',4,1,'u1','L08','g4_1_sci_u1_L08_basic','lesson_basic','SC4-1-u1-C39',3,'mc','auto','캔 분리수거 장치에서 자석에 붙어 골라지는 것은 무엇인가요?',ARRAY['SC4-1-u1-X51']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C39","difficulty":3,"kind":"mc","stem":"캔 분리수거 장치에서 자석에 붙어 골라지는 것은 무엇인가요?","options":[{"t":"철 캔","correct":true},{"t":"알루미늄 캔","mis":"SC4-1-u1-X51"},{"t":"플라스틱 병","mis":"SC4-1-u1-X51"},{"t":"유리병","mis":"SC4-1-u1-X51"}],"explanation":["철로 된 것이에요.","자석에 붙어요.","철 캔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#1','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C38',2,'blank','auto','「액체 자석은 (    )처럼 흐르지만 자석의 성질을 가지고 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X49']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C38","difficulty":2,"kind":"blank","stem":"「액체 자석은 (    )처럼 흐르지만 자석의 성질을 가지고 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"물이나 기름","correct":true},{"t":"돌이나 쇠","mis":"SC4-1-u1-X49"},{"t":"나무나 종이","mis":"SC4-1-u1-X49"},{"t":"유리나 고무","mis":"SC4-1-u1-X49"}],"explanation":["흐르는 것을 떠올려요.","액체예요.","물이나 기름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#2','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C39',2,'mc','auto','첨단 과학 분야의 자석 이야기를 읽을 때 가장 중요한 것은 무엇인가요?',ARRAY['SC4-1-u1-X50']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C39","difficulty":2,"kind":"mc","stem":"첨단 과학 분야의 자석 이야기를 읽을 때 가장 중요한 것은 무엇인가요?","options":[{"t":"자석이 여러 첨단 과학 분야에 쓰이고 있음을 알고 관심을 가지는 것","correct":true},{"t":"기술의 원리를 모두 외우는 것","mis":"SC4-1-u1-X50"},{"t":"자석은 교실에서만 쓴다고 정리하는 것","mis":"SC4-1-u1-X50"},{"t":"우주 기술만 자석을 쓴다고 아는 것","mis":"SC4-1-u1-X50"}],"explanation":["원리보다 쓰임이에요.","관심을 가져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#3','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C39',3,'error','auto','첨단 과학 기술 이야기를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X50','SC4-1-u1-X48','SC4-1-u1-X49']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C39","difficulty":3,"kind":"error","stem":"첨단 과학 기술 이야기를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「자석은 교실이랑 냉장고에서만 쓰이는 물건이야.」","correct":true,"mis_target":"SC4-1-u1-X50"},{"t":"친구 가 — 「자석으로 몸속 작은 로봇을 조종할 수 있대.」","mis":"SC4-1-u1-X48"},{"t":"친구 나 — 「흐르는 액체 자석도 있대.」","mis":"SC4-1-u1-X49"}],"explanation":["여러 분야를 떠올려요.","우주와 의료에도 써요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#4','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C39',3,'mc','auto','캔 분리수거 장치에 철 캔과 알루미늄 캔이 섞여 들어오면 어떻게 될까요?',ARRAY['SC4-1-u1-X51']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C39","difficulty":3,"kind":"mc","stem":"캔 분리수거 장치에 철 캔과 알루미늄 캔이 섞여 들어오면 어떻게 될까요?","options":[{"t":"철 캔만 자석에 붙어 골라진다","correct":true},{"t":"알루미늄 캔만 자석에 붙어 골라진다","mis":"SC4-1-u1-X51"},{"t":"두 캔 모두 자석에 붙는다","mis":"SC4-1-u1-X51"},{"t":"두 캔 모두 붙지 않아 골라낼 수 없다","mis":"SC4-1-u1-X51"}],"explanation":["철은 자석에 붙어요.","알루미늄은 안 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#5','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C36',3,'ox','auto','과학자들은 자석의 성질을 이용해 우주 쓰레기를 모아 처리하는 장치를 개발하고 있어요.',ARRAY['SC4-1-u1-X47']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C36","difficulty":3,"kind":"ox","stem":"과학자들은 자석의 성질을 이용해 우주 쓰레기를 모아 처리하는 장치를 개발하고 있어요.","answer":"O","reason_options":[{"t":"우주 쓰레기와 부딪치는 사고를 막기 위해 연구하고 있기 때문에","correct":true},{"t":"우주 쓰레기는 아무 문제가 없어 연구할 필요가 없기 때문에","mis":"SC4-1-u1-X47"}],"mis":"SC4-1-u1-X47","explanation":["첫 줄을 떠올려요.","모아서 처리해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#6','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C39',3,'mc','auto','자석끼리 밀어 내거나 끌어당기는 성질을 이용해 프로펠러를 돌리면 어떤 점이 좋을까요?',ARRAY['SC4-1-u1-X50','SC4-1-u1-X49']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C39","difficulty":3,"kind":"mc","stem":"자석끼리 밀어 내거나 끌어당기는 성질을 이용해 프로펠러를 돌리면 어떤 점이 좋을까요?","options":[{"t":"열과 소음, 떨림이 거의 생기지 않는다","correct":true},{"t":"소음이 훨씬 커진다","mis":"SC4-1-u1-X50"},{"t":"프로펠러가 녹아서 흐른다","mis":"SC4-1-u1-X49"},{"t":"철로 된 물체를 모두 밀어 낸다","mis":"SC4-1-u1-X50"}],"explanation":["마찰이 줄어요.","조용해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#7','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C37',3,'mc','auto','몸속 작은 로봇이 약을 전달하면 좋은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X48','SC4-1-u1-X47']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C37","difficulty":3,"kind":"mc","stem":"몸속 작은 로봇이 약을 전달하면 좋은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"약이 필요한 곳에 정확하게 전달될 수 있다","correct":true},{"t":"약이 몸 밖으로 바로 나온다","mis":"SC4-1-u1-X48"},{"t":"로봇이 약을 대신 먹는다","mis":"SC4-1-u1-X48"},{"t":"몸속에 쓰레기를 모은다","mis":"SC4-1-u1-X47"}],"explanation":["필요한 곳이에요.","정확하게예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#8','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C38',4,'mc','auto','지폐에 자석 잉크를 쓰는 까닭은 무엇일까요?',ARRAY['SC4-1-u1-X49','SC4-1-u1-X48']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C38","difficulty":4,"kind":"mc","stem":"지폐에 자석 잉크를 쓰는 까닭은 무엇일까요?","options":[{"t":"가짜 지폐를 만들지 못하도록 막는 데 도움이 되기 때문에","correct":true},{"t":"지폐를 더 무겁게 만들기 위해","mis":"SC4-1-u1-X49"},{"t":"지폐가 물처럼 흐르게 하기 위해","mis":"SC4-1-u1-X49"},{"t":"지폐로 몸속을 살펴보기 위해","mis":"SC4-1-u1-X48"}],"explanation":["위조 방지예요.","가짜를 막아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#9','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C39',4,'mc','auto','친구가 「나는 커서 자석과 상관있는 일은 할 수 없을 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X50']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C39","difficulty":4,"kind":"mc","stem":"친구가 「나는 커서 자석과 상관있는 일은 할 수 없을 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「우주 쓰레기를 치우는 장치나 몸속 로봇을 만드는 사람처럼 자석과 관련된 일이 많아. 관심을 가져 보자.」","correct":true},{"t":"「맞아, 자석은 교실에서만 쓰여.」","mis":"SC4-1-u1-X50"},{"t":"「자석은 막대자석밖에 없어서 할 일이 없어.」","mis":"SC4-1-u1-X50"},{"t":"「첨단 과학은 우리와 상관없어.」","mis":"SC4-1-u1-X50"}],"explanation":["여러 분야를 떠올려요.","관련된 일이 많아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_L08_challenge#10','sci',4,1,'u1','L08','g4_1_sci_u1_L08_challenge','lesson_challenge','SC4-1-u1-C39',4,'essay','teacher','자석의 성질을 이용한 첨단 과학 기술 두 가지를 골라 어떤 일을 하는지 쓰고, 내가 해 보고 싶은 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C39","difficulty":4,"kind":"essay","stem":"자석의 성질을 이용한 첨단 과학 기술 두 가지를 골라 어떤 일을 하는지 쓰고, 내가 해 보고 싶은 일을 쓰세요.","answer_guide":{"answer":"예: 우주 쓰레기 청소 장치는 자석의 성질로 우주 쓰레기를 모아 인공위성과 부딪치는 사고를 막는다. 몸속 작은 로봇은 몸 밖에서 조종해 필요한 곳에 약을 전달한다. 나는 몸속 로봇을 연구하는 일을 해 보고 싶다.","scoring_points":["기술 두 가지를 바르게 썼는가","하는 일을 썼는가","해 보고 싶은 일을 썼는가"]},"explanation":["기술을 떠올려요.","하는 일을 써요.","내 꿈을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#1','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C1',1,'mc','auto','햇살반 일지 ①에서 같은 칸에 다트 핀 두 개가 붙었을 때 어떻게 세었나요?',ARRAY['SC4-1-u1-X02']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C1","difficulty":1,"kind":"mc","stem":"햇살반 일지 ①에서 같은 칸에 다트 핀 두 개가 붙었을 때 어떻게 세었나요?","options":[{"t":"하나로 세었다","correct":true},{"t":"두 개로 세었다","mis":"SC4-1-u1-X02"},{"t":"세지 않았다","mis":"SC4-1-u1-X02"},{"t":"다시 던졌다","mis":"SC4-1-u1-X02"}],"explanation":["둘째 줄을 읽어요.","하나로 세었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠별로 과녁판을 그리고 자석 다트 핀을 던졌다.","같은 칸에 두 개가 붙어서 하나로 세었다.","다트 핀은 착 붙었다가 쉽게 떨어졌다.","친구 가 — 「우리 모둠이 이겼으니 놀이 끝!」"],"title":"햇살반 일지 ① 자석 다트 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#2','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C5',1,'mc','auto','햇살반 일지 ②에서 자석에 붙은 물체는 무엇인가요?',ARRAY['SC4-1-u1-X09','SC4-1-u1-X08','SC4-1-u1-X12']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C5","difficulty":1,"kind":"mc","stem":"햇살반 일지 ②에서 자석에 붙은 물체는 무엇인가요?","options":[{"t":"철 나사못","correct":true},{"t":"플라스틱 단추","mis":"SC4-1-u1-X09"},{"t":"동전","mis":"SC4-1-u1-X08"},{"t":"가위 손잡이","mis":"SC4-1-u1-X12"}],"explanation":["첫 줄을 읽어요.","철로 된 것이에요.","철 나사못이에요."],"asset":{"type":"passage","lines":["철 나사못 — 붙었다","플라스틱 단추 — 붙지 않았다","동전 — 붙지 않았다","가위 — 날만 붙었다","친구 나 — 「동전은 금속인데 왜 안 붙지?」"],"title":"햇살반 일지 ② 붙을까, 안 붙을까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#3','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C14',1,'mc','auto','햇살반 일지 ③에서 공책 한 장을 끼워도 클립이 따라온 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X17','SC4-1-u1-X09','SC4-1-u1-X15']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C14","difficulty":1,"kind":"mc","stem":"햇살반 일지 ③에서 공책 한 장을 끼워도 클립이 따라온 까닭은 무엇인가요?","options":[{"t":"사이에 종이가 있어도 끌어당기는 힘이 작용하기 때문에","correct":true},{"t":"종이가 클립을 밀어 주기 때문에","mis":"SC4-1-u1-X17"},{"t":"클립이 종이에 붙었기 때문에","mis":"SC4-1-u1-X09"},{"t":"자석과 클립이 닿았기 때문에","mis":"SC4-1-u1-X15"}],"explanation":["둘째 줄을 읽어요.","종이가 있어도요.","첫 번째예요."],"asset":{"type":"passage","lines":["얇은 플라스틱 통 속 철 클립을 통 밖 자석으로 움직였다.","자석과 클립 사이에 공책 한 장을 끼워도 클립이 따라왔다.","자석을 멀리 떼니 클립이 따라오지 않았다.","친구 다 — 「자석만 클립을 당기는 거야.」"],"title":"햇살반 일지 ③ 떨어져 있어도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#4','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C19',1,'mc','auto','햇살반 일지 ④에서 N극끼리 가까이 했을 때 밀어 낸 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X22','SC4-1-u1-X23']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C19","difficulty":1,"kind":"mc","stem":"햇살반 일지 ④에서 N극끼리 가까이 했을 때 밀어 낸 까닭은 무엇인가요?","options":[{"t":"같은 극끼리는 서로 밀어 내기 때문에","correct":true},{"t":"다른 극끼리는 서로 밀어 내기 때문에","mis":"SC4-1-u1-X22"},{"t":"N극끼리만 특별히 밀어 내기 때문에","mis":"SC4-1-u1-X23"},{"t":"막대자석이 가볍기 때문에","mis":"SC4-1-u1-X23"}],"explanation":["첫 줄을 읽어요.","같은 극이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["막대자석 두 개의 N극끼리 가까이 하니 밀어 냈다.","N극과 S극을 가까이 하니 끌어당겼다.","고리 자석 윗면에 S극을 대니 끌려 왔다.","친구 가 — 「자석을 반으로 자르면 N극만 남아.」"],"title":"햇살반 일지 ④ 극 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#5','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C23',1,'mc','auto','햇살반 일지 ⑤에서 S극을 가까이 했을 때 빨간색 부분이 다가온 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X31','SC4-1-u1-X28','SC4-1-u1-X30']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C23","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑤에서 S극을 가까이 했을 때 빨간색 부분이 다가온 까닭은 무엇인가요?","options":[{"t":"빨간색 부분이 N극이라 다른 극인 S극과 끌어당기기 때문에","correct":true},{"t":"빨간색 부분이 S극이라 같은 극끼리 끌어당기기 때문에","mis":"SC4-1-u1-X31"},{"t":"바늘이 철이라 어느 극에든 끌려오기 때문에","mis":"SC4-1-u1-X28"},{"t":"바늘이 바람에 움직였기 때문에","mis":"SC4-1-u1-X30"}],"explanation":["빨간색은 N극이에요.","다른 극이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["나침반을 평평한 책상에 놓고 바늘이 멈추길 기다렸다.","S극을 가까이 하니 빨간색 부분이 다가왔다.","자석을 치우니 바늘이 원래 방향으로 돌아갔다.","친구 나 — 「바늘은 그냥 철이야.」"],"title":"햇살반 일지 ⑤ 나침반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#6','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C27',1,'mc','auto','햇살반 일지 ⑥의 자석 클립 통이 이용한 성질은 무엇인가요?',ARRAY['SC4-1-u1-X37','SC4-1-u1-X36','SC4-1-u1-X35']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C27","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑥의 자석 클립 통이 이용한 성질은 무엇인가요?","options":[{"t":"자석과 철 클립이 서로 끌어당기는 성질","correct":true},{"t":"자석의 같은 극끼리 밀어 내는 성질","mis":"SC4-1-u1-X37"},{"t":"자석의 다른 극끼리 끌어당기는 성질","mis":"SC4-1-u1-X36"},{"t":"자석이 플라스틱을 끌어당기는 성질","mis":"SC4-1-u1-X35"}],"explanation":["뚜껑에 자석이 있어요.","클립은 철이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["자석 클립 통 — 뚜껑에 자석이 있다.","자석 창문 닦이 — 안쪽과 바깥쪽에 자석이 있다.","자석 양치 컵 걸이 — 컵 바닥에 자석이 있다.","친구 다 — 「자석 걸이에 나무 주걱도 붙여 보자.」"],"title":"햇살반 일지 ⑥ 자석을 이용한 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#7','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C32',1,'mc','auto','햇살반 일지 ⑦의 설계에서 연필에 붙인 것은 무엇인가요?',ARRAY['SC4-1-u1-X44']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C32","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑦의 설계에서 연필에 붙인 것은 무엇인가요?","options":[{"t":"철 조각","correct":true},{"t":"나무 조각","mis":"SC4-1-u1-X44"},{"t":"플라스틱 조각","mis":"SC4-1-u1-X44"},{"t":"고무 조각","mis":"SC4-1-u1-X44"}],"explanation":["둘째 줄을 읽어요.","자석에 붙어야 해요.","철 조각이에요."],"asset":{"type":"passage","lines":["불편한 점 — 연필이 책상에서 자꾸 굴러떨어진다.","설계 — 연필에 철 조각, 책상 홈에 자석을 붙인다.","이용한 성질 — 자석과 철이 서로 끌어당긴다.","친구 가 — 「직접 만들지 않았으니 설계가 아니야.」"],"title":"햇살반 일지 ⑦ 우리 모둠 설계도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
