INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#16','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C37',2,'blank','auto','「몸속을 돌아다니는 아주 작은 로봇은 몸 (    )에서 조종해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u1-X48']::text[],false,'{"seq":16,"concept":"SC4-1-u1-C37","difficulty":2,"kind":"blank","stem":"「몸속을 돌아다니는 아주 작은 로봇은 몸 (    )에서 조종해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"밖","correct":true},{"t":"안","mis":"SC4-1-u1-X48"},{"t":"뒤","mis":"SC4-1-u1-X48"},{"t":"아래","mis":"SC4-1-u1-X48"}],"explanation":["로봇은 몸속에 있어요.","조종은 다른 곳에서요.","밖이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#17','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C5',3,'mc','auto','자석 낚싯대로 공예용 철 끈, 고무공, 철 클립, 색종이, 철 나사못을 낚으면 붙어 나오는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-1-u1-X09','SC4-1-u1-X10']::text[],false,'{"seq":17,"concept":"SC4-1-u1-C5","difficulty":3,"kind":"mc","stem":"자석 낚싯대로 공예용 철 끈, 고무공, 철 클립, 색종이, 철 나사못을 낚으면 붙어 나오는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"공예용 철 끈, 철 클립, 철 나사못","correct":true},{"t":"고무공, 색종이","mis":"SC4-1-u1-X09"},{"t":"철 클립, 색종이, 고무공","mis":"SC4-1-u1-X09"},{"t":"하나도 붙지 않는다","mis":"SC4-1-u1-X10"}],"explanation":["철로 된 것을 찾아요.","셋이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#18','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C14',3,'mc','auto','플라스틱 병 안의 철 클립을 병 밖에서 자석으로 움직일 수 있는 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X09','SC4-1-u1-X17','SC4-1-u1-X15']::text[],false,'{"seq":18,"concept":"SC4-1-u1-C14","difficulty":3,"kind":"mc","stem":"플라스틱 병 안의 철 클립을 병 밖에서 자석으로 움직일 수 있는 까닭은 무엇인가요?","options":[{"t":"자석과 철 클립 사이에 얇은 플라스틱이 있어도 끌어당기는 힘이 작용하기 때문에","correct":true},{"t":"플라스틱 병이 자석에 붙기 때문에","mis":"SC4-1-u1-X09"},{"t":"병 밖에서는 힘이 작용하지 않기 때문에","mis":"SC4-1-u1-X17"},{"t":"클립이 스스로 움직이기 때문에","mis":"SC4-1-u1-X15"}],"explanation":["사이에 플라스틱이 있어요.","그래도 당겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#19','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C23',3,'mc','auto','나침반에 막대자석의 S극을 가까이 했다가 멀리 떨어뜨렸어요. 바늘의 빨간색 부분은 어떻게 되나요?',ARRAY['SC4-1-u1-X29','SC4-1-u1-X30','SC4-1-u1-X28']::text[],false,'{"seq":19,"concept":"SC4-1-u1-C23","difficulty":3,"kind":"mc","stem":"나침반에 막대자석의 S극을 가까이 했다가 멀리 떨어뜨렸어요. 바늘의 빨간색 부분은 어떻게 되나요?","options":[{"t":"S극 쪽으로 다가왔다가 원래 방향으로 되돌아간다","correct":true},{"t":"S극에서 멀어졌다가 그대로 멈춘다","mis":"SC4-1-u1-X29"},{"t":"S극 쪽으로 다가온 채 돌아가지 않는다","mis":"SC4-1-u1-X30"},{"t":"처음부터 끝까지 움직이지 않는다","mis":"SC4-1-u1-X28"}],"explanation":["두 장면이에요.","다가오고 돌아가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#20','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C27',3,'mc','auto','냉장고 자석에 이용한 자석의 성질로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X37','SC4-1-u1-X35','SC4-1-u1-X36']::text[],false,'{"seq":20,"concept":"SC4-1-u1-C27","difficulty":3,"kind":"mc","stem":"냉장고 자석에 이용한 자석의 성질로 알맞은 것은 무엇인가요?","options":[{"t":"자석과 자석에 붙는 물체가 서로 끌어당긴다","correct":true},{"t":"자석의 같은 극끼리 밀어 낸다","mis":"SC4-1-u1-X37"},{"t":"자석은 나무를 끌어당긴다","mis":"SC4-1-u1-X35"},{"t":"자석과 유리가 서로 끌어당긴다","mis":"SC4-1-u1-X36"}],"explanation":["냉장고 문은 철이에요.","당겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#21','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C34',3,'mc','auto','설계 평가 기준 「일상생활을 편리하게 하는 장치를 설계했나요?」에 가장 잘 맞는 설계는 무엇인가요?',ARRAY['SC4-1-u1-X40','SC4-1-u1-X41','SC4-1-u1-X42']::text[],false,'{"seq":21,"concept":"SC4-1-u1-C34","difficulty":3,"kind":"mc","stem":"설계 평가 기준 「일상생활을 편리하게 하는 장치를 설계했나요?」에 가장 잘 맞는 설계는 무엇인가요?","options":[{"t":"실수로 쳐도 쓰러지지 않는 자석 물통","correct":true},{"t":"자석으로 만든 아주 비싼 장식품","mis":"SC4-1-u1-X40"},{"t":"반드시 직접 만들어 본 장치","mis":"SC4-1-u1-X41"},{"t":"친구 설계를 그대로 베낀 장치","mis":"SC4-1-u1-X42"}],"explanation":["편리한가요?","생활에 도움이 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#22','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C38',3,'mc','auto','액체 자석과 막대자석의 같은 점은 무엇인가요?',ARRAY['SC4-1-u1-X49','SC4-1-u1-X50']::text[],false,'{"seq":22,"concept":"SC4-1-u1-C38","difficulty":3,"kind":"mc","stem":"액체 자석과 막대자석의 같은 점은 무엇인가요?","options":[{"t":"둘 다 자석의 성질을 가지고 있다","correct":true},{"t":"둘 다 물처럼 흐른다","mis":"SC4-1-u1-X49"},{"t":"둘 다 단단한 막대 모양이다","mis":"SC4-1-u1-X50"},{"t":"둘 다 철을 밀어 내기만 한다","mis":"SC4-1-u1-X49"}],"explanation":["둘 다 자석이에요.","성질이 같아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#23','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C8',4,'mc','auto','친구가 「반짝이는 숟가락은 금속이니까 자석에 꼭 붙을 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X08','SC4-1-u1-X11']::text[],false,'{"seq":23,"concept":"SC4-1-u1-C8","difficulty":4,"kind":"mc","stem":"친구가 「반짝이는 숟가락은 금속이니까 자석에 꼭 붙을 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「금속이어도 철이 아니면 붙지 않을 수 있어. 무엇으로 만들었는지 자석을 대 보자.」","correct":true},{"t":"「맞아, 반짝이면 모두 붙어.」","mis":"SC4-1-u1-X08"},{"t":"「숟가락이라는 이름이면 다 붙어.」","mis":"SC4-1-u1-X11"},{"t":"「숟가락은 절대 붙지 않아.」","mis":"SC4-1-u1-X11"}],"explanation":["알루미늄을 떠올려요.","물질이 중요해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#24','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C28',4,'mc','auto','자석 창문 닦이의 안쪽 닦이를 뒤집어 같은 극끼리 마주 보게 하면 어떻게 될까요?',ARRAY['SC4-1-u1-X37','SC4-1-u1-X36']::text[],false,'{"seq":24,"concept":"SC4-1-u1-C28","difficulty":4,"kind":"mc","stem":"자석 창문 닦이의 안쪽 닦이를 뒤집어 같은 극끼리 마주 보게 하면 어떻게 될까요?","options":[{"t":"두 닦이가 서로 밀어 내서 함께 붙어 움직이지 않는다","correct":true},{"t":"더 세게 끌어당겨 붙는다","mis":"SC4-1-u1-X37"},{"t":"유리가 자석에 붙는다","mis":"SC4-1-u1-X36"},{"t":"아무 변화도 없다","mis":"SC4-1-u1-X37"}],"explanation":["같은 극이에요.","밀어 내요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_a#25','sci',4,1,'u1','','g4_1_sci_u1_review_a','unit_review','SC4-1-u1-C5',4,'essay','teacher','자석 낚싯대에 철 클립만 붙고 플라스틱 접시와 유리구슬은 붙지 않았어요. 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u1-C5","difficulty":4,"kind":"essay","stem":"자석 낚싯대에 철 클립만 붙고 플라스틱 접시와 유리구슬은 붙지 않았어요. 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 철로 된 물체는 자석에 붙고, 플라스틱이나 유리로 된 물체는 자석에 붙지 않기 때문이다.","scoring_points":["철로 된 물체가 붙음을 썼는가","플라스틱·유리는 붙지 않음을 썼는가","물질을 기준으로 까닭을 썼는가"]},"explanation":["무엇으로 만들었나요?","철인지 봐요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#1','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C2',1,'ox','auto','햇살반 일지 ①의 자석 다트 핀은 과녁판에 착 붙었다가 쉽게 떨어졌어요.',ARRAY['SC4-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C2","difficulty":1,"kind":"ox","stem":"햇살반 일지 ①의 자석 다트 핀은 과녁판에 착 붙었다가 쉽게 떨어졌어요.","answer":"O","reason_options":[{"t":"붙는 부분이 자석으로 되어 있어 붙였다 떼기 쉽기 때문에","correct":true},{"t":"다트 핀 끝이 뾰족해서 꽂혔기 때문에","mis":"SC4-1-u1-X05"}],"mis":"SC4-1-u1-X05","explanation":["셋째 줄을 읽어요.","쉽게 떨어졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["모둠별로 과녁판을 그리고 자석 다트 핀을 던졌다.","같은 칸에 두 개가 붙어서 하나로 세었다.","다트 핀은 착 붙었다가 쉽게 떨어졌다.","친구 가 — 「우리 모둠이 이겼으니 놀이 끝!」"],"title":"햇살반 일지 ① 자석 다트 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#2','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C7',1,'ox','auto','햇살반 일지 ②의 동전은 금속이지만 자석에 붙지 않았어요.',ARRAY['SC4-1-u1-X08']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C7","difficulty":1,"kind":"ox","stem":"햇살반 일지 ②의 동전은 금속이지만 자석에 붙지 않았어요.","answer":"O","reason_options":[{"t":"금속 가운데에도 자석에 붙지 않는 것이 있기 때문에","correct":true},{"t":"동전은 플라스틱으로 만들었기 때문에","mis":"SC4-1-u1-X08"}],"mis":"SC4-1-u1-X08","explanation":["셋째 줄을 읽어요.","붙지 않았어요.","그래서 O예요."],"asset":{"type":"passage","lines":["철 나사못 — 붙었다","플라스틱 단추 — 붙지 않았다","동전 — 붙지 않았다","가위 — 날만 붙었다","친구 나 — 「동전은 금속인데 왜 안 붙지?」"],"title":"햇살반 일지 ② 붙을까, 안 붙을까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#3','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C15',1,'ox','auto','햇살반 일지 ③ 친구 다의 말처럼 자석만 클립을 끌어당겨요.',ARRAY['SC4-1-u1-X18']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C15","difficulty":1,"kind":"ox","stem":"햇살반 일지 ③ 친구 다의 말처럼 자석만 클립을 끌어당겨요.","answer":"X","reason_options":[{"t":"자석과 클립은 서로 끌어당기기 때문에","correct":true},{"t":"철 클립은 자석을 끌어당기지 못하기 때문에","mis":"SC4-1-u1-X18"}],"mis":"SC4-1-u1-X18","explanation":["「서로」를 떠올려요.","둘 다 당겨요.","그래서 X예요."],"asset":{"type":"passage","lines":["얇은 플라스틱 통 속 철 클립을 통 밖 자석으로 움직였다.","자석과 클립 사이에 공책 한 장을 끼워도 클립이 따라왔다.","자석을 멀리 떼니 클립이 따라오지 않았다.","친구 다 — 「자석만 클립을 당기는 거야.」"],"title":"햇살반 일지 ③ 떨어져 있어도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#4','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C21',1,'ox','auto','햇살반 일지 ④ 친구 가의 말처럼 자석을 반으로 자르면 N극만 있는 자석이 남아요.',ARRAY['SC4-1-u1-X25']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C21","difficulty":1,"kind":"ox","stem":"햇살반 일지 ④ 친구 가의 말처럼 자석을 반으로 자르면 N극만 있는 자석이 남아요.","answer":"X","reason_options":[{"t":"잘린 자석도 각각 N극과 S극이 모두 있는 새 자석이 되기 때문에","correct":true},{"t":"자석을 자르면 극이 하나씩 나뉘기 때문에","mis":"SC4-1-u1-X25"}],"mis":"SC4-1-u1-X25","explanation":["극은 항상 두 개예요.","새 자석이 돼요.","그래서 X예요."],"asset":{"type":"passage","lines":["막대자석 두 개의 N극끼리 가까이 하니 밀어 냈다.","N극과 S극을 가까이 하니 끌어당겼다.","고리 자석 윗면에 S극을 대니 끌려 왔다.","친구 가 — 「자석을 반으로 자르면 N극만 남아.」"],"title":"햇살반 일지 ④ 극 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#5','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C24',1,'ox','auto','햇살반 일지 ⑤ 친구 나의 말처럼 나침반 바늘은 그냥 철이에요.',ARRAY['SC4-1-u1-X28']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C24","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑤ 친구 나의 말처럼 나침반 바늘은 그냥 철이에요.","answer":"X","reason_options":[{"t":"바늘은 N극에 밀리고 S극에 끌리는 자석이기 때문에","correct":true},{"t":"바늘은 자석의 어느 극에든 끌려오기 때문에","mis":"SC4-1-u1-X28"}],"mis":"SC4-1-u1-X28","explanation":["N극에 밀려나요.","바늘도 자석이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["나침반을 평평한 책상에 놓고 바늘이 멈추길 기다렸다.","S극을 가까이 하니 빨간색 부분이 다가왔다.","자석을 치우니 바늘이 원래 방향으로 돌아갔다.","친구 나 — 「바늘은 그냥 철이야.」"],"title":"햇살반 일지 ⑤ 나침반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#6','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C29',1,'ox','auto','햇살반 일지 ⑥ 친구 다의 말처럼 자석 걸이에 나무 주걱을 붙일 수 있어요.',ARRAY['SC4-1-u1-X35']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C29","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑥ 친구 다의 말처럼 자석 걸이에 나무 주걱을 붙일 수 있어요.","answer":"X","reason_options":[{"t":"나무는 자석에 붙지 않기 때문에","correct":true},{"t":"자석 걸이에는 무엇이든 붙기 때문에","mis":"SC4-1-u1-X35"}],"mis":"SC4-1-u1-X35","explanation":["나무를 떠올려요.","안 붙어요.","그래서 X예요."],"asset":{"type":"passage","lines":["자석 클립 통 — 뚜껑에 자석이 있다.","자석 창문 닦이 — 안쪽과 바깥쪽에 자석이 있다.","자석 양치 컵 걸이 — 컵 바닥에 자석이 있다.","친구 다 — 「자석 걸이에 나무 주걱도 붙여 보자.」"],"title":"햇살반 일지 ⑥ 자석을 이용한 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#7','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C34',1,'ox','auto','햇살반 일지 ⑦ 친구 가의 말처럼 직접 만들지 않았으니 설계가 아니에요.',ARRAY['SC4-1-u1-X41']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C34","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑦ 친구 가의 말처럼 직접 만들지 않았으니 설계가 아니에요.","answer":"X","reason_options":[{"t":"설계한 것이 꼭 만들기로 이어지지 않아도 되기 때문에","correct":true},{"t":"설계는 반드시 만들어야 하기 때문에","mis":"SC4-1-u1-X41"}],"mis":"SC4-1-u1-X41","explanation":["설계를 떠올려요.","만들지 않아도 돼요.","그래서 X예요."],"asset":{"type":"passage","lines":["불편한 점 — 연필이 책상에서 자꾸 굴러떨어진다.","설계 — 연필에 철 조각, 책상 홈에 자석을 붙인다.","이용한 성질 — 자석과 철이 서로 끌어당긴다.","친구 가 — 「직접 만들지 않았으니 설계가 아니야.」"],"title":"햇살반 일지 ⑦ 우리 모둠 설계도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#8','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C39',1,'ox','auto','햇살반 일지 ⑧ 친구 나의 말처럼 자석은 교실에서만 쓰여요.',ARRAY['SC4-1-u1-X50']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C39","difficulty":1,"kind":"ox","stem":"햇살반 일지 ⑧ 친구 나의 말처럼 자석은 교실에서만 쓰여요.","answer":"X","reason_options":[{"t":"우주, 의료, 생활 등 여러 첨단 과학 분야에서 쓰이기 때문에","correct":true},{"t":"자석은 막대자석 모양뿐이기 때문에","mis":"SC4-1-u1-X50"}],"mis":"SC4-1-u1-X50","explanation":["일지를 읽어요.","우주와 몸속에도 써요.","그래서 X예요."],"asset":{"type":"passage","lines":["우주 쓰레기를 자석의 성질로 모으는 장치를 연구한다.","몸 밖에서 조종하는 아주 작은 로봇이 있다.","지폐에는 자석 잉크가 쓰이기도 한다.","친구 나 — 「자석은 교실에서만 쓰여.」"],"title":"햇살반 일지 ⑧ 첨단 과학 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#9','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C2',2,'mc','auto','자석 다트 핀이 안전한 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X05','SC4-1-u1-X04']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C2","difficulty":2,"kind":"mc","stem":"자석 다트 핀이 안전한 까닭은 무엇인가요?","options":[{"t":"끝이 뾰족하지 않기 때문에","correct":true},{"t":"끝이 아주 뾰족하기 때문에","mis":"SC4-1-u1-X05"},{"t":"세게 던질수록 안전하기 때문에","mis":"SC4-1-u1-X04"},{"t":"과녁판에 깊이 꽂히기 때문에","mis":"SC4-1-u1-X05"}],"explanation":["끝을 떠올려요.","뾰족하지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#10','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C8',2,'mc','auto','같은 컵이라도 자석에 붙기도 하고 붙지 않기도 하는 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X11']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C8","difficulty":2,"kind":"mc","stem":"같은 컵이라도 자석에 붙기도 하고 붙지 않기도 하는 까닭은 무엇인가요?","options":[{"t":"컵을 만든 물질이 다를 수 있기 때문에","correct":true},{"t":"컵이라는 이름이 같기 때문에","mis":"SC4-1-u1-X11"},{"t":"컵의 크기가 다르기 때문에","mis":"SC4-1-u1-X11"},{"t":"컵은 모두 자석에 붙기 때문에","mis":"SC4-1-u1-X11"}],"explanation":["이름이 아니에요.","물질이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#11','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C16',2,'mc','auto','자석이 아닌 나무젓가락을 철 클립에 가까이 하면 어떻게 되나요?',ARRAY['SC4-1-u1-X19']::text[],false,'{"seq":11,"concept":"SC4-1-u1-C16","difficulty":2,"kind":"mc","stem":"자석이 아닌 나무젓가락을 철 클립에 가까이 하면 어떻게 되나요?","options":[{"t":"클립이 끌려 오지 않는다","correct":true},{"t":"클립이 나무젓가락에 붙는다","mis":"SC4-1-u1-X19"},{"t":"클립이 공중에 뜬다","mis":"SC4-1-u1-X19"},{"t":"클립이 나무젓가락을 밀어 낸다","mis":"SC4-1-u1-X19"}],"explanation":["나무젓가락은 자석이 아니에요.","당기지 못해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#12','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C18',2,'mc','auto','모양이 다른 자석들의 극에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u1-X21']::text[],false,'{"seq":12,"concept":"SC4-1-u1-C18","difficulty":2,"kind":"mc","stem":"모양이 다른 자석들의 극에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"막대자석, 말굽자석, 동전 모양 자석, 고리 자석 모두 극이 두 개이다","correct":true},{"t":"막대자석만 극이 두 개이다","mis":"SC4-1-u1-X21"},{"t":"동전 모양 자석은 극이 하나이다","mis":"SC4-1-u1-X21"},{"t":"고리 자석은 극이 없다","mis":"SC4-1-u1-X21"}],"explanation":["모양과 상관없어요.","항상 두 개예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#13','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C24',2,'mc','auto','나침반 바늘이 자석이라는 것을 알 수 있는 관찰은 무엇인가요?',ARRAY['SC4-1-u1-X28','SC4-1-u1-X31']::text[],false,'{"seq":13,"concept":"SC4-1-u1-C24","difficulty":2,"kind":"mc","stem":"나침반 바늘이 자석이라는 것을 알 수 있는 관찰은 무엇인가요?","options":[{"t":"자석의 N극에는 밀려나고 S극에는 끌려온다","correct":true},{"t":"자석의 어느 극에든 끌려온다","mis":"SC4-1-u1-X28"},{"t":"자석을 가까이 해도 움직이지 않는다","mis":"SC4-1-u1-X28"},{"t":"바늘이 늘 빨간색이다","mis":"SC4-1-u1-X31"}],"explanation":["밀려나는 모습이에요.","철은 밀려나지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#14','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C26',2,'mc','auto','냉장고 문 안쪽에 자석이 있으면 어떤 점이 편리한가요?',ARRAY['SC4-1-u1-X34','SC4-1-u1-X35']::text[],false,'{"seq":14,"concept":"SC4-1-u1-C26","difficulty":2,"kind":"mc","stem":"냉장고 문 안쪽에 자석이 있으면 어떤 점이 편리한가요?","options":[{"t":"냉장고 문을 쉽게 열고 닫을 수 있다","correct":true},{"t":"냉장고 속 음식이 차가워진다","mis":"SC4-1-u1-X34"},{"t":"냉장고가 가벼워진다","mis":"SC4-1-u1-X34"},{"t":"냉장고에 나무 주걱을 붙일 수 있다","mis":"SC4-1-u1-X35"}],"explanation":["문을 떠올려요.","여닫기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#15','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C31',2,'mc','auto','장치를 설계할 때 정리할 세 가지로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X43','SC4-1-u1-X42']::text[],false,'{"seq":15,"concept":"SC4-1-u1-C31","difficulty":2,"kind":"mc","stem":"장치를 설계할 때 정리할 세 가지로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 상황에서 쓰는지, 어느 부분에 자석을 쓰는지, 어떤 성질을 이용하는지","correct":true},{"t":"얼마에 팔지, 누구에게 팔지, 언제 팔지","mis":"SC4-1-u1-X43"},{"t":"무슨 색인지, 얼마나 큰지, 얼마나 무거운지","mis":"SC4-1-u1-X43"},{"t":"누가 먼저 끝냈는지, 누가 더 빨랐는지, 누가 칭찬받았는지","mis":"SC4-1-u1-X42"}],"explanation":["설계해요를 떠올려요.","상황·위치·성질이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#16','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C39',2,'mc','auto','자석의 크기와 모습에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u1-X50','SC4-1-u1-X49']::text[],false,'{"seq":16,"concept":"SC4-1-u1-C39","difficulty":2,"kind":"mc","stem":"자석의 크기와 모습에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"아주 큰 자석부터 눈에 보이지 않을 만큼 작은 자석까지 다양하다","correct":true},{"t":"자석은 모두 손바닥만 하다","mis":"SC4-1-u1-X50"},{"t":"자석은 막대 모양만 있다","mis":"SC4-1-u1-X50"},{"t":"흐르는 자석은 없다","mis":"SC4-1-u1-X49"}],"explanation":["여러 자석을 떠올려요.","다양해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#17','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C8',3,'ox','auto','철 캔과 알루미늄 캔은 모양이 같으면 둘 다 자석에 붙어요.',ARRAY['SC4-1-u1-X11']::text[],false,'{"seq":17,"concept":"SC4-1-u1-C8","difficulty":3,"kind":"ox","stem":"철 캔과 알루미늄 캔은 모양이 같으면 둘 다 자석에 붙어요.","answer":"X","reason_options":[{"t":"모양이 같아도 만든 물질이 달라 철 캔만 붙기 때문에","correct":true},{"t":"이름과 모양이 같으면 붙는지도 같기 때문에","mis":"SC4-1-u1-X11"}],"mis":"SC4-1-u1-X11","explanation":["물질을 떠올려요.","알루미늄은 안 붙어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#18','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C17',3,'ox','auto','막대자석에서 철 클립이 많이 붙는 부분은 한 군데예요.',ARRAY['SC4-1-u1-X20']::text[],false,'{"seq":18,"concept":"SC4-1-u1-C17","difficulty":3,"kind":"ox","stem":"막대자석에서 철 클립이 많이 붙는 부분은 한 군데예요.","answer":"X","reason_options":[{"t":"막대자석의 양쪽 끝 두 군데에 많이 붙기 때문에","correct":true},{"t":"클립은 가운데 한 군데에만 많이 붙기 때문에","mis":"SC4-1-u1-X20"}],"mis":"SC4-1-u1-X20","explanation":["극을 떠올려요.","양쪽 끝이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#19','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C24',3,'ox','auto','나침반 바늘과 자석의 극도 자석의 극끼리처럼 서로 밀어 내거나 끌어당겨요.',ARRAY['SC4-1-u1-X28']::text[],false,'{"seq":19,"concept":"SC4-1-u1-C24","difficulty":3,"kind":"ox","stem":"나침반 바늘과 자석의 극도 자석의 극끼리처럼 서로 밀어 내거나 끌어당겨요.","answer":"O","reason_options":[{"t":"나침반 바늘도 자석의 성질을 가지고 있기 때문에","correct":true},{"t":"나침반 바늘은 철이라서 끌어당기기만 하기 때문에","mis":"SC4-1-u1-X28"}],"mis":"SC4-1-u1-X28","explanation":["바늘도 자석이에요.","밀고 당겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#20','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C28',3,'ox','auto','가방 자석 단추는 두 단추에 든 자석의 다른 극끼리 끌어당겨 닫혀요.',ARRAY['SC4-1-u1-X37']::text[],false,'{"seq":20,"concept":"SC4-1-u1-C28","difficulty":3,"kind":"ox","stem":"가방 자석 단추는 두 단추에 든 자석의 다른 극끼리 끌어당겨 닫혀요.","answer":"O","reason_options":[{"t":"다른 극끼리는 서로 끌어당기기 때문에","correct":true},{"t":"같은 극끼리 끌어당기기 때문에","mis":"SC4-1-u1-X37"}],"mis":"SC4-1-u1-X37","explanation":["두 단추에 자석이 있어요.","다른 극끼리예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#21','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C32',3,'ox','auto','쓰러지지 않는 물통의 받침대를 나무로 바꾸어도 물통은 받침대에 꼭 붙어요.',ARRAY['SC4-1-u1-X44']::text[],false,'{"seq":21,"concept":"SC4-1-u1-C32","difficulty":3,"kind":"ox","stem":"쓰러지지 않는 물통의 받침대를 나무로 바꾸어도 물통은 받침대에 꼭 붙어요.","answer":"X","reason_options":[{"t":"나무는 자석에 붙지 않기 때문에","correct":true},{"t":"자석은 어떤 받침대든 끌어당기기 때문에","mis":"SC4-1-u1-X44"}],"mis":"SC4-1-u1-X44","explanation":["나무를 떠올려요.","안 붙어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#22','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C36',3,'ox','auto','우주 쓰레기 청소 장치는 자석과 자석에 붙는 물체가 서로 끌어당기는 힘을 이용해 쓰레기를 모아요.',ARRAY['SC4-1-u1-X47']::text[],false,'{"seq":22,"concept":"SC4-1-u1-C36","difficulty":3,"kind":"ox","stem":"우주 쓰레기 청소 장치는 자석과 자석에 붙는 물체가 서로 끌어당기는 힘을 이용해 쓰레기를 모아요.","answer":"O","reason_options":[{"t":"자석의 성질로 우주 쓰레기를 끌어당겨 모으기 때문에","correct":true},{"t":"우주에서는 자석의 성질이 쓰이지 않기 때문에","mis":"SC4-1-u1-X47"}],"mis":"SC4-1-u1-X47","explanation":["모으는 장치예요.","끌어당겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#23','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C15',4,'mc','auto','친구가 「자석보다 무거운 철 기둥은 자석을 끌어당기지 못해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X18','SC4-1-u1-X15']::text[],false,'{"seq":23,"concept":"SC4-1-u1-C15","difficulty":4,"kind":"mc","stem":"친구가 「자석보다 무거운 철 기둥은 자석을 끌어당기지 못해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「무거운 철 기둥에 자석을 대면 손이 끌려가. 자석과 철은 서로 끌어당겨.」","correct":true},{"t":"「맞아, 가벼운 쪽만 끌려가.」","mis":"SC4-1-u1-X18"},{"t":"「철 기둥은 자석을 밀어 내.」","mis":"SC4-1-u1-X18"},{"t":"「닿기 전에는 아무 힘도 없어.」","mis":"SC4-1-u1-X15"}],"explanation":["손이 끌려가요.","서로 당겨요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#24','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C34',4,'mc','auto','친구가 「우리 모둠 설계는 이미 있는 자석 장치를 조금 바꾼 거라서 좋은 설계가 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X41','SC4-1-u1-X42','SC4-1-u1-X40']::text[],false,'{"seq":24,"concept":"SC4-1-u1-C34","difficulty":4,"kind":"mc","stem":"친구가 「우리 모둠 설계는 이미 있는 자석 장치를 조금 바꾼 거라서 좋은 설계가 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「이미 있는 장치를 바꾸어 더 편리하게 한 것도 좋은 설계야.」","correct":true},{"t":"「맞아, 완전히 새로워야만 해.」","mis":"SC4-1-u1-X41"},{"t":"「다른 모둠 것을 놀리면 돼.」","mis":"SC4-1-u1-X42"},{"t":"「자석을 빼고 다시 설계하자.」","mis":"SC4-1-u1-X40"}],"explanation":["부담을 느끼지 않아요.","바꾸어도 돼요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_b#25','sci',4,1,'u1','','g4_1_sci_u1_review_b','unit_review','SC4-1-u1-C20',4,'essay','teacher','빨대에 끼운 고리 자석의 윗면이 무슨 극인지 알아보는 방법을 쓰고, 윗면에 N극을 가까이 했더니 밀려났을 때 윗면의 극과 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u1-C20","difficulty":4,"kind":"essay","stem":"빨대에 끼운 고리 자석의 윗면이 무슨 극인지 알아보는 방법을 쓰고, 윗면에 N극을 가까이 했더니 밀려났을 때 윗면의 극과 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 막대자석의 N극과 S극을 차례로 고리 자석 윗면에 가까이 해 본다. N극을 가까이 했을 때 밀려났으므로 윗면은 N극이다. 같은 극끼리는 서로 밀어 내기 때문이다.","scoring_points":["극을 알아보는 방법을 썼는가","윗면이 N극임을 썼는가","같은 극끼리 밀어 냄을 근거로 썼는가"]},"explanation":["막대자석을 대 봐요.","밀려났어요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#1','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C3',1,'mc','auto','햇살반 일지 ① 친구 가의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC4-1-u1-X03','SC4-1-u1-X04','SC4-1-u1-X02']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C3","difficulty":1,"kind":"mc","stem":"햇살반 일지 ① 친구 가의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"이기는 것보다 자석에 관심과 흥미를 갖는 것이 더 중요하다","correct":true},{"t":"이긴 모둠만 놀이를 계속한다","mis":"SC4-1-u1-X03"},{"t":"진 모둠은 다트 핀을 세게 던져야 한다","mis":"SC4-1-u1-X04"},{"t":"놀이 규칙은 지키지 않아도 된다","mis":"SC4-1-u1-X02"}],"explanation":["놀이의 뜻을 떠올려요.","흥미가 먼저예요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠별로 과녁판을 그리고 자석 다트 핀을 던졌다.","같은 칸에 두 개가 붙어서 하나로 세었다.","다트 핀은 착 붙었다가 쉽게 떨어졌다.","친구 가 — 「우리 모둠이 이겼으니 놀이 끝!」"],"title":"햇살반 일지 ① 자석 다트 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#2','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C9',1,'mc','auto','햇살반 일지 ②의 가위에서 날만 붙은 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X08','SC4-1-u1-X12','SC4-1-u1-X11']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C9","difficulty":1,"kind":"mc","stem":"햇살반 일지 ②의 가위에서 날만 붙은 까닭은 무엇인가요?","options":[{"t":"날은 철로, 손잡이는 플라스틱으로 되어 있기 때문에","correct":true},{"t":"날이 더 반짝이기 때문에","mis":"SC4-1-u1-X08"},{"t":"가위는 모두 철로 되어 있기 때문에","mis":"SC4-1-u1-X12"},{"t":"손잡이가 더 무겁기 때문에","mis":"SC4-1-u1-X11"}],"explanation":["부분마다 물질이 달라요.","날은 철이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["철 나사못 — 붙었다","플라스틱 단추 — 붙지 않았다","동전 — 붙지 않았다","가위 — 날만 붙었다","친구 나 — 「동전은 금속인데 왜 안 붙지?」"],"title":"햇살반 일지 ② 붙을까, 안 붙을까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#3','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C13',1,'mc','auto','햇살반 일지 ③에서 자석을 멀리 떼었을 때 클립이 따라오지 않은 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X17','SC4-1-u1-X18']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C13","difficulty":1,"kind":"mc","stem":"햇살반 일지 ③에서 자석을 멀리 떼었을 때 클립이 따라오지 않은 까닭은 무엇인가요?","options":[{"t":"자석과 클립 사이가 너무 멀어졌기 때문에","correct":true},{"t":"사이에 종이를 넣었기 때문에","mis":"SC4-1-u1-X17"},{"t":"클립이 자석을 밀어 냈기 때문에","mis":"SC4-1-u1-X18"},{"t":"통이 플라스틱이기 때문에","mis":"SC4-1-u1-X17"}],"explanation":["셋째 줄을 읽어요.","너무 멀어요.","첫 번째예요."],"asset":{"type":"passage","lines":["얇은 플라스틱 통 속 철 클립을 통 밖 자석으로 움직였다.","자석과 클립 사이에 공책 한 장을 끼워도 클립이 따라왔다.","자석을 멀리 떼니 클립이 따라오지 않았다.","친구 다 — 「자석만 클립을 당기는 거야.」"],"title":"햇살반 일지 ③ 떨어져 있어도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#4','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C20',1,'mc','auto','햇살반 일지 ④에서 고리 자석 윗면에 S극을 대니 끌려 왔어요. 고리 자석 윗면은 무슨 극인가요?',ARRAY['SC4-1-u1-X24','SC4-1-u1-X21']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C20","difficulty":1,"kind":"mc","stem":"햇살반 일지 ④에서 고리 자석 윗면에 S극을 대니 끌려 왔어요. 고리 자석 윗면은 무슨 극인가요?","options":[{"t":"N극","correct":true},{"t":"S극","mis":"SC4-1-u1-X24"},{"t":"극이 없다","mis":"SC4-1-u1-X21"},{"t":"N극과 S극이 섞여 있다","mis":"SC4-1-u1-X21"}],"explanation":["셋째 줄을 읽어요.","끌려 왔어요.","N극이에요."],"asset":{"type":"passage","lines":["막대자석 두 개의 N극끼리 가까이 하니 밀어 냈다.","N극과 S극을 가까이 하니 끌어당겼다.","고리 자석 윗면에 S극을 대니 끌려 왔다.","친구 가 — 「자석을 반으로 자르면 N극만 남아.」"],"title":"햇살반 일지 ④ 극 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#5','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C22',1,'mc','auto','햇살반 일지 ⑤처럼 나침반을 쓸 때 바르게 한 것은 무엇인가요?',ARRAY['SC4-1-u1-X32','SC4-1-u1-X33']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C22","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑤처럼 나침반을 쓸 때 바르게 한 것은 무엇인가요?","options":[{"t":"평평한 곳에 놓고 바늘이 멈추길 기다렸다","correct":true},{"t":"자석 옆에 나침반을 두었다","mis":"SC4-1-u1-X32"},{"t":"나침반을 계속 흔들었다","mis":"SC4-1-u1-X32"},{"t":"바늘이 돌 때 바로 읽었다","mis":"SC4-1-u1-X33"}],"explanation":["첫 줄을 읽어요.","멈추길 기다려요.","첫 번째예요."],"asset":{"type":"passage","lines":["나침반을 평평한 책상에 놓고 바늘이 멈추길 기다렸다.","S극을 가까이 하니 빨간색 부분이 다가왔다.","자석을 치우니 바늘이 원래 방향으로 돌아갔다.","친구 나 — 「바늘은 그냥 철이야.」"],"title":"햇살반 일지 ⑤ 나침반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#6','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C28',1,'mc','auto','햇살반 일지 ⑥의 자석 창문 닦이가 이용한 성질은 무엇인가요?',ARRAY['SC4-1-u1-X36','SC4-1-u1-X37']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C28","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑥의 자석 창문 닦이가 이용한 성질은 무엇인가요?","options":[{"t":"자석의 다른 극끼리 서로 끌어당기는 성질","correct":true},{"t":"자석과 유리가 서로 끌어당기는 성질","mis":"SC4-1-u1-X36"},{"t":"자석의 같은 극끼리 끌어당기는 성질","mis":"SC4-1-u1-X37"},{"t":"자석과 물이 서로 끌어당기는 성질","mis":"SC4-1-u1-X36"}],"explanation":["둘째 줄을 읽어요.","양쪽에 자석이 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["자석 클립 통 — 뚜껑에 자석이 있다.","자석 창문 닦이 — 안쪽과 바깥쪽에 자석이 있다.","자석 양치 컵 걸이 — 컵 바닥에 자석이 있다.","친구 다 — 「자석 걸이에 나무 주걱도 붙여 보자.」"],"title":"햇살반 일지 ⑥ 자석을 이용한 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#7','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C31',1,'mc','auto','햇살반 일지 ⑦의 설계는 어떤 불편함에서 시작했나요?',ARRAY['SC4-1-u1-X43']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C31","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑦의 설계는 어떤 불편함에서 시작했나요?","options":[{"t":"연필이 책상에서 자꾸 굴러떨어진다","correct":true},{"t":"물감 물통이 자꾸 쓰러진다","mis":"SC4-1-u1-X43"},{"t":"이불을 개기 어렵다","mis":"SC4-1-u1-X43"},{"t":"신발 끈이 자꾸 풀린다","mis":"SC4-1-u1-X43"}],"explanation":["첫 줄을 읽어요.","불편한 점이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["불편한 점 — 연필이 책상에서 자꾸 굴러떨어진다.","설계 — 연필에 철 조각, 책상 홈에 자석을 붙인다.","이용한 성질 — 자석과 철이 서로 끌어당긴다.","친구 가 — 「직접 만들지 않았으니 설계가 아니야.」"],"title":"햇살반 일지 ⑦ 우리 모둠 설계도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#8','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C37',1,'mc','auto','햇살반 일지 ⑧의 아주 작은 로봇은 어디에서 일하나요?',ARRAY['SC4-1-u1-X47','SC4-1-u1-X49','SC4-1-u1-X51']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C37","difficulty":1,"kind":"mc","stem":"햇살반 일지 ⑧의 아주 작은 로봇은 어디에서 일하나요?","options":[{"t":"사람의 몸속","correct":true},{"t":"우주 정거장 밖","mis":"SC4-1-u1-X47"},{"t":"지폐 속","mis":"SC4-1-u1-X49"},{"t":"캔 분리수거장","mis":"SC4-1-u1-X51"}],"explanation":["둘째 줄을 읽어요.","몸 밖에서 조종해요.","몸속이에요."],"asset":{"type":"passage","lines":["우주 쓰레기를 자석의 성질로 모으는 장치를 연구한다.","몸 밖에서 조종하는 아주 작은 로봇이 있다.","지폐에는 자석 잉크가 쓰이기도 한다.","친구 나 — 「자석은 교실에서만 쓰여.」"],"title":"햇살반 일지 ⑧ 첨단 과학 기술"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#9','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C3',2,'error','auto','자석 다트 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X04','SC4-1-u1-X03']::text[],false,'{"seq":9,"concept":"SC4-1-u1-C3","difficulty":2,"kind":"error","stem":"자석 다트 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「더 멀리 날아가게 힘껏 던져 보자.」","correct":true,"mis_target":"SC4-1-u1-X04"},{"t":"친구 가 — 「던지는 곳 앞에 친구가 없는지 보자.」","mis":"SC4-1-u1-X03"},{"t":"친구 다 — 「교실 자석 말고 다트 핀으로 하자.」","mis":"SC4-1-u1-X04"}],"explanation":["안전을 떠올려요.","살살 던져요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#10','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C9',2,'error','auto','공책에 자석을 대 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X12','SC4-1-u1-X10','SC4-1-u1-X09']::text[],false,'{"seq":10,"concept":"SC4-1-u1-C9","difficulty":2,"kind":"error","stem":"공책에 자석을 대 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「공책은 모두 붙거나 모두 안 붙어야 해.」","correct":true,"mis_target":"SC4-1-u1-X12"},{"t":"친구 가 — 「스프링은 철이라 붙었어.」","mis":"SC4-1-u1-X10"},{"t":"친구 나 — 「속지는 종이라 안 붙었어.」","mis":"SC4-1-u1-X09"}],"explanation":["부분마다 달라요.","스프링만 붙어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#11','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C13',2,'error','auto','유리컵 속 철 집게 실험을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X16','SC4-1-u1-X17']::text[],false,'{"seq":11,"concept":"SC4-1-u1-C13","difficulty":2,"kind":"error","stem":"유리컵 속 철 집게 실험을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「자석을 아주 멀리 해도 철 집게는 계속 따라와.」","correct":true,"mis_target":"SC4-1-u1-X16"},{"t":"친구 나 — 「컵 밖에서 자석을 움직이니 철 집게가 따라왔어.」","mis":"SC4-1-u1-X17"},{"t":"친구 다 — 「자석을 멀리 떨어뜨리니 철 집게가 바닥으로 떨어졌어.」","mis":"SC4-1-u1-X16"}],"explanation":["거리를 떠올려요.","너무 멀면 떨어져요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#12','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C21',2,'error','auto','자석의 극을 배우고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X26','SC4-1-u1-X20','SC4-1-u1-X21']::text[],false,'{"seq":12,"concept":"SC4-1-u1-C21","difficulty":2,"kind":"error","stem":"자석의 극을 배우고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「극은 빨간색으로 칠한 쪽에만 있어.」","correct":true,"mis_target":"SC4-1-u1-X26"},{"t":"친구 가 — 「극은 철을 끌어당기는 힘이 가장 센 곳이야.」","mis":"SC4-1-u1-X20"},{"t":"친구 나 — 「극은 N극과 S극 두 개야.」","mis":"SC4-1-u1-X21"}],"explanation":["극은 양쪽 끝이에요.","색과 상관없어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#13','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C25',2,'error','auto','나침반을 쓰며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X32','SC4-1-u1-X33']::text[],false,'{"seq":13,"concept":"SC4-1-u1-C25","difficulty":2,"kind":"error","stem":"나침반을 쓰며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「막대자석 바로 옆에서 나침반을 읽자.」","correct":true,"mis_target":"SC4-1-u1-X32"},{"t":"친구 가 — 「평평한 곳에 놓고 바늘이 멈출 때까지 기다리자.」","mis":"SC4-1-u1-X33"},{"t":"친구 다 — 「주변에 철로 된 물건이 없는지 보자.」","mis":"SC4-1-u1-X32"}],"explanation":["자석이 영향을 줘요.","멀리해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#14','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C28',2,'error','auto','생활용품의 성질을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X36','SC4-1-u1-X37']::text[],false,'{"seq":14,"concept":"SC4-1-u1-C28","difficulty":2,"kind":"error","stem":"생활용품의 성질을 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「자석 창문 닦이는 자석과 유리가 끌어당기는 성질이야.」","correct":true,"mis_target":"SC4-1-u1-X36"},{"t":"친구 나 — 「자석 클립 통은 자석과 철이 끌어당기는 성질이야.」","mis":"SC4-1-u1-X36"},{"t":"친구 다 — 「가방 자석 단추는 다른 극끼리 끌어당기는 성질이야.」","mis":"SC4-1-u1-X37"}],"explanation":["유리는 안 붙어요.","다른 극끼리예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#15','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C32',2,'error','auto','쓰러지지 않는 물통 설계도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X44','SC4-1-u1-X46']::text[],false,'{"seq":15,"concept":"SC4-1-u1-C32","difficulty":2,"kind":"error","stem":"쓰러지지 않는 물통 설계도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「받침대를 플라스틱으로 바꿔도 물통이 꼭 붙을 거야.」","correct":true,"mis_target":"SC4-1-u1-X44"},{"t":"친구 가 — 「물통 바닥의 자석과 철 받침대가 끌어당겨.」","mis":"SC4-1-u1-X44"},{"t":"친구 나 — 「실수로 쳐도 잘 쓰러지지 않겠어.」","mis":"SC4-1-u1-X46"}],"explanation":["플라스틱을 떠올려요.","자석에 안 붙어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#16','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C38',2,'error','auto','액체 자석 이야기를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u1-X49','SC4-1-u1-X50']::text[],false,'{"seq":16,"concept":"SC4-1-u1-C38","difficulty":2,"kind":"error","stem":"액체 자석 이야기를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「흐르는 것은 자석의 성질을 가질 수 없어.」","correct":true,"mis_target":"SC4-1-u1-X49"},{"t":"친구 가 — 「액체 자석은 지폐의 자석 잉크로 쓰여.」","mis":"SC4-1-u1-X49"},{"t":"친구 다 — 「의료 기구에도 쓰인대.」","mis":"SC4-1-u1-X50"}],"explanation":["액체 자석을 떠올려요.","흘러도 자석이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#17','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C12',3,'mc','auto','종이 물고기에 끼운 철 클립이 자석 낚싯대에 닿기 전에 끌려 왔어요. 그 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X09','SC4-1-u1-X15','SC4-1-u1-X18']::text[],false,'{"seq":17,"concept":"SC4-1-u1-C12","difficulty":3,"kind":"mc","stem":"종이 물고기에 끼운 철 클립이 자석 낚싯대에 닿기 전에 끌려 왔어요. 그 까닭은 무엇인가요?","options":[{"t":"자석과 철 클립은 조금 떨어져 있어도 서로 끌어당기기 때문에","correct":true},{"t":"종이 물고기가 자석에 붙기 때문에","mis":"SC4-1-u1-X09"},{"t":"클립과 자석이 닿아야만 끌려오기 때문에","mis":"SC4-1-u1-X15"},{"t":"자석만 클립을 끌어당기기 때문에","mis":"SC4-1-u1-X18"}],"explanation":["닿기 전이에요.","떨어져 있어도요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#18','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C20',3,'mc','auto','고리 자석 윗면에 막대자석의 N극을 가까이 했더니 밀려났어요. 고리 자석 아랫면은 무슨 극인가요?',ARRAY['SC4-1-u1-X24','SC4-1-u1-X21']::text[],false,'{"seq":18,"concept":"SC4-1-u1-C20","difficulty":3,"kind":"mc","stem":"고리 자석 윗면에 막대자석의 N극을 가까이 했더니 밀려났어요. 고리 자석 아랫면은 무슨 극인가요?","options":[{"t":"S극","correct":true},{"t":"N극","mis":"SC4-1-u1-X24"},{"t":"극이 없다","mis":"SC4-1-u1-X21"},{"t":"윗면과 아랫면 모두 극이 없다","mis":"SC4-1-u1-X21"}],"explanation":["윗면은 N극이에요.","반대쪽은 다른 극이에요.","S극이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#19','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C22',3,'mc','auto','나침반 근처에 있던 철 필통을 치웠더니 바늘이 가리키는 방향이 달라졌어요. 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u1-X32','SC4-1-u1-X28','SC4-1-u1-X33']::text[],false,'{"seq":19,"concept":"SC4-1-u1-C22","difficulty":3,"kind":"mc","stem":"나침반 근처에 있던 철 필통을 치웠더니 바늘이 가리키는 방향이 달라졌어요. 알 수 있는 것은 무엇인가요?","options":[{"t":"나침반 주변의 철이나 자석이 바늘에 영향을 줄 수 있다","correct":true},{"t":"나침반은 주변 물체와 상관없다","mis":"SC4-1-u1-X32"},{"t":"철 필통이 바늘을 철로 바꾸었다","mis":"SC4-1-u1-X28"},{"t":"나침반은 방향을 찾는 도구가 아니다","mis":"SC4-1-u1-X33"}],"explanation":["주변을 살펴야 해요.","영향을 줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#20','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C26',3,'mc','auto','스마트 기기 덮개에 든 작은 자석들이 하는 일은 무엇인가요?',ARRAY['SC4-1-u1-X34']::text[],false,'{"seq":20,"concept":"SC4-1-u1-C26","difficulty":3,"kind":"mc","stem":"스마트 기기 덮개에 든 작은 자석들이 하는 일은 무엇인가요?","options":[{"t":"덮개가 화면에 꼭 붙어 화면을 보호하고 접어 고정할 수 있게 한다","correct":true},{"t":"화면을 더 밝게 만든다","mis":"SC4-1-u1-X34"},{"t":"화면의 글씨를 크게 만든다","mis":"SC4-1-u1-X34"},{"t":"기기를 더 무겁게 만든다","mis":"SC4-1-u1-X34"}],"explanation":["덮개를 떠올려요.","꼭 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#21','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C31',3,'mc','auto','자석 신발 끈 매듭기는 어떤 불편함을 해결한 장치인가요?',ARRAY['SC4-1-u1-X43']::text[],false,'{"seq":21,"concept":"SC4-1-u1-C31","difficulty":3,"kind":"mc","stem":"자석 신발 끈 매듭기는 어떤 불편함을 해결한 장치인가요?","options":[{"t":"신발 끈이 자꾸 풀리는 불편함","correct":true},{"t":"물감 물통이 쓰러지는 불편함","mis":"SC4-1-u1-X43"},{"t":"연필이 굴러떨어지는 불편함","mis":"SC4-1-u1-X43"},{"t":"이불 귀퉁이가 맞지 않는 불편함","mis":"SC4-1-u1-X43"}],"explanation":["신발 끈이에요.","자꾸 풀려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#22','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C39',3,'mc','auto','자석의 성질을 이용한 첨단 과학 기술이 아닌 것은 무엇인가요?',ARRAY['SC4-1-u1-X47','SC4-1-u1-X48','SC4-1-u1-X49']::text[],false,'{"seq":22,"concept":"SC4-1-u1-C39","difficulty":3,"kind":"mc","stem":"자석의 성질을 이용한 첨단 과학 기술이 아닌 것은 무엇인가요?","options":[{"t":"햇빛을 모아 전기를 만드는 판","correct":true},{"t":"우주 쓰레기를 모으는 장치","mis":"SC4-1-u1-X47"},{"t":"몸속을 살피는 작은 로봇","mis":"SC4-1-u1-X48"},{"t":"지폐의 자석 잉크","mis":"SC4-1-u1-X49"}],"explanation":["자석을 쓰는지 봐요.","햇빛이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#23','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C21',4,'mc','auto','친구가 「막대자석이 두 동강 나서 이제 극이 하나씩밖에 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X25','SC4-1-u1-X26']::text[],false,'{"seq":23,"concept":"SC4-1-u1-C21","difficulty":4,"kind":"mc","stem":"친구가 「막대자석이 두 동강 나서 이제 극이 하나씩밖에 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「두 조각 모두 양쪽 끝에 N극과 S극이 있는 자석이야. 클립으로 확인해 보자.」","correct":true},{"t":"「맞아, 한 조각은 N극, 한 조각은 S극뿐이야.」","mis":"SC4-1-u1-X25"},{"t":"「부러진 자석은 극이 모두 사라져.」","mis":"SC4-1-u1-X25"},{"t":"「빨간 조각에만 극이 남아.」","mis":"SC4-1-u1-X26"}],"explanation":["극은 항상 두 개예요.","새 자석이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#24','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C39',4,'mc','auto','철 캔과 알루미늄 캔이 섞인 분리수거함에서 자석을 이용해 캔을 나누는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X51','SC4-1-u1-X08','SC4-1-u1-X11']::text[],false,'{"seq":24,"concept":"SC4-1-u1-C39","difficulty":4,"kind":"mc","stem":"철 캔과 알루미늄 캔이 섞인 분리수거함에서 자석을 이용해 캔을 나누는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"자석을 가까이 해 붙는 캔은 철 캔으로, 붙지 않는 캔은 알루미늄 캔으로 나눈다","correct":true},{"t":"자석에 붙는 캔을 알루미늄 캔으로 나눈다","mis":"SC4-1-u1-X51"},{"t":"금속이니 모두 자석에 붙어 나눌 수 없다","mis":"SC4-1-u1-X08"},{"t":"캔 이름표만 보고 나눈다","mis":"SC4-1-u1-X11"}],"explanation":["철은 붙어요.","알루미늄은 안 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_c#25','sci',4,1,'u1','','g4_1_sci_u1_review_c','unit_review','SC4-1-u1-C25',4,'essay','teacher','햇살반 일지 ⑤를 보고 나침반을 바르게 쓰는 방법을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u1-C25","difficulty":4,"kind":"essay","stem":"햇살반 일지 ⑤를 보고 나침반을 바르게 쓰는 방법을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 나침반을 평평한 곳에 놓고 주변에 자석이 없는지 확인한 뒤 바늘이 멈출 때까지 기다린다. 나침반 바늘은 그냥 철이 아니라 N극에는 밀려나고 S극에는 끌려오는 자석이다.","scoring_points":["바르게 쓰는 방법을 썼는가","주변 자석을 확인해야 함을 썼는가","친구 나의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","방법을 써요.","고쳐 써요."],"asset":{"type":"passage","lines":["나침반을 평평한 책상에 놓고 바늘이 멈추길 기다렸다.","S극을 가까이 하니 빨간색 부분이 다가왔다.","자석을 치우니 바늘이 원래 방향으로 돌아갔다.","친구 나 — 「바늘은 그냥 철이야.」"],"title":"햇살반 일지 ⑤ 나침반"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#1','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C4',1,'mc','auto','자석 다트 핀이 과녁판에 붙는 까닭을 가장 알맞게 짐작한 친구의 말은 무엇인가요?',ARRAY['SC4-1-u1-X06','SC4-1-u1-X05']::text[],false,'{"seq":1,"concept":"SC4-1-u1-C4","difficulty":1,"kind":"mc","stem":"자석 다트 핀이 과녁판에 붙는 까닭을 가장 알맞게 짐작한 친구의 말은 무엇인가요?","options":[{"t":"「다트 핀과 과녁판이 서로 끌어당기는 것 같아.」","correct":true},{"t":"「과녁판이 끈적해서 붙는 것 같아.」","mis":"SC4-1-u1-X06"},{"t":"「다트 핀이 뾰족해서 꽂히는 것 같아.」","mis":"SC4-1-u1-X05"},{"t":"「바람이 밀어 주는 것 같아.」","mis":"SC4-1-u1-X06"}],"explanation":["착 붙어요.","서로 당기는 것 같아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#2','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C6',1,'mc','auto','자석에 붙지 않는 물질은 무엇인가요?',ARRAY['SC4-1-u1-X10']::text[],false,'{"seq":2,"concept":"SC4-1-u1-C6","difficulty":1,"kind":"mc","stem":"자석에 붙지 않는 물질은 무엇인가요?","options":[{"t":"고무","correct":true},{"t":"철","mis":"SC4-1-u1-X10"},{"t":"철로 된 집게의 쇠 부분","mis":"SC4-1-u1-X10"},{"t":"철 옷핀의 재료","mis":"SC4-1-u1-X10"}],"explanation":["철이 아닌 것을 찾아요.","지우개를 떠올려요.","고무예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#3','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C12',1,'mc','auto','자석과 철 클립 사이의 힘으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u1-X15','SC4-1-u1-X16','SC4-1-u1-X17']::text[],false,'{"seq":3,"concept":"SC4-1-u1-C12","difficulty":1,"kind":"mc","stem":"자석과 철 클립 사이의 힘으로 알맞은 것은 무엇인가요?","options":[{"t":"조금 떨어져 있어도 서로 끌어당긴다","correct":true},{"t":"꼭 닿아 있어야만 끌어당긴다","mis":"SC4-1-u1-X15"},{"t":"아무리 멀어도 끌어당긴다","mis":"SC4-1-u1-X16"},{"t":"사이에 종이가 있으면 끌어당기지 않는다","mis":"SC4-1-u1-X17"}],"explanation":["공중에 뜬 클립을 떠올려요.","닿지 않아도 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#4','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C18',1,'mc','auto','말굽자석의 극은 몇 개인가요?',ARRAY['SC4-1-u1-X21']::text[],false,'{"seq":4,"concept":"SC4-1-u1-C18","difficulty":1,"kind":"mc","stem":"말굽자석의 극은 몇 개인가요?","options":[{"t":"두 개","correct":true},{"t":"한 개","mis":"SC4-1-u1-X21"},{"t":"네 개","mis":"SC4-1-u1-X21"},{"t":"극이 없다","mis":"SC4-1-u1-X21"}],"explanation":["모양과 상관없어요.","항상 같아요.","두 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#5','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C25',1,'mc','auto','나침반 가까이에 자석을 두면 안 되는 까닭은 무엇인가요?',ARRAY['SC4-1-u1-X32','SC4-1-u1-X28','SC4-1-u1-X33']::text[],false,'{"seq":5,"concept":"SC4-1-u1-C25","difficulty":1,"kind":"mc","stem":"나침반 가까이에 자석을 두면 안 되는 까닭은 무엇인가요?","options":[{"t":"바늘이 자석의 영향을 받아 정확한 방향을 가리키지 못하기 때문에","correct":true},{"t":"나침반이 자석을 녹이기 때문에","mis":"SC4-1-u1-X32"},{"t":"바늘이 철로 변하기 때문에","mis":"SC4-1-u1-X28"},{"t":"자석이 방향을 알려 주기 때문에","mis":"SC4-1-u1-X33"}],"explanation":["바늘도 자석이에요.","영향을 받아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#6','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C30',1,'mc','auto','자석 양치 컵 걸이에 컵을 매달아 두면 무엇이 잘 생기지 않나요?',ARRAY['SC4-1-u1-X38']::text[],false,'{"seq":6,"concept":"SC4-1-u1-C30","difficulty":1,"kind":"mc","stem":"자석 양치 컵 걸이에 컵을 매달아 두면 무엇이 잘 생기지 않나요?","options":[{"t":"물때나 곰팡이","correct":true},{"t":"컵의 손잡이","mis":"SC4-1-u1-X38"},{"t":"칫솔의 털","mis":"SC4-1-u1-X38"},{"t":"치약","mis":"SC4-1-u1-X38"}],"explanation":["물이 고이지 않아요.","깨끗해요.","물때나 곰팡이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#7','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C33',1,'mc','auto','자석 식탁의 편리한 점은 무엇인가요?',ARRAY['SC4-1-u1-X46']::text[],false,'{"seq":7,"concept":"SC4-1-u1-C33","difficulty":1,"kind":"mc","stem":"자석 식탁의 편리한 점은 무엇인가요?","options":[{"t":"철 그릇이나 수저를 쳐도 떨어지거나 쓰러지지 않는다","correct":true},{"t":"나무 그릇이 식탁에 붙는다","mis":"SC4-1-u1-X46"},{"t":"음식이 저절로 따뜻해진다","mis":"SC4-1-u1-X46"},{"t":"식탁이 가벼워진다","mis":"SC4-1-u1-X46"}],"explanation":["식탁에 자석이 있어요.","철 그릇이 붙어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#8','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C38',1,'mc','auto','지폐에 쓰이는 자석 잉크는 무엇으로 만들었나요?',ARRAY['SC4-1-u1-X49']::text[],false,'{"seq":8,"concept":"SC4-1-u1-C38","difficulty":1,"kind":"mc","stem":"지폐에 쓰이는 자석 잉크는 무엇으로 만들었나요?","options":[{"t":"액체 자석","correct":true},{"t":"나무 가루","mis":"SC4-1-u1-X49"},{"t":"고무","mis":"SC4-1-u1-X49"},{"t":"유리","mis":"SC4-1-u1-X49"}],"explanation":["흐르는 자석이에요.","잉크가 돼요.","액체 자석이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#9','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C4',2,'match','auto','자석을 써 본 곳과 쓰는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC4-1-u1-C4","difficulty":2,"kind":"match","stem":"자석을 써 본 곳과 쓰는 모습을 알맞게 이으세요.","pairs":[{"l":"칠판의 이름표","r":"이름표를 붙였다 떼어요"},{"l":"칠판의 시간표","r":"시간표를 붙여 두어요"},{"l":"냉장고 문","r":"메모를 붙여 두어요"},{"l":"과녁판","r":"다트 핀이 착 붙어요"}],"mis":"SC4-1-u1-X06","explanation":["자석을 써 본 곳이에요.","붙여 두어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#10','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C11',2,'sa','auto','철 구슬과 플라스틱 구슬이 섞여 있을 때, 철 구슬만 쉽게 골라내려면 무엇을 쓰면 좋을까요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u1-C11","difficulty":2,"kind":"sa","stem":"철 구슬과 플라스틱 구슬이 섞여 있을 때, 철 구슬만 쉽게 골라내려면 무엇을 쓰면 좋을까요? 두 글자로 쓰세요.","answer":["자석"],"explanation":["철은 붙어요.","플라스틱은 안 붙어요.","자석이에요."],"mis":"SC4-1-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#11','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C15',2,'match','auto','상황과 알 수 있는 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC4-1-u1-C15","difficulty":2,"kind":"match","stem":"상황과 알 수 있는 점을 알맞게 이으세요.","pairs":[{"l":"가벼운 클립이 자석 쪽으로 끌려 와요","r":"자석이 클립을 끌어당겨요"},{"l":"무거운 철 문 쪽으로 손이 끌려가요","r":"철도 자석을 끌어당겨요"},{"l":"사이에 색종이를 넣어도 클립이 떠 있어요","r":"종이가 있어도 힘이 작용해요"},{"l":"자석을 아주 멀리 하니 클립이 떨어져요","r":"너무 멀면 힘이 미치지 못해요"}],"mis":"SC4-1-u1-X18","explanation":["상황을 읽어요.","무엇을 알 수 있나요?","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#12','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C18',2,'sa','auto','막대자석의 양쪽 끝에 있는 두 극 가운데 하나는 N극이에요. 다른 하나는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"SC4-1-u1-C18","difficulty":2,"kind":"sa","stem":"막대자석의 양쪽 끝에 있는 두 극 가운데 하나는 N극이에요. 다른 하나는 무엇인가요? 두 글자로 쓰세요.","answer":["S극"],"explanation":["극은 두 개예요.","N극과 짝이에요.","S극이에요."],"mis":"SC4-1-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#13','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C23',2,'match','auto','자석을 움직인 모습과 바늘의 빨간색 부분을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC4-1-u1-C23","difficulty":2,"kind":"match","stem":"자석을 움직인 모습과 바늘의 빨간색 부분을 알맞게 이으세요.","pairs":[{"l":"S극을 가까이 했어요","r":"S극 쪽으로 다가와요"},{"l":"N극을 가까이 했어요","r":"N극에서 멀어져요"},{"l":"자석을 치웠어요","r":"원래 방향으로 돌아가요"},{"l":"S극을 나침반 주변에서 돌렸어요","r":"계속 S극 쪽을 따라가요"}],"mis":"SC4-1-u1-X30","explanation":["빨간색은 N극이에요.","규칙은 같아요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#14','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C27',2,'match','auto','생활용품과 이용한 자석의 성질을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC4-1-u1-C27","difficulty":2,"kind":"match","stem":"생활용품과 이용한 자석의 성질을 알맞게 이으세요.","pairs":[{"l":"자석 주방 기구 걸이","r":"자석이 철로 된 국자를 끌어당겨요"},{"l":"자석 드라이버","r":"자석이 철 나사못을 끌어당겨요"},{"l":"자석 창문 닦이","r":"안팎 자석의 다른 극끼리 끌어당겨요"},{"l":"자석 단추가 달린 가방","r":"두 단추 자석의 다른 극끼리 끌어당겨요"}],"mis":"SC4-1-u1-X36","explanation":["무엇과 무엇이 당기나요?","철 또는 자석이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#15','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C33',2,'match','auto','친구들이 설계한 장치와 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC4-1-u1-C33","difficulty":2,"kind":"match","stem":"친구들이 설계한 장치와 쓰임을 알맞게 이으세요.","pairs":[{"l":"자석 수저 받침대","r":"철 수저를 붙여 보관해요"},{"l":"자석 식탁","r":"그릇을 쳐도 잘 쓰러지지 않아요"},{"l":"자석 허리띠","r":"철 공구와 나사못을 붙여 다녀요"},{"l":"자석 이불","r":"갤 때 귀퉁이끼리 꼭 붙어요"}],"mis":"SC4-1-u1-X46","explanation":["장치 이름을 읽어요.","쓰임을 떠올려요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#16','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C39',2,'sa','auto','캔 분리수거 장치에서 자석에 붙는 캔은 무엇으로 만든 캔인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"SC4-1-u1-C39","difficulty":2,"kind":"sa","stem":"캔 분리수거 장치에서 자석에 붙는 캔은 무엇으로 만든 캔인가요? 한 글자로 쓰세요.","answer":["철"],"explanation":["자석에 붙는 물질이에요.","알루미늄은 아니에요.","철이에요."],"mis":"SC4-1-u1-X51"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#17','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C7',3,'mc','auto','「금속은 모두 자석에 붙는다.」는 말이 틀렸음을 보여 주는 물체는 무엇인가요?',ARRAY['SC4-1-u1-X10']::text[],false,'{"seq":17,"concept":"SC4-1-u1-C7","difficulty":3,"kind":"mc","stem":"「금속은 모두 자석에 붙는다.」는 말이 틀렸음을 보여 주는 물체는 무엇인가요?","options":[{"t":"알루미늄 캔","correct":true},{"t":"철 캔","mis":"SC4-1-u1-X10"},{"t":"철 옷핀","mis":"SC4-1-u1-X10"},{"t":"철 집게","mis":"SC4-1-u1-X10"}],"explanation":["금속인데 안 붙는 것이에요.","알루미늄이에요.","알루미늄 캔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#18','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C19',3,'mc','auto','막대자석 (가)의 S극과 막대자석 (나)의 S극을 마주 보게 가까이 하면 어떤 힘이 작용하나요?',ARRAY['SC4-1-u1-X22','SC4-1-u1-X23']::text[],false,'{"seq":18,"concept":"SC4-1-u1-C19","difficulty":3,"kind":"mc","stem":"막대자석 (가)의 S극과 막대자석 (나)의 S극을 마주 보게 가까이 하면 어떤 힘이 작용하나요?","options":[{"t":"서로 밀어 내는 힘","correct":true},{"t":"서로 끌어당기는 힘","mis":"SC4-1-u1-X22"},{"t":"아무 힘도 작용하지 않는다","mis":"SC4-1-u1-X23"},{"t":"S극끼리는 N극끼리와 달리 끌어당긴다","mis":"SC4-1-u1-X23"}],"explanation":["S극끼리예요.","같은 극이에요.","밀어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#19','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C24',3,'mc','auto','나침반 바늘의 빨간색 부분이 막대자석 쪽으로 다가왔어요. 막대자석의 어느 극을 가까이 했을까요?',ARRAY['SC4-1-u1-X29','SC4-1-u1-X28','SC4-1-u1-X20']::text[],false,'{"seq":19,"concept":"SC4-1-u1-C24","difficulty":3,"kind":"mc","stem":"나침반 바늘의 빨간색 부분이 막대자석 쪽으로 다가왔어요. 막대자석의 어느 극을 가까이 했을까요?","options":[{"t":"S극","correct":true},{"t":"N극","mis":"SC4-1-u1-X29"},{"t":"바늘은 어느 극에든 다가오니 알 수 없다","mis":"SC4-1-u1-X28"},{"t":"막대자석의 가운데","mis":"SC4-1-u1-X20"}],"explanation":["빨간색은 N극이에요.","다른 극에 다가와요.","S극이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#20','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C29',3,'mc','auto','자석 주방 기구 걸이에 붙여 보관할 수 없는 것은 무엇인가요?',ARRAY['SC4-1-u1-X10']::text[],false,'{"seq":20,"concept":"SC4-1-u1-C29","difficulty":3,"kind":"mc","stem":"자석 주방 기구 걸이에 붙여 보관할 수 없는 것은 무엇인가요?","options":[{"t":"나무 주걱","correct":true},{"t":"철 국자","mis":"SC4-1-u1-X10"},{"t":"철 뒤집개","mis":"SC4-1-u1-X10"},{"t":"철 집게","mis":"SC4-1-u1-X10"}],"explanation":["붙지 않는 물질을 찾아요.","나무예요.","나무 주걱이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#21','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C35',3,'mc','auto','자석 말판 놀이에서 「고무지우개, 플라스틱 단추, 철 집게 가운데 자석에 붙는 것은?」 칸에 멈췄어요. 알맞은 답은 무엇인가요?',ARRAY['SC4-1-u1-X09','SC4-1-u1-X08']::text[],false,'{"seq":21,"concept":"SC4-1-u1-C35","difficulty":3,"kind":"mc","stem":"자석 말판 놀이에서 「고무지우개, 플라스틱 단추, 철 집게 가운데 자석에 붙는 것은?」 칸에 멈췄어요. 알맞은 답은 무엇인가요?","options":[{"t":"철 집게","correct":true},{"t":"고무지우개","mis":"SC4-1-u1-X09"},{"t":"플라스틱 단추","mis":"SC4-1-u1-X09"},{"t":"셋 다 붙는다","mis":"SC4-1-u1-X08"}],"explanation":["철로 된 것이에요.","하나예요.","철 집게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#22','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C37',3,'mc','auto','로봇 캡슐을 삼키면 주사 대신 약을 전달할 수 있대요. 어떤 기술과 관계있나요?',ARRAY['SC4-1-u1-X47','SC4-1-u1-X51','SC4-1-u1-X49']::text[],false,'{"seq":22,"concept":"SC4-1-u1-C37","difficulty":3,"kind":"mc","stem":"로봇 캡슐을 삼키면 주사 대신 약을 전달할 수 있대요. 어떤 기술과 관계있나요?","options":[{"t":"몸 밖에서 조종하는 아주 작은 로봇 기술","correct":true},{"t":"우주 쓰레기 청소 기술","mis":"SC4-1-u1-X47"},{"t":"캔 분리수거 기술","mis":"SC4-1-u1-X51"},{"t":"액체 자석 잉크 기술","mis":"SC4-1-u1-X49"}],"explanation":["몸속이에요.","로봇이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#23','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C24',4,'mc','auto','친구가 「나침반 바늘은 철이라서 N극에도 S극에도 끌려와.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u1-X28','SC4-1-u1-X31','SC4-1-u1-X30']::text[],false,'{"seq":23,"concept":"SC4-1-u1-C24","difficulty":4,"kind":"mc","stem":"친구가 「나침반 바늘은 철이라서 N극에도 S극에도 끌려와.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「N극을 대면 빨간색 부분이 밀려나잖아. 바늘도 극이 있는 자석이야.」","correct":true},{"t":"「맞아, 바늘은 철이야.」","mis":"SC4-1-u1-X28"},{"t":"「빨간색 부분은 S극이라 그래.」","mis":"SC4-1-u1-X31"},{"t":"「바늘은 자석과 상관없이 움직여.」","mis":"SC4-1-u1-X30"}],"explanation":["밀려나는 모습이에요.","철은 밀려나지 않아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#24','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C32',4,'mc','auto','쓰러지지 않는 물통에 붓을 보관하는 기능을 더하려고 해요. 가장 알맞은 설계는 무엇인가요?',ARRAY['SC4-1-u1-X44','SC4-1-u1-X45']::text[],false,'{"seq":24,"concept":"SC4-1-u1-C32","difficulty":4,"kind":"mc","stem":"쓰러지지 않는 물통에 붓을 보관하는 기능을 더하려고 해요. 가장 알맞은 설계는 무엇인가요?","options":[{"t":"붓 손잡이에 철 조각을 붙이고 물통 옆면에 자석을 붙인다","correct":true},{"t":"붓 손잡이에 고무를 붙이고 물통 옆면에 자석을 붙인다","mis":"SC4-1-u1-X44"},{"t":"붓을 물통 속에 넣어 둔다","mis":"SC4-1-u1-X45"},{"t":"물통 옆면에 나무 조각만 붙인다","mis":"SC4-1-u1-X44"}],"explanation":["붓이 붙어야 해요.","철과 자석이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u1_review_d#25','sci',4,1,'u1','','g4_1_sci_u1_review_d','unit_review','SC4-1-u1-C27',4,'essay','teacher','햇살반 일지 ⑥의 생활용품 두 가지를 골라 이용한 자석의 성질과 편리한 점을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u1-C27","difficulty":4,"kind":"essay","stem":"햇살반 일지 ⑥의 생활용품 두 가지를 골라 이용한 자석의 성질과 편리한 점을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 자석 클립 통은 자석과 철 클립이 서로 끌어당기는 성질을 이용해 통이 떨어져도 클립이 쏟아지지 않는다. 자석 창문 닦이는 다른 극끼리 끌어당기는 성질을 이용해 유리창 안쪽과 바깥쪽을 함께 닦을 수 있다. 나무는 자석에 붙지 않으므로 자석 걸이에는 자석에 붙는 물체만 붙일 수 있다.","scoring_points":["두 가지의 성질을 바르게 썼는가","편리한 점을 썼는가","친구 다의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","두 가지를 골라요.","고쳐 써요."],"asset":{"type":"passage","lines":["자석 클립 통 — 뚜껑에 자석이 있다.","자석 창문 닦이 — 안쪽과 바깥쪽에 자석이 있다.","자석 양치 컵 걸이 — 컵 바닥에 자석이 있다.","친구 다 — 「자석 걸이에 나무 주걱도 붙여 보자.」"],"title":"햇살반 일지 ⑥ 자석을 이용한 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
